  const DONE_KEY = "mandala-done-v2";
  const OLD_TASKS_KEY = "mandala-tasks-v1";
  const OLD_DONE_KEY = "mandala-done-v1";
  const SETTINGS_KEY = "mandala-settings-v1";
  const CHAT_KEY = "mandala-chat-v1";
  const THEME_KEY = "mandala-theme-v1";
  const NOTIFY_KEY = "mandala-notify-v1";
  const DRAFT_PLAN_KEY = "mandala-draft-plan-v1";
  const CONV_TPL_KEY = "mandala-conv-templates-v1";
  const CHECKLIST_KEY = "mandala-checklists-v1";
  const ACCENT_KEY = "mandala-accent-v1";
  const REPEAT_KEY = "mandala-repeats-v1";
  const INPUT_HISTORY_KEY = "mandala-input-history-v1";
  // 天地人三才：记录页数据 & 复盘页数据
  const RECORD_KEY = "mandala-records-v1";
  const REVIEW_KEY = "mandala-reviews-v1";
  // 记录笔记本（按日期自由笔记）& 持续记录开关 & 持续事项
  const NOTE_KEY = "mandala-record-notes-v1";
  const AUTO_RECORD_KEY = "mandala-autorecord-v1";
  const ONGOING_KEY = "mandala-ongoing-v1";
  // ❓ 提问解析库：导入的问题库 + 逐问作答进度
  const QA_KEY = "mandala-qabank-v1";
  // 截图/图片附件（用 IndexedDB，localStorage 装不下大图）
  const ATTACH_DB_NAME = "mandala-attachments";
  const ATTACH_DB_VERSION = 1;
  const ATTACH_STORE = "files";
  // 长期任务（时间地图）数据
  const LONGTASK_KEY = "mandala-longtasks-v1";
  // Hermes 同步的总结/规划/洞察（L3 add_hermes_note 写入）
  const HERMES_NOTES_KEY = "mandala-hermes-notes-v1";
  // Hermes 触发的 PWA 动作队列（L3 trigger_action 写入，pullSync 拉取后消费）
  const ACTIONS_KEY = "mandala-actions-v1";
  // 任务孵化历史（完成率闭环用）
  const HATCH_HISTORY_KEY = "mandala-hatch-history-v1";

  // ---------- 知识评估 7 维度 ----------
  // 标准 编号前缀 - 子维度 - 核心追问
  const KNOWLEDGE_DIMENSIONS = [
    { code: "Cl", name: "清晰度", color: "#7c5cff",
      subs: [
        { key: "def", name: "定义清晰度", q: "能用一句话说清这个知识是什么吗？" },
        { key: "boundary", name: "边界清晰度", q: "能说清它和相似知识的区别吗？" },
        { key: "repr", name: "表征清晰度", q: "能用图形、比喻、口诀等多种方式表达它吗？" },
      ]},
    { code: "Cp", name: "完整性", color: "#4ade80",
      subs: [
        { key: "structure", name: "结构完整度", q: "有没有遗漏的子知识？根干枝叶齐全吗？" },
        { key: "steps", name: "步骤完整度", q: "操作链的每一步都能闭卷写出来吗？" },
      ]},
    { code: "B", name: "边界感", color: "#fbbf24",
      subs: [
        { key: "condition", name: "适用条件", q: "在什么条件下能用？" },
        { key: "fail", name: "失效条件", q: "在什么条件下会出错？" },
        { key: "limit", name: "极限测试", q: "推到极端参数还成立吗？" },
      ]},
    { code: "L", name: "关联度", color: "#60a5fa",
      subs: [
        { key: "upstream", name: "上下游关联", q: "它的前置知识和后续应用是什么？" },
        { key: "isomorphic", name: "同构关联", q: "和哪个知识共享相同的底层骨架？" },
        { key: "crossdomain", name: "跨域关联", q: "能迁移到其他领域或生活中吗？" },
      ]},
    { code: "Ev", name: "进化感", color: "#f87171",
      subs: [
        { key: "version", name: "版本追溯", q: "和过去比，理解变深了吗？" },
        { key: "iteration", name: "迭代方向", q: "下一步该修正、升级还是淘汰？" },
      ]},
    { code: "P", name: "精炼度", color: "#34d399",
      subs: [
        { key: "chunk", name: "组块紧凑度", q: "能压缩成多短的口诀？" },
        { key: "fluency", name: "执行流畅度", q: "能自动执行还是需要刻意回忆？" },
      ]},
    { code: "Rh", name: "节奏感", color: "#a78bfa",
      subs: [
        { key: "cycle", name: "周期", q: "固定多久检索一次？" },
        { key: "freq", name: "频率", q: "练习频率够高吗？" },
        { key: "predict", name: "预测", q: "能预判自己会在哪卡住吗？" },
        { key: "duration", name: "时长", q: "每次训练的时长合理吗？" },
        { key: "timing", name: "时机", q: "在什么状态下训练效果最好？" },
      ]},
  ];

  // 生成本维度空评估对象 { def:0, boundary:0, ... }
  function emptyEval() {
    const o = {};
    KNOWLEDGE_DIMENSIONS.forEach((d) => d.subs.forEach((s) => { o[s.key] = 0; }));
    return o;
  }

  // 计算某维度平均分（0-5）
  function dimScore(evalObj, dim) {
    const vals = dim.subs.map((s) => evalObj[s.key] || 0);
    return vals.reduce((a, b) => a + b, 0) / vals.length;
  }

  // 7 维度 × 子维度 完整体系文本（注入 AI prompt，供 basic 孵化/对话诊断复用）
  // 每行：编码 维度名：子维度key(子维度名)·核心追问，逗号分隔
  function buildDimListText() {
    return KNOWLEDGE_DIMENSIONS.map((d) =>
      `  - ${d.code} ${d.name}：${d.subs.map((s) => `${d.code}.${s.key}(${s.name})·${s.q}`).join(" / ")}`
    ).join("\n");
  }

  // 压缩版维度列表（只列编码与子维度名，省略核心追问，供拆解 prompt 使用，省 ~40% token）
  function buildDimListCompact() {
    return KNOWLEDGE_DIMENSIONS.map((d) =>
      `  - ${d.code} ${d.name}：${d.subs.map((s) => `${d.code}.${s.key}(${s.name})`).join(" / ")}`
    ).join("\n");
  }

  // 文本截断（单条上下文压缩用，按字符截断保留语义头）
  function trunc(s, n) {
    s = String(s == null ? "" : s).replace(/\s+/g, " ").trim();
    return s.length > n ? s.slice(0, n) + "…" : s;
  }

  // ---------- 截图/图片附件（IndexedDB 封装）----------
  // 附件存储：key = `${date}|${period}-${cell}|${attachId}`，value = { id, blob, thumb, createdAt, mime, name }
  let _attachDB = null;
  function attachDB() {
    if (_attachDB) return Promise.resolve(_attachDB);
    return new Promise((resolve, reject) => {
      const req = indexedDB.open(ATTACH_DB_NAME, ATTACH_DB_VERSION);
      req.onupgradeneeded = (e) => {
        const db = e.target.result;
        if (!db.objectStoreNames.contains(ATTACH_STORE)) {
          const store = db.createObjectStore(ATTACH_STORE, { keyPath: "id" });
          store.createIndex("byCell", "cellKey", { unique: false });
        }
      };
      req.onsuccess = (e) => { _attachDB = e.target.result; resolve(_attachDB); };
      req.onerror = () => reject(req.error);
    });
  }
  // cellKey 格式：`${date}|${period}-${cell}`
  function attachCellKey(period, cell, date) {
    return `${date || state.currentDate}|${period}-${cell}`;
  }
  async function attachSave(cellKey, blob, name, mime) {
    const db = await attachDB();
    const thumb = await makeThumb(blob, mime);
    const rec = {
      id: cellKey + "|" + Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
      cellKey,
      blob,
      thumb,
      mime: mime || blob.type || "image/png",
      name: name || ("截图-" + new Date().toLocaleTimeString("zh-CN")),
      createdAt: Date.now(),
    };
    return new Promise((resolve, reject) => {
      const tx = db.transaction(ATTACH_STORE, "readwrite");
      tx.objectStore(ATTACH_STORE).put(rec);
      tx.oncomplete = () => resolve(rec);
      tx.onerror = () => reject(tx.error);
    });
  }
  async function attachList(cellKey) {
    const db = await attachDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(ATTACH_STORE, "readonly");
      const idx = tx.objectStore(ATTACH_STORE).index("byCell");
      const req = idx.getAll(cellKey);
      req.onsuccess = () => resolve(req.result || []);
      req.onerror = () => reject(req.error);
    });
  }
  async function attachDelete(id) {
    const db = await attachDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(ATTACH_STORE, "readwrite");
      tx.objectStore(ATTACH_STORE).delete(id);
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
  }
  async function attachDeleteAll(cellKey) {
    const list = await attachList(cellKey);
    await Promise.all(list.map((r) => attachDelete(r.id)));
  }
  // 生成缩略图（dataURL，限制最大边 240px）
  function makeThumb(blob, mime) {
    return new Promise((resolve) => {
      try {
        const url = URL.createObjectURL(blob);
        const img = new Image();
        img.onload = () => {
          const maxSide = 240;
          let { width: w, height: h } = img;
          if (w > maxSide || h > maxSide) {
            const r = Math.min(maxSide / w, maxSide / h);
            w = Math.round(w * r); h = Math.round(h * r);
          }
          const canvas = document.createElement("canvas");
          canvas.width = w; canvas.height = h;
          const ctx = canvas.getContext("2d");
          ctx.drawImage(img, 0, 0, w, h);
          URL.revokeObjectURL(url);
          resolve(canvas.toDataURL(mime || "image/jpeg", 0.7));
        };
        img.onerror = () => { URL.revokeObjectURL(url); resolve(""); };
        img.src = url;
      } catch (e) { resolve(""); }
    });
  }
  // 读取 Blob 为 dataURL（用于预览大图）
  function blobToDataURL(blob) {
    return new Promise((resolve) => {
      const r = new FileReader();
      r.onload = () => resolve(r.result);
      r.onerror = () => resolve("");
      r.readAsDataURL(blob);
    });
  }

