        why: s.why,
        verify: s.verify,
        law: s.law,
        branch: "main", // 习惯是顺序链：6 步纵向推进（身份→提示→捆绑→两分钟→奖赏→追踪）
        parent_step: null,
        habitType: isBreak ? "break" : "build",
