  function sleep(ms) { return new Promise((r) => setTimeout(r, ms)); }

  // 全屏孵化 header 状态徽标
  function setHatchFsStatus(state, text) {
    if (!el.hatchFsStatus) return;
    el.hatchFsStatus.classList.remove("running", "done", "error");
    if (state) el.hatchFsStatus.classList.add(state);
    el.hatchFsStatus.textContent = text || "待命";
  }

  // 通用入口：打开孵化实验室，填入任务文本但不自动启动（等用户答完基石问询点「开始孵化」）
  function openHatchDialog(opts) {
    opts = opts || {};
    let text = opts.text || "";
    let longTaskId = opts.longTaskId || null;
    let scene = opts.scene || "auto";
    let sourceLabel = opts.sourceLabel || ""; // "长期任务" / "收集箱" / ""
    if (!text) {
      // 默认取当前任务弹窗第一行
      text = el.taskContent.value.split("\n").map((s) => s.trim()).filter(Boolean)[0] || "";
    }
    // 填入任务输入框（允许空，用户可在对话框里补填）
    if (el.hatchTaskInput) el.hatchTaskInput.value = text;
    if (el.hatchTaskText) el.hatchTaskText.textContent = text || "—";
    el.hatchMode.value = "auto";
    el.hatchScene.value = scene;
    el.hatchProgress.hidden = true;
    el.hatchResult.hidden = true;
    el.hatchError.hidden = true;
    el.hatchHistoryHint.hidden = true;
    if (el.hatchHistoryPanel) el.hatchHistoryPanel.hidden = true;
    // 显示问询面板（重置为初始状态：显示生成按钮，隐藏问题区）
    if (el.hatchOnboard) el.hatchOnboard.hidden = false;
    if (el.hatchOnboard) el.hatchOnboard.classList.remove("collapsed");
    if (el.hatchOnboardGen) el.hatchOnboardGen.hidden = false;
    if (el.hatchOnboardQs) el.hatchOnboardQs.innerHTML = "";
    // 「开始孵化」常显：问询可跳过，不想答直接孵（卡点：以前必须先生成问题才能开始）
    if (el.hatchOnboardActions) el.hatchOnboardActions.hidden = false;
    if (el.hatchRegenBtn) el.hatchRegenBtn.hidden = true; // 还没有问题，隐藏「重新问询」
    if (el.hatchGenBtn) el.hatchGenBtn.disabled = false;
    if (el.hatchGenTip) el.hatchGenTip.textContent = "填好任务后点此，AI 会针对你的任务提 5-7 个关键问题（含 7 维度子维度）";
    hatchState.onboardQuestions = [];
    // 记录 longTaskId 供启动时用
    hatchState.longTaskId = longTaskId;
    hatchState.pendingScene = scene;
    // 更新 header 副标题（来源标识）
    if (el.hatchFsSubtitle) {
      el.hatchFsSubtitle.textContent = sourceLabel
        ? `${sourceLabel} · AI 实时拆解为可执行子步骤`
        : "AI 实时拆解任务为可执行子步骤";
    }
    setHatchFsStatus("", "待命");
    el.hatchDialog.showModal();
    // 自动聚焦任务输入框（若为空）
    if (!text && el.hatchTaskInput) setTimeout(() => el.hatchTaskInput.focus(), 100);
  }

  // 内置 7 维度+子维度引导问题模板（0 token，无 AI 也能按 7 维度提问）
  // 子维度轮换：每轮生成换一组子维度，多次「重新问询」可覆盖全部 20 个子维度（持久化计数）
  let tmplSubRotate = parseInt(load("mandala-tmpl-sub-rotate", "0"), 10) || 0;
  // 全部 20 个子维度的作答引导 hint
  const SUB_HINTS = {
    "Cl.def": "把模糊词换成具体对象：什么、给谁、做到什么程度。",
    "Cl.boundary": "说清它和相似概念的区别，划出「不是什么」的边界。",
    "Cl.repr": "试着用比喻、图形或口诀换一种方式表达它。",
    "Cp.structure": "列全组成部分，检查有没有漏掉的关键环节。",
    "Cp.steps": "闭卷走一遍操作链，看哪一步会卡壳。",
    "B.condition": "写出适用条件，每条配一个真实场景。",
    "B.fail": "想想什么情况下会出错、为什么会错。",
    "B.limit": "推到极端情况，看它还成不成立。",
    "L.upstream": "它依赖什么上游、又能支撑什么下游，别孤立地做。",
    "L.isomorphic": "找一个和它共享相同底层骨架的知识，对比结构。",
    "L.crossdomain": "它能迁移到别的领域或日常生活里吗？举一例。",
    "Ev.version": "对比过去/现在的理解，看深化在哪个点。",
    "Ev.iteration": "第一版 60 分就够，想好下一步怎么迭代升级。",
    "P.chunk": "把大目标切成 30 分钟能完成的小块和短口诀。",
    "P.fluency": "区分哪些已自动化、哪些还需要刻意回忆。",
    "Rh.cycle": "固定检索周期：多久回顾一次才不会忘？",
    "Rh.freq": "练习频率够不够支撑巩固？",
    "Rh.predict": "预判自己会在哪卡住，提前想好对策。",
    "Rh.duration": "单次训练时长是否在专注力范围内？",
    "Rh.timing": "什么状态下练效果最好（精力/场景/时段）？",
  };
  function buildTemplateOnboardQuestions(taskText) {
    const t = (taskText || "").trim();
    const dims = KNOWLEDGE_DIMENSIONS;
    // 每个子维度的核心追问模板
    const subQ = (dimCode, subKey) => {
      const d = dims.find((x) => x.code === dimCode);
      if (!d) return "";
      const s = d.subs.find((x) => x.key === subKey);
      return s ? s.q : "";
    };
    // 用 HATCH_DIM_TEMPLATES 作为子维度问题模板（已针对任务填空）
    const tmpl = HATCH_DIM_TEMPLATES;
    // 基础 4 问（本质/必要前提/第一性原理/成功标准）+ 7 维度各挑核心子维度
    // mode 标注三问式：orient 导向型·现象定位 / analyze 解析型·内部拆解 / test 实验型·验证修复
    const questions = [
      { label: "本质", question: `用一句话说清「${t}」的核心本质是什么？`, hint: "别急着写做法，先想清楚这件事到底要解决谁的什么问题。", dim: "", sub: "", mode: "analyze" },
      { label: "必要前提", question: `完成「${t}」需要哪些前置条件或基础？现在缺什么？`, hint: "盘点手上已有的资源/信息/工具，以及还缺什么才能开始。", dim: "", sub: "", mode: "orient" },
      { label: "第一性原理", question: `「${t}」最底层的原理/不可再分的要素是什么？`, hint: "抛开现有做法，回到最根本的规律：这件事本质依赖什么？", dim: "", sub: "", mode: "analyze" },
      { label: "成功标准", question: `怎样算「${t}」成功完成？可量化的标准是什么？`, hint: "想想完成后谁能验收、用什么指标证明做到了。", dim: "", sub: "", mode: "test" },
    ];
    // 7 维度：每维度按轮换索引挑子维度（多次重新生成 → 覆盖全部 20 个子维度）
    // 轮换奇偶交替问式：偶数轮出「解析型核心问」，奇数轮出「实验型验证问」（带判据）
    const dimCodes = ["Cl", "Cp", "B", "L", "Ev", "P", "Rh"];
    const useTest = tmplSubRotate % 2 === 1;
    dimCodes.forEach((code, i) => {
      const d = dims.find((x) => x.code === code);
      if (!d || !d.subs.length) return;
      const sub = d.subs[(tmplSubRotate + i) % d.subs.length];
      const key = `${code}.${sub.key}`;
      const tmplFn = useTest ? (HATCH_DIM_TEST_TEMPLATES[key] || tmpl[key]) : tmpl[key];
      const fallback = subQ(code, sub.key);
      questions.push({
        label: `${d.name}${code}`,
        question: tmplFn ? tmplFn(t) : (fallback ? fallback.replace(/知识/g, `「${t}」`) : `关于「${t}」的 ${d.name}·${sub.name}`),
        hint: useTest ? (SUB_TEST_HINTS[key] || SUB_HINTS[key] || sub.q) : (SUB_HINTS[key] || sub.q),
        dim: code,
        sub: sub.key,
        mode: useTest ? "test" : "analyze",
      });
    });
    // 轮换推进（下一次生成覆盖新的子维度组合 + 问式交替）
    tmplSubRotate = (tmplSubRotate + 1) % 60; // 60 > 最大子维度数，保证完整循环
    save("mandala-tmpl-sub-rotate", String(tmplSubRotate));
    return questions;
  }

  // AI 根据任务生成针对性基石问题
  async function generateOnboardQuestions() {
    const text = (el.hatchTaskInput ? el.hatchTaskInput.value : "").trim();
    if (!text) {
      toast("请先填写任务描述", "error");
      if (el.hatchTaskInput) el.hatchTaskInput.focus();
      return;
    }
    if (!state.settings.apiUrl || !state.settings.apiKey) {
      // 无 AI 时使用内置 7 维度模板（0 token，保证按 7 维度+子维度提问）
      const tmplQs = buildTemplateOnboardQuestions(text);
      toast("未配置 AI API，使用内置 7 维度模板提问", "info");
      renderOnboardQuestions(tmplQs);
      if (el.hatchOnboardGen) el.hatchOnboardGen.hidden = true;
      if (el.hatchOnboardActions) el.hatchOnboardActions.hidden = false;
      if (el.hatchOnboardTip) el.hatchOnboardTip.textContent = `💡 内置 7 维度模板生成了 ${tmplQs.length} 个问题，答完点「开始孵化」`;
      toast(`已生成 ${tmplQs.length} 个 7 维度问题`, "success");
      return;
    }
    if (el.hatchGenBtn) el.hatchGenBtn.disabled = true;
    if (el.hatchGenTip) el.hatchGenTip.innerHTML = '<span class="hatch-gen-loading">⏳ AI 正在分析任务并生成问题…</span>';
    try {
      const dimList = KNOWLEDGE_DIMENSIONS.map((d) =>
        `   - ${d.code} ${d.name}：${d.subs.map((s) => s.name).join(" / ")}`
      ).join("\n");
      const prompt = `你是一位经验丰富的任务拆解教练。你不是在机械提问，而是在用「对话式引导」帮用户把模糊的念头变成清晰可执行的计划。请针对以下任务提出 8-10 个层层递进的「引导问题」。

任务：${text}

引导风格要求：
1. 问题口语化、自然，像教练在聊天中顺势追问，不要生硬地罗列术语
2. 每个问题带「hint」字段：用一句话告诉用户"为什么问这个、从哪个角度想、怎么答"（例如 hint: "想想你最终要交付什么，别人会怎么验收"）
3. 问题顺序要符合认知逻辑：先厘清目标与本质，再挖前提与障碍，再落到具体做法与验收，最后是时间与节奏
4. 必须覆盖 4 个基础维度（本质/必要前提/第一性原理/成功标准），再结合任务从「7 维度知识体系」挑 3-4 个最相关的维度（含子维度）深入追问：
${dimList}
5. 子维度核心追问参考（用于把问题问得更具体）：
${KNOWLEDGE_DIMENSIONS.map((d) => "   " + d.code + " → " + d.subs.map((s) => s.name + "：「" + s.q + "」").join("；")).join("\n")}
6. 问题要直击要害，但给足思考引导；用户能用 1-3 句话答完，不用写作文
7. 不要问"你想做什么"这种废话；直接切入具体细节，帮用户发现没想过的盲点
8. 【三问式深度】每个问题标注 mode 字段，问法按三层递进：
   - mode="orient"（导向型·现象定位）：问现状与表现——「现在实际是什么样？具体在哪发生？」
   - mode="analyze"（解析型·内部拆解）：问根源与机制——「为什么会这样？背后真正的障碍是什么？」
   - mode="test"（实验型·验证修复）：问验证与行动——「如果试一下 X，看 Y 指标，能否证明/修复？」
   基础 4 问以 orient/analyze 为主；7 维度问题中至少 2 个必须是 test 实验型（把「想明白」转成「做出来验证」），且 hint 里给出可观察的判据（看什么信号、多久见效）
9. test 实验型问题的 hint 必须包含：做什么小实验 + 看什么指标 + 成败判据（例如 hint: "今天用 25 分钟只做第 1 步，若能顺利启动就算验证通过"）

返回 JSON 数组，格式：[{"label":"本质","question":"问题文本","hint":"引导提示","dim":"Cl","sub":"def","mode":"orient"},...]
- label 从这 12 个里选：本质、必要前提、第一性原理、成功标准、约束、清晰度Cl、完整性Cp、边界感B、关联度L、进化感Ev、精炼度P、节奏感Rh
- 若选 7 维度问题，label 用「清晰度Cl」这种格式，dim 填对应代码（Cl/Cp/B/L/Ev/P/Rh），sub 填对应子维度 key（如 def/boundary/repr/structure/steps/condition/fail/limit/upstream/isomorphic/crossdomain/version/iteration/chunk/fluency/cycle/freq/predict/duration/timing），否则 dim 与 sub 都留空
- mode 必填：orient / analyze / test 三选一
- hint 必须具体、有引导性，不能是空话
- 只返回 JSON，不要任何解释`;

      const provider = state.settings.apiProvider || "openai";
      // 60s 超时保护：避免无反馈干等（痛点：网络差时一直转圈）
      hatchState.abortController = new AbortController();
      const genTimeout = setTimeout(() => { try { hatchState.abortController.abort(); } catch (e2) {} }, 60000);
      const resp = await fetch(state.settings.apiUrl, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": "Bearer " + state.settings.apiKey,
        },
        body: JSON.stringify({
          model: state.settings.apiModel,
          messages: [{ role: "user", content: prompt }],
          temperature: 0.4,
          max_tokens: 1600,
        }),
        signal: hatchState.abortController.signal,
      });
      clearTimeout(genTimeout);
      if (!resp.ok) throw new Error(formatApiError(resp.status, await resp.text().catch(() => "")));
      const data = await resp.json();
      const content = (data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content) || "";
      // 提取 JSON
      const jsonMatch = content.match(/\[[\s\S]*\]/);
      let questions = [];
      if (jsonMatch) {
        try { questions = JSON.parse(jsonMatch[0]); } catch (e) { /* fallback */ }
      }
      if (!Array.isArray(questions) || questions.length === 0) throw new Error("未能解析问题");
      // 渲染问题
      renderOnboardQuestions(questions);
      if (el.hatchOnboardGen) el.hatchOnboardGen.hidden = true;
      if (el.hatchOnboardActions) el.hatchOnboardActions.hidden = false;
      if (el.hatchOnboardTip) el.hatchOnboardTip.textContent = `💡 AI 生成了 ${questions.length} 个问题，答完点「开始孵化」`;
      toast(`已生成 ${questions.length} 个针对性问题`, "success");
    } catch (e) {
      console.error("生成问询失败:", e);
      const aborted = e && (e.name === "AbortError" || /abort/i.test(e.message || ""));
      // AI 失败时 fallback 到内置 7 维度模板，保证按 7 维度+子维度提问
      const tmplQs = buildTemplateOnboardQuestions(text);
      if (!aborted && tmplQs && tmplQs.length) {
        renderOnboardQuestions(tmplQs);
        if (el.hatchOnboardGen) el.hatchOnboardGen.hidden = true;
        if (el.hatchOnboardActions) el.hatchOnboardActions.hidden = false;
        if (el.hatchOnboardTip) el.hatchOnboardTip.textContent = `⚠️ AI 生成失败（${aborted ? "超时" : e.message || "未知错误"}），已用内置 7 维度模板（${tmplQs.length} 问），答完点「开始孵化」`;
        toast("AI 失败，已用内置 7 维度模板", "info");
        return;
      }
      if (el.hatchGenTip) el.hatchGenTip.textContent = "❌ 生成失败：" + (aborted ? "请求超时（60s）" : (e.message || "未知错误")) + "，可重试或跳过直接孵化";
      if (el.hatchGenBtn) el.hatchGenBtn.disabled = false;
      // 生成失败时也保证「开始孵化」可用（可跳过问询）
      if (el.hatchOnboardActions) el.hatchOnboardActions.hidden = false;
      if (el.hatchOnboardTip) el.hatchOnboardTip.textContent = aborted
        ? "⚠️ AI 请求超时，可重试生成或直接开始孵化（无问询上下文）"
        : "⚠️ 问询生成失败，可直接开始孵化（无问询上下文）";
    } finally {
      hatchState.abortController = null;
      if (el.hatchGenBtn) el.hatchGenBtn.disabled = false;
    }
  }

  // 渲染动态问题到面板（带 7 维度+子维度徽章 + 引导提示 + 多行作答）
  function renderOnboardQuestions(questions) {
    if (!el.hatchOnboardQs) return;
    el.hatchOnboardQs.innerHTML = "";
    hatchState.onboardQuestions = questions;
    if (el.hatchOnboardActions) el.hatchOnboardActions.hidden = false;
    if (el.hatchRegenBtn) el.hatchRegenBtn.hidden = false; // 有问题了，可重新生成
    // 顶部进度条（已答 / 总数）
    const progressEl = document.createElement("div");
    progressEl.className = "hoq-progress";
    progressEl.id = "hoqProgress";
    progressEl.textContent = `📊 已答 0 / ${questions.length} 题 · 答完点「开始孵化」`;
    el.hatchOnboardQs.appendChild(progressEl);
    const updateProgress = () => {
      const all = [...el.hatchOnboardQs.querySelectorAll("textarea[data-hoq-idx]")];
      const answered = all.length - all.filter((t) => !t.value.trim()).length;
      const p = el.hatchOnboardQs.querySelector("#hoqProgress");
      if (p) p.textContent = `📊 已答 ${answered} / ${questions.length} 题 · 答完点「开始孵化」`;
      const tip = el.hatchOnboardTip;
      if (tip) tip.textContent = answered < questions.length
        ? `💡 已答 ${answered}/${questions.length}，答得越具体，AI 拆解越精准`
        : `✅ 全部答完！点「开始孵化」让 AI 基于你的答案拆解`;
    };
    questions.forEach((q, i) => {
      const div = document.createElement("div");
      div.className = "hatch-onboard-q";
      const num = ["①", "②", "③", "④", "⑤", "⑥", "⑦", "⑧", "⑨", "⑩"][i] || (i + 1) + ".";
      // 7 维度+子维度徽章（若有 dim 字段）
      let dimBadge = "";
      if (q.dim) {
        const dimObj = KNOWLEDGE_DIMENSIONS.find((d) => d.code === q.dim);
        const color = dimObj ? dimObj.color : "#7c5cff";
        const subObj = dimObj && q.sub ? dimObj.subs.find((s) => s.key === q.sub) : null;
        const subLabel = subObj ? subObj.name : (q.sub || "");
        dimBadge = `<span class="hoq-dim-badge" style="background:${color}22;color:${color};border-color:${color}44;" title="${subObj ? subObj.q : ""}">${q.dim}${subLabel ? "·" + subLabel : ""}</span>`;
      }
      // 三问式徽章（导向型·现象定位 / 解析型·内部拆解 / 实验型·验证修复）
      let modeBadge = "";
      if (q.mode) {
        const modeMeta = {
          orient: { txt: "导向", full: "导向型·现象定位：问现状与表现", color: "#9d85ff" },
          analyze: { txt: "解析", full: "解析型·内部拆解：问根源与机制", color: "#fbbf24" },
          test: { txt: "实验", full: "实验型·验证修复：用小实验验证并修复", color: "#2dd4bf" },
        }[String(q.mode).toLowerCase()] || null;
        if (modeMeta) modeBadge = `<span class="hoq-mode-badge" style="background:${modeMeta.color}22;color:${modeMeta.color};border-color:${modeMeta.color}44;" title="${modeMeta.full}">${modeMeta.txt}</span>`;
      }
      const hint = q.hint
        ? `<div class="hoq-hint">💬 ${escapeHtml(q.hint)}</div>`
        : "";
      div.innerHTML = `<label><span class="hoq-num">${num}</span> <span class="hoq-pos">${i + 1}/${questions.length}</span>${q.label || ""}：${dimBadge}${modeBadge}<span class="hoq-q">${q.question || ""}</span></label>${hint}
        <textarea data-hoq-idx="${i}" rows="2" placeholder="在这里写下你的思考…"></textarea>`;
      el.hatchOnboardQs.appendChild(div);
      // 自适应高度：输入时随内容增长，方便长作答
      const ta = div.querySelector("textarea");
      ta.addEventListener("input", () => {
        ta.style.height = "auto";
        ta.style.height = Math.min(ta.scrollHeight + 2, 160) + "px";
        updateProgress();
      });
    });
    updateProgress();
  }

  // 收集动态问题答案，拼成上下文喂给 AI
  function collectOnboardContext() {
    if (!el.hatchOnboardQs || !hatchState.onboardQuestions) return "";
    const inputs = el.hatchOnboardQs.querySelectorAll("textarea[data-hoq-idx]");
    const parts = [];
    inputs.forEach((inp) => {
      const idx = parseInt(inp.getAttribute("data-hoq-idx"), 10);
      const q = hatchState.onboardQuestions[idx];
      const ans = inp.value.trim();
      if (ans && q) {
        const dimObj = q.dim ? KNOWLEDGE_DIMENSIONS.find((d) => d.code === q.dim) : null;
        const subObj = dimObj && q.sub ? dimObj.subs.find((s) => s.key === q.sub) : null;
        const dimTag = q.dim ? `[${q.dim}${subObj ? "/" + subObj.name : ""}] ` : "";
        const modeName = { orient: "导向", analyze: "解析", test: "实验" }[String(q.mode || "").toLowerCase()] || "";
        const modeTag = modeName ? `[${modeName}] ` : "";
        parts.push(`${dimTag}${modeTag}【${q.label || "问" + (idx + 1)}】${q.question} → ${ans}`);
      }
    });
    return parts.join("\n");
  }

  // 从表单启动孵化（点击「开始孵化」按钮）
  function startHatchFromForm() {
    const text = (el.hatchTaskInput ? el.hatchTaskInput.value : "").trim();
    if (!text) {
      toast("请先填写要孵化的任务", "error");
      if (el.hatchTaskInput) el.hatchTaskInput.focus();
      return;
    }
    // 无 API 也能孵化：runHatch 内部会走本地启发式拆解降级
    // 收集问询作为额外上下文
    const onboardCtx = collectOnboardContext();
    const baseCtx = buildHatchContext();
    const fullCtx = [baseCtx, onboardCtx].filter(Boolean).join("\n\n");
    // 隐藏问询面板，进入孵化过程
    if (el.hatchOnboard) el.hatchOnboard.hidden = true;
    if (el.hatchTaskText) el.hatchTaskText.textContent = text;
    // 模式：尊重用户在下拉框的手动选择；仅 auto 时自动选档
    const mode = (el.hatchMode.value && el.hatchMode.value !== "auto")
      ? el.hatchMode.value
      : autoHatchMode(text);
    const scene = (hatchState.pendingScene && hatchState.pendingScene !== "auto")
      ? hatchState.pendingScene
      : detectHatchScene(text);
    el.hatchMode.value = mode;
    el.hatchScene.value = scene;
    setHatchFsStatus("running", "孵化中…");
    runHatch(text, mode, scene, fullCtx, hatchState.longTaskId, scene === "drill");
  }

  // 构建孵化上下文（今日已做 + 关联长期任务）
  function buildHatchContext() {
    const parts = [];
    const todayTasks = getCellTasks ? getDayTasks(state.currentDate) : null;
    if (todayTasks) {
      const doneCount = Object.values(getDayDone(state.currentDate) || {}).reduce((s, arr) => s + (Array.isArray(arr) ? arr.length : 0), 0);
      if (doneCount) parts.push(`今日已完成 ${doneCount} 项任务`);
    }
    return parts.join("；");
  }

  function closeHatchDialog() {
    if (hatchState.abortController) {
      try { hatchState.abortController.abort(); } catch (e) {}
    }
    if (el.hatchHistoryPanel) el.hatchHistoryPanel.hidden = true;
    el.hatchDialog.close();
  }

  // 加入清单：追加到 taskChecklist 末尾，保留原有内容
  // 带 target_dim 的步骤在行尾追加 ` #Cl.def→3#` 标记，saveTask 时解析为 item.dim
  function applyHatchToChecklist() {
    if (!hatchState.result || !hatchState.acceptedSet) return;
    const acceptedSteps = (hatchState.result.steps || [])
      .filter((_, i) => hatchState.acceptedSet.has(i));
    if (!acceptedSteps.length) {
      toast("未选择任何步骤", "info");
      return;
    }
    // 编码：纯文本步骤直接用；带 target_dim 的追加 ` #Dim.Sub→goal#`
    const newLines = acceptedSteps.map((s) => {
      let line = s.text;
      if (s.target_dim) {
        const goal = s.dim_goal ? `→${s.dim_goal}` : "";
        line += ` #${s.target_dim}${goal}#`;
      }
      return line;
    });
    const existing = el.taskChecklist.value.split("\n").map((s) => s.trim()).filter(Boolean);
    const before = existing.length;
    // 去重（按纯文本，忽略 dim 标记和完成前缀）
    const existingSet = new Set(existing.map((s) => s.replace(/^[☑☐✓√xX]\s*/, "").replace(/\s*#\w+\.\w+(→\d+)?#\s*$/, "")));
    const newOnes = newLines.filter((t) => !existingSet.has(t.replace(/\s*#\w+\.\w+(→\d+)?#\s*$/, "")));
    if (!newOnes.length) {
      toast("所选步骤已在清单中", "info");
      return;
    }
    el.taskChecklist.value = [...existing, ...newOnes].join("\n");
    // 记录历史（用于完成率闭环 + 回看孵化过程）
    const rawOutput = el.hatchStreamBody ? el.hatchStreamBody.textContent : "";
    recordHatchHistory(hatchState.taskHash, hatchState.taskText, hatchState.result, newOnes.length, { rawOutput });
    // 把 hatchHash 写到当前编辑格子的首个任务，使详情面板可回看孵化过程
    if (state.editingCell) {
      const cellTasks = getCellTasks(state.editingCell.period, state.editingCell.cell).slice();
      if (cellTasks.length) {
        cellTasks[0].hatchHash = hatchState.taskHash;
        setCellTasks(state.editingCell.period, state.editingCell.cell, cellTasks);
        renderTaskDetailPanel(cellTasks[0], state.editingCell.period, state.editingCell.cell);
      }
    }
    const dimCount = acceptedSteps.filter((s) => s.target_dim).length;
    toast(`已加入 ${newOnes.length} 条到清单${dimCount ? `（含 ${dimCount} 条维度练习）` : ""}`, "success");
    haptic([20, 40, 20]);
    closeHatchDialog();
  }

  // 安排到时间格子：把接受的步骤按 est_min 智能分配到当前时辰起的空格子
  function applyHatchToGrid() {
    if (!hatchState.result || !hatchState.acceptedSet) return;
    const acceptedSteps = (hatchState.result.steps || [])
      .filter((_, i) => hatchState.acceptedSet.has(i));
    if (!acceptedSteps.length) {
      toast("未选择任何步骤", "info");
      return;
    }
    // 每步占多少格（每格约 13.3 分钟，向上取整，最少 1 格）
    const cellsPerStep = acceptedSteps.map((s) => {
      const min = s.est_min || 15;
      return Math.max(1, Math.ceil(min / (SECONDS_PER_CELL / 60)));
    });
    const totalCells = cellsPerStep.reduce((a, b) => a + b, 0);

    // 从当前时辰的下一格开始找连续空位；不够则跨时辰；全天不够则提示
    let startGlobal = getCurrentGlobalCell();
    if (startGlobal < 0) startGlobal = 0; // 不在今天活跃时段，从第 1 格开始
    else startGlobal += 1; // 从当前格的下一格开始

    // 收集每个目标格子的 (period, cell) 和是否空闲
    const assignments = [];
    let cursor = startGlobal;
    let overflow = false;
    for (let i = 0; i < acceptedSteps.length; i++) {
      const need = cellsPerStep[i];
      // 找连续 need 个空格
      let placed = false;
      while (cursor + need - 1 < PERIOD_COUNT * CELLS_PER_PERIOD) {
        let allFree = true;
        for (let k = 0; k < need; k++) {
          const g = cursor + k;
          const p = Math.floor(g / CELLS_PER_PERIOD);
          const c = g % CELLS_PER_PERIOD;
          if (getCellTasks(p, c).length > 0) { allFree = false; break; }
        }
        if (allFree) {
          const step = acceptedSteps[i];
          // 第一格写入任务（带维度标记），后续格留空占位
          const firstG = cursor;
          const firstP = Math.floor(firstG / CELLS_PER_PERIOD);
          const firstC = firstG % CELLS_PER_PERIOD;
          let taskText = step.text;
          const meta = {};
          if (step.target_dim) {
            const goal = step.dim_goal ? `→${step.dim_goal}` : "";
            taskText += ` #${step.target_dim}${goal}#`;
            meta.dim = step.target_dim;
            if (step.dim_goal) meta.dimGoal = step.dim_goal;
          }
          if (step.est_min) meta.estimate = String(step.est_min);
          assignments.push({ period: firstP, cell: firstC, text: taskText, meta, stepIdx: i });
          // 占位的后续格（不写入任务，只标记跳过）
          for (let k = 1; k < need; k++) {
            const g = firstG + k;
            assignments.push({ period: Math.floor(g / CELLS_PER_PERIOD), cell: g % CELLS_PER_PERIOD, text: "", meta: null, placeholder: true, stepIdx: i });
          }
          cursor = firstG + need;
          placed = true;
          break;
        }
        cursor++; // 不连续，从下一格继续找
      }
      if (!placed) { overflow = true; break; }
    }

    if (!assignments.length || overflow) {
      toast(`今日剩余空格不足（需 ${totalCells} 格），请先清空格子或减少步骤`, "error");
      return;
    }

    // 实际写入（仅写有 text 的格子）
    let written = 0;
    const filledPeriods = new Set();
    assignments.forEach((a) => {
      if (a.placeholder || !a.text) return;
      setCellTasks(a.period, a.cell, [{ text: a.text, ...a.meta, hatchHash: hatchState.taskHash }]);
      filledPeriods.add(a.period);
      written++;
    });
    // 记录孵化历史
    const rawOutput = el.hatchStreamBody ? el.hatchStreamBody.textContent : "";
    recordHatchHistory(hatchState.taskHash, hatchState.taskText, hatchState.result, written, { rawOutput });

    // 跳转到第一个被填充的时辰
    if (filledPeriods.size) {
      const firstP = Math.min(...filledPeriods);
      state.activePeriod = firstP;
      setRealm("plan");
    }
    const dimCount = acceptedSteps.filter((s) => s.target_dim).length;
    toast(`已安排 ${written} 个任务到 ${filledPeriods.size} 个时辰${dimCount ? `（含 ${dimCount} 条维度练习）` : ""}`, "success");
    haptic([20, 40, 20]);
    closeHatchDialog();
    renderAll();
  }

  // 把孵化选中步骤拆成收集箱条目（每步一条，带维度/时长/风险标记）
  // 把孵化步骤自动拆分进收集箱（去重，返回新增条数）
  function autoHatchStepsToInbox(result) {
    if (!result || !Array.isArray(result.steps) || !result.steps.length) return 0;
    // 🏷 任务级标签：AI 返回的 result.tag 优先，否则从任务文本提炼（作为所有入箱条目的首 tag）
    const taskTag = (result.tag || suggestTag(result.taskText || hatchState.taskText || "")).trim();
    // 去重键：纯文本 + 维度
    const existingKeys = new Set(inboxItems.map((i) => `${(i.text || "").replace(/\s*#\w+(→\d+)?#\s*$/, "").trim()}|${(i.tags || []).join(",")}`));
    const pushItem = (s, parentId) => {
      if (!s || !s.text) return null;
      let taskText = s.text;
      const tags = [];
      if (taskTag) tags.push(taskTag);
      if (s.target_dim) {
        const goal = s.dim_goal ? `→${s.dim_goal}` : "";
        taskText += ` #${s.target_dim}${goal}#`;
        tags.push(s.target_dim);
      }
      const key = `${taskText.replace(/\s*#\w+(→\d+)?#\s*$/, "").trim()}|${tags.join(",")}`;
      if (existingKeys.has(key)) return null;
      existingKeys.add(key);
      const id = genId("inb");
      inboxItems.unshift({
        id,
        text: taskText,
        tags,
        mainline: null,
        sideline: null,
        parentId: parentId || null, // 支线/细化子步骤：挂在父任务下
        priority: 0,
        due: null,
        estimate: null,
        done: false,
        createdAt: Date.now(),
        kind: "hatch",
        meta: {
          source: "hatch",
          hatchTask: hatchState.taskText || "",
          hatchHash: hatchState.taskHash || "",
          dim: s.target_dim || "",
          dimGoal: s.dim_goal || null,
          estimate: s.est_min || 0,
          risk: s.risk || "",
          branch: s.branch || "main",
          parentStep: typeof s.parent_step === "number" ? s.parent_step : null,
        },
      });
      added++;
      return id;
    };
    let added = 0;
    // 第一遍：主线步骤入箱，记录 id（支线/子步骤据此挂父任务）
    const mainIds = new Map(); // step index -> inbox item id
    const sideSteps = [];
    result.steps.forEach((s, idx) => {
      if (s.branch === "side" && typeof s.parent_step === "number" && s.parent_step !== idx && result.steps[s.parent_step]) {
        sideSteps.push({ s, idx });
        return;
      }
      mainIds.set(idx, pushItem(s, null));
    });
    // 第二遍：支线步骤挂到对应主线步骤下（也记录支线 id，子步骤可挂支线）
    sideSteps.forEach(({ s, idx }) => {
      const pid = mainIds.get(s.parent_step) || null;
      mainIds.set(idx, pushItem(s, pid));
    });
    // 第三遍：细化子步骤（children）挂到父步骤下（主线/支线均可）
    result.steps.forEach((s) => {
      if (Array.isArray(s.children) && s.children.length) {
        const pid = mainIds.get(result.steps.indexOf(s)) || null;
        s.children.forEach((c) => pushItem(c, pid));
      }
    });
    if (added) saveInbox();
    return added;
  }

  // 🏷 同步已入箱条目的首标签（结果页改 tag 后，收集箱里该次孵化产出的条目 tags[0] 一起更新）
  function syncHatchInboxTags(newTag, oldTag, taskHash) {
    let changed = 0;
    inboxItems.forEach((it) => {
      if (!it.meta || it.meta.hatchHash !== taskHash) return;
      const tags = it.tags || [];
      if (tags[0] === oldTag || (oldTag && !tags[0] && tags.length)) {
        if (newTag) { tags[0] = newTag; changed++; }
      } else if (!tags[0] && newTag) {
        tags.unshift(newTag); changed++;
      }
    });
    if (changed) saveInbox();
    return changed;
  }

  function applyHatchToInbox() {
    if (!hatchState.result || !hatchState.acceptedSet) return;
    // acceptedSet 键：主线步骤为数字 index 字符串，支线为 "i_sideN"，子步骤为 "i_N"
    const result = hatchState.result;
    const steps = result.steps || [];
    const buildAccepted = () => {
      const accepted = [];
      const sideMap = new Map(); // parent idx -> [side step]
      steps.forEach((s, i) => {
        if (s.branch === "side" && typeof s.parent_step === "number" && s.parent_step !== i && steps[s.parent_step]) {
          if (!sideMap.has(s.parent_step)) sideMap.set(s.parent_step, []);
          sideMap.get(s.parent_step).push(s);
        } else if (hatchState.acceptedSet.has(String(i)) || hatchState.acceptedSet.has(i)) {
          accepted.push({ step: s, idx: i });
        }
      });
      sideMap.forEach((sides, pi) => {
        if (!(hatchState.acceptedSet.has(String(pi)) || hatchState.acceptedSet.has(pi))) return; // 父未选，支线不单放
        sides.forEach((sd) => { if (hatchState.acceptedSet.has(`${pi}_side${sides.indexOf(sd)}`)) accepted.push({ step: sd, idx: pi }); });
      });
      // 子步骤随父步骤一起入箱：保持嵌套结构（autoHatchStepsToInbox 第三遍会展开 children）
      return accepted.map(({ step }) => step);
    };
    const acceptedSteps = buildAccepted();
    if (!acceptedSteps.length) {
      toast("未选择任何步骤", "info");
      return;
    }
    const rawOutput = el.hatchStreamBody ? el.hatchStreamBody.textContent : "";
    // 复用公共去重入箱逻辑（按选中步骤）
    const added = autoHatchStepsToInbox({ steps: acceptedSteps });
    if (!added) {
      toast("所选步骤已在收集箱中", "info");
      return;
    }
    // 记录孵化历史
    recordHatchHistory(hatchState.taskHash, hatchState.taskText, result, added, { rawOutput });
    const dimCount = acceptedSteps.filter((s) => s.target_dim).length;
    toast(`已拆分 ${added} 条到收集箱${dimCount ? `（含 ${dimCount} 条维度练习）` : ""}，可拖拽到格子`, "success");
    haptic([20, 40, 20]);
    closeHatchDialog();
    // 直接打开收集箱，便于拖拽
    setTimeout(() => openInbox(), 200);
  }


  function formatHatchTime(ts) {
    if (!ts) return "—";
    const d = new Date(ts);
    const pad = (n) => String(n).padStart(2, "0");
    return `${d.getMonth() + 1}/${d.getDate()} ${pad(d.getHours())}:${pad(d.getMinutes())}`;
  }

  // 渲染孵化历史详情（用于格子任务回看）
  function renderHatchHistoryDetail(rec) {
    if (!rec) return '<div class="inbox-empty">无记录</div>';
    let html = `<div class="hatch-history-card">`;
    html += `<div class="hh-task">📝 ${escapeHtml(rec.task_text || "")}</div>`;
    html += `<div class="hh-meta">${rec.last_mode || ""} · ${rec.last_scene || ""} · ${rec.accepted_count || 0}/${rec.total_count || 0} 步 · 预估 ${rec.est_total_min || 0}min</div>`;
    // 完成度闭环：详情页也显示实际完成进度
    const prog = getHatchProgress(rec.task_hash);
    if (prog) {
      const pct = Math.round((prog.done / Math.max(prog.total, 1)) * 100);
      const doneCls = pct >= 100 ? "hh-prog-full" : (pct >= 50 ? "hh-prog-mid" : "hh-prog-low");
      html += `<div class="hh-prog ${doneCls}">
        <span class="hh-prog-label">实际完成 ${prog.done}/${prog.total}</span>
        <span class="hh-prog-bar"><span class="hh-prog-fill" style="width:${pct}%"></span></span>
        <span class="hh-prog-pct">${pct}%</span>
      </div>`;
    }
    if (rec.qa_pairs && rec.qa_pairs.length) {
      html += `<div class="hh-section"><div class="hh-section-title">🧠 引导问答（7维度）</div>`;
      rec.qa_pairs.forEach((qa) => {
        html += `<div class="hh-qa"><div class="hh-q"><span class="hh-dim-badge">${escapeHtml(qa.dim || "")}</span>${escapeHtml(qa.label || "")}：${escapeHtml(qa.question || "")}</div><div class="hh-a">${escapeHtml(qa.answer || "（未回答）")}</div></div>`;
      });
      html += `</div>`;
    }
    if (rec.steps && rec.steps.length) {
      html += `<div class="hh-section"><div class="hh-section-title">📋 拆解步骤（主线/支线）</div>`;
      // 主线/支线分组渲染（历史回看同样保留层级）
      const steps = rec.steps;
      const sideMap = new Map();
      steps.forEach((s, i) => {
        if (s.branch === "side" && typeof s.parent_step === "number" && s.parent_step !== i && steps[s.parent_step]) {
          if (!sideMap.has(s.parent_step)) sideMap.set(s.parent_step, []);
          sideMap.get(s.parent_step).push(s);
        }
      });
      const renderStepHtml = (s, label, isSide, depth) => {
        const badge = isSide ? '<span class="hh-step-side-badge">支线</span>' : '<span class="hh-step-main-badge">主线</span>';
        const childBadge = '<span class="hh-step-child-badge">子步</span>';
        const kids = (s.children && s.children.length)
          ? `<div class="hh-step-kids">${s.children.map((c, ci) => `<div class="hh-step hh-step-child" style="margin-left:${28 + depth * 20}px;">${childBadge}<span class="hh-step-idx">${ci + 1}</span><span class="hh-step-text">${escapeHtml(c.text || "")}</span>${c.est_min ? `<span class="hh-step-est">${c.est_min}min</span>` : ""}</div>`).join("")}</div>`
          : "";
        return `<div class="hh-step ${isSide ? "hh-step-side" : "hh-step-main"}" style="margin-left:${depth * 20}px;"><span class="hh-step-idx">${label}</span>${badge}<span class="hh-step-text">${escapeHtml(s.text || "")}</span>${s.target_dim ? `<span class="hh-dim-badge" style="background:var(--accent)20;color:var(--accent);">${escapeHtml(s.target_dim)}${s.dim_goal ? `→${s.dim_goal}` : ""}</span>` : ""}${s.est_min ? `<span class="hh-step-est">${s.est_min}min</span>` : ""}</div>${kids}`;
      };
      steps.forEach((s, i) => {
        if (s.branch === "side") return; // 支线在父步骤后渲染
        html += renderStepHtml(s, i + 1, false, 0);
        const sides = sideMap.get(i) || [];
        sides.forEach((sd, si) => { html += renderStepHtml(sd, `└${i + 1}-${si + 1}`, true, 1); });
      });
      html += `</div>`;
    }
    if (rec.shortcut) html += `<div class="hh-shortcut">⚡ 捷径：${escapeHtml(rec.shortcut)}</div>`;
    if (rec.first_blocker) html += `<div class="hh-blocker">🚧 首个障碍：${escapeHtml(rec.first_blocker)}</div>`;
    html += `<div class="hh-section-title">🕸 孵化过程图</div><div class="hh-mermaid"></div>`;
    html += `<div class="hh-mm-open"><button type="button" class="tool-btn hh-mm-open-btn" data-mm-history="1" title="把本次孵化渲染为可编辑思维导图（双击编辑/拖拽/导出）">🧠 思维导图（可编辑）</button></div>`;
    html += `</div>`;
    return html;
  }

  function renderHatchHistory() {
    const body = el.hatchHistoryBody;
    if (!body) return;
    const list = loadHatchHistory();
    if (el.hatchHistoryCount) el.hatchHistoryCount.textContent = list.length ? `${list.length} 条` : "";
    if (!list.length) {
      body.innerHTML = `<div class="hatch-history-empty">尚无孵化记录</div>`;
      return;
    }
    const sorted = [...list].sort((a, b) => (b.created_at || 0) - (a.created_at || 0));

    // ---- Kanban 列定义：7 大维度 + 未标注 ----
    const columns = [
      ...KNOWLEDGE_DIMENSIONS.map((d) => ({ key: d.code, name: d.name, color: d.color })),
      { key: "__none__", name: "未标注", color: "#8b8b9e" },
    ];
    const tagsOf = (h) => {
      const s = new Set((h.steps || []).map((x) => x.target_dim).filter(Boolean));
      return [...s];
    };
    // 列归属取维度级编码（target_dim 形如 "Cl.def"，列 key 是 "Cl"）
    // 修复：此前直接用 tags[0]（含子维度）匹配列 key，导致带维度标签的卡片永远落不进任何列而整卡消失
    const colOf = (h) => {
      const tags = tagsOf(h);
      return tags.length ? String(tags[0]).split(".")[0] : "__none__";
    };
    // 子维度徽章：编码 → 中文（带维度色 + 核心追问 title）
    const dimTagHtml = (t) => {
      const [dc, sk] = String(t).split(".");
      const meta = lookupDim(dc, sk);
      if (meta) {
        return `<span class="hh-dim-tag" style="background:${meta.dimColor}22;color:${meta.dimColor};border-color:${meta.dimColor}55;" title="${meta.dimName}${dc} · ${meta.subName}：${meta.question}">${dc}·${meta.subName}</span>`;
      }
      return `<span class="hh-dim-tag">${escapeHtml(t)}</span>`;
    };
    // 列内子维度分布（列头下方小徽章，体现子维度而非只看维度）
    const colSubStats = (items, colKey) => {
      if (colKey === "__none__") return "";
      const dim = KNOWLEDGE_DIMENSIONS.find((d) => d.code === colKey);
      if (!dim) return "";
      const counts = {};
      items.forEach((h) => tagsOf(h).forEach((t) => {
        const [dc, sk] = String(t).split(".");
        if (dc === colKey && sk) counts[sk] = (counts[sk] || 0) + 1;
      }));
      const subs = dim.subs.filter((s) => counts[s.key]);
      if (!subs.length) return "";
      return `<div class="hh-kb-subs">${subs.map((s) =>
        `<span class="hh-kb-sub-chip" title="${escapeHtml(s.q)}">${s.name}·${counts[s.key]}</span>`
      ).join("")}</div>`;
    };

    // ---- 单张卡片（摘要 + 可展开详情）----
    const cardHtml = (h) => {
      const tags = tagsOf(h);
      const dimTags = tags.map((t) => dimTagHtml(t)).join("");
      const shortcutMark = h.shortcut ? `<div class="hh-shortcut">⚡ ${escapeHtml(h.shortcut)}</div>` : "";
      // 完成度闭环：实际完成进度条（收集箱 done 状态）
      let progressHtml = "";
      const prog = getHatchProgress(h.task_hash);
      if (prog) {
        const pct = Math.round((prog.done / Math.max(prog.total, 1)) * 100);
        const doneCls = pct >= 100 ? "hh-prog-full" : (pct >= 50 ? "hh-prog-mid" : "hh-prog-low");
        progressHtml = `<div class="hh-prog ${doneCls}">
          <span class="hh-prog-label">实际完成 ${prog.done}/${prog.total}</span>
          <span class="hh-prog-bar"><span class="hh-prog-fill" style="width:${pct}%"></span></span>
          <span class="hh-prog-pct">${pct}%</span>
        </div>`;
      }
      return `<div class="hh-kb-card" data-hash="${escapeHtml(h.task_hash || "")}">
        <div class="hh-kb-card-head">
          <span class="hh-task-text">${escapeHtml(h.task_text || "")}</span>
          <span class="hh-time">${formatHatchTime(h.created_at)}</span>
        </div>
        <div class="hh-meta">
          <span class="hh-meta-item">${h.accepted_count || 0}/${h.total_count || 0} 步</span>
          ${h.est_total_min ? `<span class="hh-meta-item">⏱ ${h.est_total_min}min</span>` : ""}
          <span class="hh-meta-item">${escapeHtml((h.last_scene || "") + (h.last_mode || ""))}</span>
          ${dimTags ? `<span class="hh-dim-list">${dimTags}</span>` : ""}
        </div>
        ${progressHtml}
        ${shortcutMark}
        <div class="hh-kb-card-detail" hidden></div>
        <div class="hh-card-actions">
          <button class="hh-btn hh-kb-toggle">▼ 展开</button>
          <button class="hh-btn hh-rehatch" data-hash="${escapeHtml(h.task_hash || "")}" data-text="${escapeHtml(h.task_text || "")}">🔄 重新孵化</button>
          <button class="hh-btn hh-to-grid" data-hash="${escapeHtml(h.task_hash || "")}" ${h.steps && h.steps.length ? "" : "disabled"}>📋 安排到格子</button>
          <button class="hh-btn hh-del" data-hash="${escapeHtml(h.task_hash || "")}">🗑 删除</button>
        </div>
      </div>`;
    };

    // ---- 顶部统计 ----
    const totalSteps = sorted.reduce((n, h) => n + (h.steps || []).length, 0);
    const totalAcc = sorted.reduce((n, h) => n + (h.accepted_count || 0), 0);
    const kw = (body.dataset.kw || "").trim().toLowerCase();
    const filtered = kw ? sorted.filter((h) => {
      const hay = [h.task_text || h.task || h.title || "", ...(h.steps || []).map((s) => s.text || s.title || "")].join(" ").toLowerCase();
      return hay.includes(kw);
    }) : sorted;
    const toolbar = `<div class="hh-kb-toolbar">
      <span class="hh-kb-toolbar-title">🧭 按知识维度分类</span>
      <input class="hh-kb-search" id="hhKbSearch" type="text" placeholder="🔍 搜索任务 / 步骤…" value="${escapeHtml(body.dataset.kw || "")}" />
      <span class="hh-kb-toolbar-stat">${filtered.length} 次孵化 · ${totalAcc}/${totalSteps} 步被接受</span>
    </div>`;

    // ---- 看板（横向滚动，列 = tag）----
    const board = `<div class="hh-kb-board">${columns.map((col) => {
      const items = filtered.filter((h) => colOf(h) === col.key);
      if (!items.length) return `<div class="hh-kb-col hh-kb-col-empty" data-col="${col.key}">
        <div class="hh-kb-col-head"><span class="hh-kb-col-dot" style="background:${col.color}"></span><span class="hh-kb-col-name">${col.name}</span><span class="hh-kb-col-count">0</span></div>
        <div class="hh-kb-col-body"><div class="hh-kb-col-empty-tip">暂无</div></div>
      </div>`;
      return `<div class="hh-kb-col" data-col="${col.key}">
        <div class="hh-kb-col-head"><span class="hh-kb-col-dot" style="background:${col.color}"></span><span class="hh-kb-col-name">${col.name}</span><span class="hh-kb-col-count">${items.length}</span></div>
        ${colSubStats(items, col.key)}
        <div class="hh-kb-col-body">${items.map(cardHtml).join("")}</div>
      </div>`;
    }).join("")}</div>`;

    body.innerHTML = toolbar + board;

    // ---- 事件委托：展开卡片 / 操作按钮（仅在首次渲染时绑定一次，避免监听器累积）----
    if (!body.dataset.hatchBound) {
      body.dataset.hatchBound = "1";
      // 搜索过滤（防抖 + 重建后恢复焦点）
      let searchTimer = null;
      body.addEventListener("input", (e) => {
        const search = e.target.closest(".hh-kb-search");
        if (!search) return;
        body.dataset.kw = search.value;
        clearTimeout(searchTimer);
        searchTimer = setTimeout(() => {
          renderHatchHistory();
          const again = body.querySelector(".hh-kb-search");
          if (again) {
            again.focus();
            const len = again.value.length;
            again.setSelectionRange(len, len);
          }
        }, 150);
      });
      body.addEventListener("click", (e) => {
      const del = e.target.closest(".hh-del");
      const rehatch = e.target.closest(".hh-rehatch");
      const toGrid = e.target.closest(".hh-to-grid");
      const card = e.target.closest(".hh-kb-card");
      if (del) {
        const hash = del.getAttribute("data-hash");
        const item = sorted.find((h) => h.task_hash === hash);
        if (item) {
          const fullList = loadHatchHistory();
          saveHatchHistory(fullList.filter((h) => h.task_hash !== hash));
          renderHatchHistory();
          toast("已删除该孵化记录", "info");
        }
        return;
      }
      if (rehatch) {
        const text = rehatch.getAttribute("data-text") || "";
        if (!text) return;
        closeHatchHistoryDialog();
        openHatchDialog({ text });
        return;
      }
      if (toGrid) {
        const hash = toGrid.getAttribute("data-hash");
        const item = sorted.find((h) => h.task_hash === hash);
        if (item && item.steps && item.steps.length) applyHistoryToGrid(item);
        return;
      }
      // 点击卡片主体（非按钮）→ 展开/收起详情
      if (card && !e.target.closest("button")) {
        const detail = card.querySelector(".hh-kb-card-detail");
        const toggleBtn = card.querySelector(".hh-kb-toggle");
        if (detail) {
          const isOpen = !detail.hidden;
          if (isOpen) {
            detail.hidden = true;
            if (toggleBtn) toggleBtn.textContent = "▼ 展开";
            card.classList.remove("expanded");
          } else {
            if (!detail.dataset.loaded) {
              fillHatchCardDetail(detail, sorted.find((h) => h.task_hash === card.getAttribute("data-hash")));
              detail.dataset.loaded = "1";
            }
            detail.hidden = false;
            if (toggleBtn) toggleBtn.textContent = "▲ 收起";
            card.classList.add("expanded");
          }
        }
      }
      });
    }
  }

  // 填充卡片展开详情（问答 + 步骤 + mermaid 过程图）
  function fillHatchCardDetail(detailEl, rec) {
    if (!rec) { detailEl.innerHTML = `<div class="hh-mm-empty">无记录</div>`; return; }
    let html = "";
    if (rec.qa_pairs && rec.qa_pairs.length) {
      html += `<div class="hh-section-label">🧠 引导问答</div>`;
      html += rec.qa_pairs.map((qa) => {
        // 维度 chip 中文化：qa.dim=编码 qa.sub=子维度 key → 中文名 + 维度色 + 核心追问 title
        let dimChip = "";
        if (qa.dim) {
          const dimObj = KNOWLEDGE_DIMENSIONS.find((d) => d.code === qa.dim);
          const color = dimObj ? dimObj.color : "#7c5cff";
          const subObj = dimObj && qa.sub ? dimObj.subs.find((s) => s.key === qa.sub) : null;
          dimChip = `<span class="hh-qa-dim" style="background:${color}22;color:${color};border-color:${color}55;" title="${dimObj ? dimObj.name : ""}${subObj ? " · " + subObj.name + "：" + subObj.q : ""}">${qa.dim}${subObj ? "·" + subObj.name : ""}</span>`;
        }
        const ansText = qa.answer
          ? `<span class="hh-qa-ans">${escapeHtml(qa.answer)}</span>`
          : `<span class="hh-qa-ans hh-qa-empty">（未填写）</span>`;
        return `<div class="hh-qa"><div class="hh-qa-q">${dimChip}<span>${escapeHtml(qa.question || qa.label || "")}</span></div><div class="hh-qa-a">${ansText}</div></div>`;
      }).join("");
    }
    if (rec.steps && rec.steps.length) {
      html += `<div class="hh-section-label">📋 拆解步骤</div>`;
      html += rec.steps.map((s, i) => {
        // 步骤维度标记中文化（编码 → 维度·子维度名，title 含核心追问）
        let dimMark = "";
        if (s.target_dim) {
          const [dc, sk] = String(s.target_dim).split(".");
          const meta = lookupDim(dc, sk);
          if (meta) {
            dimMark = `<span class="hh-step-dim" style="background:${meta.dimColor}22;color:${meta.dimColor};border-color:${meta.dimColor}55;" title="${meta.dimName}${dc} · ${meta.subName}：${meta.question}（编码 ${s.target_dim}）">${dc}·${meta.subName}${s.dim_goal ? `→${s.dim_goal}` : ""}</span>`;
          } else {
            dimMark = `<span class="hh-step-dim">${escapeHtml(s.target_dim)}</span>`;
          }
        }
        const estMark = s.est_min ? `<span class="hh-step-est">${s.est_min}min</span>` : "";
        const riskMark = s.risk ? `<span class="hh-step-risk" title="风险">⚠</span>` : "";
        return `<div class="hh-step"><span class="hh-step-idx">${i + 1}</span><span class="hh-step-text">${escapeHtml(s.text || "")}${dimMark}</span>${estMark}${riskMark}</div>`;
      }).join("");
    }
    if (rec.first_blocker) html += `<div class="hh-blocker">🚧 首个障碍：${escapeHtml(rec.first_blocker)}</div>`;
    html += `<div class="hh-section-label">🕸 孵化过程图</div><div class="hh-mermaid"></div>`;
    html += `<div class="hh-mm-open"><button type="button" class="tool-btn hh-mm-open-btn" data-mm-history="1" title="把本次孵化渲染为可编辑思维导图（双击编辑/拖拽/导出）">🧠 思维导图（可编辑）</button></div>`;
    detailEl.innerHTML = html;
    const mmEl = detailEl.querySelector(".hh-mermaid");
    if (mmEl) renderHatchMermaid(mmEl, rec);
    const mmOpenBtn = detailEl.querySelector("[data-mm-history]");
    if (mmOpenBtn) mmOpenBtn.addEventListener("click", () => openMindmapFromHistory(rec));
  }

  // 生成孵化过程 mermaid 图（任务 → 引导问答 → 主线/支线步骤 → 细化子步骤 → 产出）
  function buildHatchGraph(rec) {
    const esc = (s) => String(s || "")
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/[\[\](){}|#]/g, " ").replace(/"/g, "＂").replace(/\n/g, " ").slice(0, 70);
    const lines = ["flowchart TD"];
    lines.push(`T["🥚 ${esc(rec.task_text)}"]`);
    const qas = rec.qa_pairs || [];
    const steps = rec.steps || [];
    // 主线/支线分组
    const mainSteps = [];
    const sideByParent = new Map();
    steps.forEach((s, idx) => {
      if (s.branch === "side" && typeof s.parent_step === "number" && s.parent_step !== idx && steps[s.parent_step]) {
        if (!sideByParent.has(s.parent_step)) sideByParent.set(s.parent_step, []);
        sideByParent.get(s.parent_step).push({ s, idx });
      } else {
        mainSteps.push({ s, idx });
      }
    });
    // 引导问答节点（只显示已回答的，避免过长）
    const qaShown = qas.filter((qa) => qa.answer && qa.answer.trim());
    qaShown.forEach((qa, i) => {
      lines.push(`QA${i}["${esc(qa.dim ? qa.dim + " " : "")}${esc(qa.question || qa.label)}<br/>→ ${esc(qa.answer)}"]`);
    });
    // 主线节点（紫色系） + 支线节点（橙色系） + 细化子节点（蓝色系）
    const nodeId = (k) => k;
    mainSteps.forEach(({ s, idx }) => {
      lines.push(`M${idx}["${esc(s.target_dim ? s.target_dim + " " : "")}${idx + 1}. ${esc(s.text)}${s.est_min ? ` (${s.est_min}min)` : ""}"]:::main`);
      // 细化子步骤（children）挂在主线节点下
      if (Array.isArray(s.children) && s.children.length) {
        s.children.forEach((c, ci) => {
          lines.push(`C${idx}_${ci}["${esc(c.target_dim ? c.target_dim + " " : "")}${ci + 1}. ${esc(c.text)}${c.est_min ? ` (${c.est_min}min)` : ""}"]:::child`);
          lines.push(`M${idx} -.-> C${idx}_${ci}`);
        });
      }
    });
    sideByParent.forEach((sides, pi) => {
      sides.forEach(({ s }, si) => {
        lines.push(`SD${pi}_${si}["↳ ${esc(s.text)}${s.est_min ? ` (${s.est_min}min)` : ""}"]:::side`);
        lines.push(`M${pi} -.-> SD${pi}_${si}`);
        if (Array.isArray(s.children) && s.children.length) {
          s.children.forEach((c, ci) => {
            lines.push(`SC${pi}_${si}_${ci}["${esc(c.text)}${c.est_min ? ` (${c.est_min}min)` : ""}"]:::child`);
            lines.push(`SD${pi}_${si} -.-> SC${pi}_${si}_${ci}`);
          });
        }
      });
    });
    // 类定义：主线/支线/子步骤着色
    lines.push("classDef main fill:#241f4a,stroke:#7c5cff,color:#c9bfff;");
    lines.push("classDef side fill:#3a2a12,stroke:#ffa94d,color:#ffd9a8;");
    lines.push("classDef child fill:#102a3a,stroke:#4dc3ff,color:#b8e8ff;");
    // 边：主线串联
    const mainIdxArr = mainSteps.map(({ idx }) => idx);
    if (qaShown.length) {
      lines.push(`T --> QA0`);
      for (let i = 0; i < qaShown.length - 1; i++) lines.push(`QA${i} --> QA${i + 1}`);
      if (steps.length) lines.push(`QA${qaShown.length - 1} --> M${mainIdxArr[0]}`);
      else lines.push(`QA${qaShown.length - 1} --> R["🎯 ${rec.accepted_count || 0}/${rec.total_count || 0} 步 · 预估 ${rec.est_total_min || 0}min"]`);
    } else if (steps.length) {
      lines.push(`T --> M${mainIdxArr[0]}`);
    } else {
      lines.push(`T --> R["🎯 ${rec.accepted_count || 0}/${rec.total_count || 0} 步"]`);
    }
    if (steps.length) {
      for (let i = 0; i < mainIdxArr.length - 1; i++) lines.push(`M${mainIdxArr[i]} --> M${mainIdxArr[i + 1]}`);
      lines.push(`M${mainIdxArr[mainIdxArr.length - 1]} --> R["🎯 ${rec.accepted_count || 0}/${rec.total_count || 0} 步 · 预估 ${rec.est_total_min || 0}min"]`);
    }
    if (rec.shortcut) lines.push(`R -.-> SH["⚡ 捷径：${esc(rec.shortcut)}"]`);
    if (rec.first_blocker) lines.push(`R -.-> BL["🚧 ${esc(rec.first_blocker)}"]`);
    return lines.join("\n");
  }

  // 渲染 mermaid 图（异步）
  async function renderHatchMermaid(container, rec) {
    if (typeof mermaid === "undefined") {
      container.innerHTML = `<div class="hh-mm-empty">图表库未加载（lib/mermaid.min.js 缺失）</div>`;
      return;
    }
    try {
      mermaid.initialize({
        startOnLoad: false,
        theme: "dark",
        securityLevel: "loose",
        fontFamily: "inherit",
        flowchart: { curve: "basis", nodeSpacing: 22, rankSpacing: 28, htmlLabels: true },
      });
      const id = "hhg" + Math.random().toString(36).slice(2, 8);
      const { svg } = await mermaid.render(id, buildHatchGraph(rec));
      container.innerHTML = `<div class="hh-mm-svg">${svg}</div><button type="button" class="hh-mm-zoom" title="点击放大查看完整流程图">🔍 放大</button>`;
      const svgEl = container.querySelector(".hh-mm-svg svg");
      if (svgEl) svgEl.style.maxWidth = "100%";
      // 绑定一次放大事件（容器复用，避免监听器累积）
      if (!container.dataset.zoomBound) {
        container.dataset.zoomBound = "1";
        container.addEventListener("click", (e) => {
          if (e.target.closest(".hh-mm-zoom")) openMermaidLightbox(container);
        });
      }
    } catch (e) {
      container.innerHTML = `<div class="hh-mm-empty">过程图渲染失败：${escapeHtml(e.message || "未知错误")}</div>`;
    }
  }

  // 把历史记录中的步骤直接安排到时间格子（无需重新打开孵化弹窗）
  function applyHistoryToGrid(histEntry) {
    const steps = (histEntry.steps || []).filter((s) => s.text);
    if (!steps.length) {
      toast("该记录无可安排的步骤", "info");
      return;
    }
    const cellsPerStep = steps.map((s) => {
      const min = s.est_min || 15;
      return Math.max(1, Math.ceil(min / (SECONDS_PER_CELL / 60)));
    });
    let startGlobal = getCurrentGlobalCell();
    if (startGlobal < 0) startGlobal = 0;
    else startGlobal += 1;

    const assignments = [];
    let cursor = startGlobal;
    let overflow = false;
    for (let i = 0; i < steps.length; i++) {
      const need = cellsPerStep[i];
      let placed = false;
      while (cursor + need - 1 < PERIOD_COUNT * CELLS_PER_PERIOD) {
        let allFree = true;
        for (let k = 0; k < need; k++) {
          const g = cursor + k;
          const p = Math.floor(g / CELLS_PER_PERIOD);
          const c = g % CELLS_PER_PERIOD;
          if (getCellTasks(p, c).length > 0) { allFree = false; break; }
        }
        if (allFree) {
          const step = steps[i];
          const firstG = cursor;
          const firstP = Math.floor(firstG / CELLS_PER_PERIOD);
          const firstC = firstG % CELLS_PER_PERIOD;
          let taskText = step.text;
          const meta = {};
          if (step.target_dim) {
            const goal = step.dim_goal ? `→${step.dim_goal}` : "";
            taskText += ` #${step.target_dim}${goal}#`;
            meta.dim = step.target_dim;
            if (step.dim_goal) meta.dimGoal = step.dim_goal;
          }
          if (step.est_min) meta.estimate = String(step.est_min);
          assignments.push({ period: firstP, cell: firstC, text: taskText, meta, placeholder: false });
          for (let k = 1; k < need; k++) {
            const g = firstG + k;
            assignments.push({ period: Math.floor(g / CELLS_PER_PERIOD), cell: g % CELLS_PER_PERIOD, text: "", meta: null, placeholder: true });
          }
          cursor = firstG + need;
          placed = true;
          break;
        }
        cursor++;
      }
      if (!placed) { overflow = true; break; }
    }

    const totalCells = cellsPerStep.reduce((a, b) => a + b, 0);
    if (!assignments.length || overflow) {
      toast(`今日剩余空格不足（需 ${totalCells} 格），请先清空格子`, "error");
      return;
    }
    let written = 0;
    const filledPeriods = new Set();
    assignments.forEach((a) => {
      if (a.placeholder || !a.text) return;
      setCellTasks(a.period, a.cell, [{ text: a.text, ...a.meta, hatchHash: histEntry.task_hash }]);
      filledPeriods.add(a.period);
      written++;
    });
    // 更新历史记录的接受数（不重写步骤）
    const fullList = loadHatchHistory();
    const existing = fullList.find((h) => h.task_hash === histEntry.task_hash);
    if (existing) {
      existing.accepted_count = written;
      existing.created_at = Date.now();
      saveHatchHistory(fullList);
    }
    if (filledPeriods.size) {
      const firstP = Math.min(...filledPeriods);
      state.activePeriod = firstP;
      setRealm("plan");
    }
    const dimCount = steps.filter((s) => s.target_dim).length;
    toast(`已安排 ${written} 个任务到 ${filledPeriods.size} 个时辰${dimCount ? `（含 ${dimCount} 条维度练习）` : ""}`, "success");
    haptic([20, 40, 20]);
    closeHatchHistoryDialog();
    renderAll();
  }

  // 孵化历史：内嵌在孵化页面的面板（不再是独立弹窗）
  function openHatchHistoryDialog() {
    renderHatchHistory();
    if (el.hatchHistoryPanel) {
      el.hatchHistoryPanel.hidden = false;
      setTimeout(() => {
        if (el.hatchHistoryPanel.scrollIntoView) {
          el.hatchHistoryPanel.scrollIntoView({ behavior: "smooth", block: "start" });
        }
      }, 60);
    }
  }
  function closeHatchHistoryDialog() {
    if (el.hatchHistoryPanel) el.hatchHistoryPanel.hidden = true;
  }

  // mermaid 流程图放大查看（lightbox）
  function openMermaidLightbox(srcContainer) {
    if (!el.mermaidLightbox || !el.mermaidLightboxBody) return;
    const svg = srcContainer && (srcContainer.querySelector(".hh-mm-svg svg") || srcContainer.querySelector("svg"));
    if (!svg) return;
    el.mermaidLightboxBody.innerHTML = "";
    const clone = svg.cloneNode(true);
    clone.removeAttribute("width");
    clone.style.maxWidth = "100%";
    clone.style.height = "auto";
    el.mermaidLightboxBody.appendChild(clone);
    if (typeof el.mermaidLightbox.showModal === "function") el.mermaidLightbox.showModal();
    else el.mermaidLightbox.setAttribute("open", "");
  }
  function closeMermaidLightbox() {
    if (!el.mermaidLightbox) return;
    try { el.mermaidLightbox.close(); } catch (e) { el.mermaidLightbox.removeAttribute("open"); }
  }

  // 导出 lightbox 中的 mermaid 图为 PNG（2x 高清，深色底）
  function downloadMermaidPng() {
    const svg = el.mermaidLightboxBody && el.mermaidLightboxBody.querySelector("svg");
    if (!svg) { toast("没有可导出的图表", "info"); return; }
    try {
      const clone = svg.cloneNode(true);
      clone.setAttribute("xmlns", "http://www.w3.org/2000/svg");
      clone.setAttribute("xmlns:xlink", "http://www.w3.org/1999/xlink");
      // 尺寸：优先 viewBox，兜底 getBoundingClientRect
      const vb = (svg.getAttribute("viewBox") || "").split(/[\s,]+/).map(Number);
      let w = vb.length === 4 && vb[2] > 0 ? vb[2] : svg.getBoundingClientRect().width || 800;
      let h = vb.length === 4 && vb[3] > 0 ? vb[3] : svg.getBoundingClientRect().height || 600;
      w = Math.max(200, Math.round(w));
      h = Math.max(150, Math.round(h));
      clone.setAttribute("width", w);
      clone.setAttribute("height", h);
      const xml = new XMLSerializer().serializeToString(clone);
      const svgUrl = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(xml);
      const img = new Image();
      img.onload = () => {
        try {
          const scale = 2; // 高清导出
          const canvas = document.createElement("canvas");
          canvas.width = w * scale;
          canvas.height = h * scale;
          const ctx = canvas.getContext("2d");
          ctx.fillStyle = "#14141f"; // 与应用深色底一致
          ctx.fillRect(0, 0, canvas.width, canvas.height);
          ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
          canvas.toBlob((blob) => {
            if (!blob) { toast("PNG 导出失败", "error"); return; }
            const a = document.createElement("a");
            a.href = URL.createObjectURL(blob);
            const d = new Date();
            const pad = (n) => String(n).padStart(2, "0");
            a.download = `孵化流程图_${d.getFullYear()}${pad(d.getMonth() + 1)}${pad(d.getDate())}_${pad(d.getHours())}${pad(d.getMinutes())}.png`;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            setTimeout(() => URL.revokeObjectURL(a.href), 5000);
            toast("已导出 PNG（2x 高清）", "success");
          }, "image/png");
        } catch (e) {
          toast("PNG 导出失败：" + (e.message || e), "error");
        }
      };
      img.onerror = () => toast("PNG 导出失败（SVG 序列化异常）", "error");
      img.src = svgUrl;
    } catch (e) {
      toast("PNG 导出失败：" + (e.message || e), "error");
    }
  }

  // ============================================================
  // 🧠 孵化思维导图（可编辑）
  // 数据模型：树 {id, text, meta:{est_min,risk,verify,why,target_dim,law,color}, type:main|side|child, collapsed, children[]}
  // 布局：tidy 槽位分配（lr 左右 / tb 上下），SVG 渲染，HTML 浮层编辑
  // 功能：双击编辑 / 增删 / 上下移 / 提升降级 / 拖拽改隶属 / 折叠 /
  //       维度配色 / 撤销重做 / 搜索定位 / 大纲 / 导出 PNG·文本·Mermaid /
  //       应用到步骤列表 / 保存到孵化记录
  // ============================================================
  const MINDMAP_KEY = "mandala-mindmaps-v1";
  let mmEditor = null;

  class MindMapEditor {
    constructor() {
      this.root = null;
      this.seq = 0;
      this.view = { x: 0, y: 0, scale: 1 };
      this.selectedId = null;
      this.layout = "lr";
      this.outlineOpen = false;
      this.history = [];
      this.histIdx = -1;
      this._slot = 0;
      this._bbox = null;   // 布局包围盒 {minX,minY,maxX,maxY}
      this._panning = null;
      this._dragging = null;
      this._dragTarget = null;
      this._focusedNode = null; // 搜索定位闪烁
      this._searchList = [];
      this._openedFrom = null;   // {mode:'result'|'history', hash}
      this.els = {
        dialog: document.getElementById("mindmapDialog"),
        svg: document.getElementById("mmSvg"),
        g: document.getElementById("mmCanvasG"),
        canvas: document.getElementById("mmCanvas"),
        title: document.getElementById("mmTaskTitle"),
        sub: document.getElementById("mmTaskSub"),
        undo: document.getElementById("mmUndo"),
        redo: document.getElementById("mmRedo"),
        layout: document.getElementById("mmLayout"),
        outlineToggle: document.getElementById("mmOutlineToggle"),
        search: document.getElementById("mmSearch"),
        zoomOut: document.getElementById("mmZoomOut"),
        zoomIn: document.getElementById("mmZoomIn"),
        zoomLabel: document.getElementById("mmZoomLabel"),
        fit: document.getElementById("mmFit"),
        exportPng: document.getElementById("mmExportPng"),
        exportText: document.getElementById("mmExportText"),
        exportMmd: document.getElementById("mmExportMmd"),
        exportMd: document.getElementById("mmExportMd"),
        exportHtml: document.getElementById("mmExportHtml"),
        apply: document.getElementById("mmApply"),
        save: document.getElementById("mmSave"),
        libraryBtn: document.getElementById("mmLibraryBtn"),
        exportInbox: document.getElementById("mmExportInbox"),
        importArticle: document.getElementById("mmImportArticle"),
        close: document.getElementById("mmClose"),
        hint: document.getElementById("mmHint"),
        stats: document.getElementById("mmStats"),
        legend: document.getElementById("mmLegend"),
        nodePanel: document.getElementById("mmNodePanel"),
        outline: document.getElementById("mmOutline"),
        library: document.getElementById("mmLibrary"),
        searchRes: document.getElementById("mmSearchRes"),
        floatEdit: document.getElementById("mmFloatEdit"),
        floatInput: document.getElementById("mmFloatInput"),
        floatOk: document.getElementById("mmFloatOk"),
        floatBar: document.getElementById("mmFloatBar"),
      };
      this._bind();
    }

    // ---------- 数据转换：steps → 树 ----------
    stepsToTree(result) {
      const steps = (result && result.steps) || [];
      const root = this.newNode(result && result.taskText || (hatchState.taskText || "任务"), { est_min: result && result.est_total_min });
      root._isRoot = true;
      const mainNodes = new Map(); // 主线 index -> 树节点
      steps.forEach((s, idx) => {
        const type = s.branch === "side" ? "side" : "main";
        const n = this.newNode(s.text, {
          est_min: s.est_min, risk: s.risk, verify: s.verify, why: s.why,
          target_dim: s.target_dim, dim_goal: s.dim_goal, law: s.law,
          branch: s.branch, parent_step: s.parent_step,
          icon: s.icon, note: s.note,
        });
        n.type = type;
        if (type === "main") {
          root.children.push(n);
          mainNodes.set(idx, n);
        }
      });
      // 支线挂主线、children 挂父节点
      steps.forEach((s, idx) => {
        if (s.branch === "side" && typeof s.parent_step === "number" && mainNodes.has(s.parent_step)) {
          const parent = mainNodes.get(s.parent_step);
          const n = this.newNode(s.text, {
            est_min: s.est_min, risk: s.risk, verify: s.verify, why: s.why,
            target_dim: s.target_dim, dim_goal: s.dim_goal, law: s.law,
            icon: s.icon, note: s.note,
          });
          n.type = "side";
          parent.children.push(n);
        } else if (Array.isArray(s.children) && s.children.length) {
          const parent = mainNodes.get(idx);
          if (parent) {
            s.children.forEach((c) => {
              const n = this.newNode(c.text, {
                est_min: c.est_min, risk: c.risk, verify: c.verify, why: c.why,
                target_dim: c.target_dim, dim_goal: c.dim_goal,
                icon: c.icon, note: c.note,
              });
              n.type = "child";
              parent.children.push(n);
            });
          }
        }
      });
      return root;
    }

    // 树 → steps（应用到列表）
    treeToSteps() {
      const mainNodes = (this.root && this.root.children) || [];
      const steps = [];
      mainNodes.forEach((m) => {
        const mainIdx = steps.length;
        steps.push({
          text: m.text,
          est_min: m.meta && m.meta.est_min, risk: (m.meta && m.meta.risk) || "low", risk_note: "",
          why: (m.meta && m.meta.why) || "", branch: "main", parent_step: null,
          target_dim: (m.meta && m.meta.target_dim) || "", dim_goal: (m.meta && m.meta.dim_goal) || null,
          law: (m.meta && m.meta.law) || "",
          icon: (m.meta && m.meta.icon) || "", note: (m.meta && m.meta.note) || "", done: !!(m.meta && m.meta.done),
        });
        const sides = [];
        const kids = [];
        (m.children || []).forEach((c) => {
          if (c.type === "side") sides.push(c);
          else kids.push(c);
        });
        sides.forEach((s) => {
          steps.push({
            text: s.text,
            est_min: s.meta && s.meta.est_min, risk: (s.meta && s.meta.risk) || "low", risk_note: "",
            why: (s.meta && s.meta.why) || "", branch: "side", parent_step: mainIdx,
            target_dim: (s.meta && s.meta.target_dim) || "", dim_goal: (s.meta && s.meta.dim_goal) || null,
            law: (s.meta && s.meta.law) || "",
            icon: (s.meta && s.meta.icon) || "", note: (s.meta && s.meta.note) || "", done: !!(s.meta && s.meta.done),
          });
        });
        if (kids.length) {
          steps[mainIdx].children = kids.map((k) => ({
            text: k.text, est_min: k.meta && k.meta.est_min, risk: (k.meta && k.meta.risk) || "low",
            target_dim: (k.meta && k.meta.target_dim) || "", dim_goal: (k.meta && k.meta.dim_goal) || null,
            branch: "main", why: (k.meta && k.meta.why) || "",
            icon: (k.meta && k.meta.icon) || "", note: (k.meta && k.meta.note) || "", done: !!(k.meta && k.meta.done),
          }));
        }
      });
      return steps;
    }

    newNode(text, meta) {
      return { id: "n" + (++this.seq), text: String(text || ""), meta: meta || {}, type: "main", collapsed: false, children: [] };
    }
    // 重新对齐自增序号：导入/打开历史导图后，避免新建节点 id 与已有节点撞号
    _resyncSeq() {
      let max = 0;
      const walk = (n) => {
        if (!n) return;
        const m = String(n.id || "").match(/^n(\d+)$/);
        if (m) max = Math.max(max, parseInt(m[1], 10));
        (n.children || []).forEach(walk);
      };
      walk(this.root);
      if (max > this.seq) this.seq = max;
    }

    // ---------- 布局（tidy 槽位分配） ----------
    // v94 自由摆放：节点 meta.dx/dy 为用户手动偏移（相对自动布局位），拖拽空白处设置；拖到节点上仍是改隶属
    _applyUserOffsets(root) {
      const walk = (n) => {
        if (!n) return;
        const p = this._nodePos.get(n.id);
        if (p && n.meta && (n.meta.dx || n.meta.dy)) {
          p.x += n.meta.dx || 0;
          p.y += n.meta.dy || 0;
        }
        (n.children || []).forEach(walk);
      };
      if (root) walk(root);
      else if (this.root) walk(this.root);
    }
    doLayout(root) {
      root = root || this.root;
      this._slot = 0;
      // 放射状布局：根居中，一级均匀分布一圈，更深层沿父角度向外延伸
      if (this.layout === "radial") {
        this._nodePos = new Map();
        const sizes = this._collectSizes(root);
        const R1 = 300, levelGap = 260;
        const place = (n, angle, radius, depth) => {
          const sz = sizes.get(n.id) || { w: 220, h: 44 };
          const x = Math.cos(angle) * radius - sz.w / 2;
          const y = Math.sin(angle) * radius - sz.h / 2;
          this._nodePos.set(n.id, { x, y, w: sz.w, h: sz.h, depth, angle, radius });
          const cnt = n.children.length;
          n.children.forEach((c, i) => {
            const ca = cnt > 1 ? angle + (i - (cnt - 1) / 2) * 0.55 : angle;
            place(c, ca, radius + levelGap, depth + 1);
          });
        };
        const sz0 = sizes.get(root.id) || { w: 220, h: 44 };
        this._nodePos.set(root.id, { x: -sz0.w / 2, y: -sz0.h / 2, w: sz0.w, h: sz0.h, depth: 0, angle: 0, radius: 0 });
        const top = root.children.length;
        root.children.forEach((c, i) => {
          const angle = -Math.PI / 2 + (i - (top - 1) / 2) * (2 * Math.PI / Math.max(1, top));
          place(c, angle, R1, 1);
        });
        this._applyUserOffsets(root);
        let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
        this._nodePos.forEach((p) => {
          minX = Math.min(minX, p.x); minY = Math.min(minY, p.y);
          maxX = Math.max(maxX, p.x + p.w); maxY = Math.max(maxY, p.y + p.h);
        });
        if (!isFinite(minX)) { minX = -200; minY = -100; maxX = 200; maxY = 100; }
        this._bbox = { minX, minY, maxX, maxY };
        return;
      }
      const NODE_W = 0, NODE_H = 0; // 占位（实际在渲染时用节点尺寸）
      const hGap = this.layout === "lr" ? 86 : 38; // 疏朗间距（避免节点拥挤）
      const vGap = this.layout === "lr" ? 32 : 86;
      this._calcLayout(root, 0);
      this._nodePos = new Map();
      const sizes = this._collectSizes(root);
      const pos = (n, depth) => {
        const sz = sizes.get(n.id) || { w: 220, h: 44 };
        const x = depth * (sz.w + hGap);
        const y = n._slot * (sz.h + vGap);
        this._nodePos.set(n.id, { x, y, w: sz.w, h: sz.h, depth });
        n.children.forEach((c) => pos(c, depth + 1));
      };
      pos(root, 0);
      this._applyUserOffsets(root);
      // 包围盒
      let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
      this._nodePos.forEach((p) => {
        minX = Math.min(minX, p.x); minY = Math.min(minY, p.y);
        maxX = Math.max(maxX, p.x + p.w); maxY = Math.max(maxY, p.y + p.h);
      });
      if (!isFinite(minX)) { minX = 0; minY = 0; maxX = 400; maxY = 200; }
      this._bbox = { minX, minY, maxX, maxY };
    }
    _calcLayout(n, depth) {
      n._depth = depth;
      if (!n.children.length || n.collapsed) { n._slot = this._slot++; }
      else {
        n.children.forEach((c) => this._calcLayout(c, depth + 1));
        n._slot = (n.children[0]._slot + n.children[n.children.length - 1]._slot) / 2;
      }
    }
    _collectSizes(n, map) {
      map = map || new Map();
      const lines = Math.max(1, Math.ceil(this._textWidth(n.text) / 210));
      const w = Math.min(Math.max(120, Math.round(this._textWidth(n.text)) + 46), 330);
      const h = 44 + (lines - 1) * 18 + (n.meta && (n.meta.verify || n.meta.risk === "high" || n.meta.risk === "med") ? 16 : 0);
      map.set(n.id, { w, h });
      n.children.forEach((c) => this._collectSizes(c, map));
      return map;
    }
    _textWidth(s) {
      let w = 0;
      for (const ch of String(s || "")) w += ch.charCodeAt(0) > 255 ? 14 : 8;
      return w;
    }

    // ---------- 渲染 ----------
    render() {
      if (!this.root) return;
      // v94：今日格子任务文本集合（O(81) 一次遍历）→ 节点渲染时 O(1) 判断是否已安排到时间格子
      this._taskTextSet = new Set();
      try {
        const dayTasks = state.tasks[state.currentDate] || {};
        Object.values(dayTasks).forEach((arr) => {
          (arr || []).forEach((t) => { const s = (t && t.text || "").trim(); if (s) this._taskTextSet.add(s); });
        });
      } catch (e) { /* 容错 */ }
      const renderRoot = (this.focusId && this.findNode(this.focusId)) || this.root;
      this.doLayout(renderRoot);
      const g = this.els.g;
      this.els.g.innerHTML = "";
      // SVG 渐变 defs（根节点紫蓝渐变 / 主线边渐变）
      const NS = "http://www.w3.org/2000/svg";
      const defs = document.createElementNS(NS, "defs");
      defs.innerHTML = `<linearGradient id="mmRootGrad" x1="0" y1="0" x2="1" y2="1">
        <stop offset="0%" stop-color="#7c5cff"/><stop offset="55%" stop-color="#9d6bff"/><stop offset="100%" stop-color="#5b8cff"/>
      </linearGradient>`;
      g.appendChild(defs);
      // 入场动画：仅导图打开/整体重建时播放一次（_open 置位），交互重绘不播
      const _animIn = this._animateIn;
      this._renderEdges(renderRoot, _animIn);
      this._renderNode(renderRoot, 0, _animIn);
      this._renderLinks(renderRoot);
      this._renderStats(renderRoot);
      this._renderLegend();
      this._applyView();
      this._updateFloatBar();
      this._updateNavCrumb && this._updateNavCrumb();
      // 描边动画结束后移除 class，避免 dasharray 常量残留影响后续渲染样式
      if (_animIn) {
        setTimeout(() => {
          try {
            this.els.g.querySelectorAll(".mm-edge-draw").forEach((p) => p.classList.remove("mm-edge-draw"));
          } catch (e) { /* 节点已重建则忽略 */ }
        }, 1900);
      }
      this._animateIn = false;
      // 聚焦状态提示
      if (this.els.hint && this.focusId) {
        this.els.hint.textContent = `🎯 已聚焦：${renderRoot.text || "节点"} · 双击编辑 · Esc 退出聚焦`;
        this.els.hint.style.background = "rgba(255,217,61,.18)";
      }
    }
    // 聚焦节点：只显示该节点及其子树（其余隐藏），Esc 退出
    focusNode(id) {
      const n = this.findNode(id);
      if (!n) return;
      this.focusId = id;
      this.selectedId = id;
      this.view = { x: 0, y: 0, scale: 1 };
      this.render();
      toast(`🎯 已聚焦「${trunc(n.text, 16)}」分支 · Esc 返回全景`, "info");
    }
    clearFocus() {
      if (!this.focusId) return false;
      this.focusId = null;
      this.view = { x: 0, y: 0, scale: 1 };
      // 退出聚焦时显式恢复默认 hint（render 只在聚焦态覆盖 hint）
      if (this.els.hint) {
        this.els.hint.textContent = "🖱 滚轮缩放 · 拖动空白平移 · 点击选中节点 · 双击编辑文本";
        this.els.hint.style.background = "rgba(15,15,30,.7)";
      }
      this.render();
      return true;
    }
    // 选中节点浮动操作条（触屏友好：不需要开面板就能增删改）
    _updateFloatBar() {
      const bar = this.els.floatBar;
      if (!bar) return;
      const id = this.selectedId;
      const n = id && this.findNode(id);
      if (!n || n._isRoot || this._dragGhost) { bar.hidden = true; return; }
      const p = this._nodePos && this._nodePos.get(id);
      if (!p) { bar.hidden = true; return; }
      const rect = this.els.canvas.getBoundingClientRect();
      if (!rect.width) { bar.hidden = true; return; }
      const cx = p.x * this.view.scale + this.view.x + p.w * this.view.scale / 2;
      const topY = p.y * this.view.scale + this.view.y;
      const bw = bar.offsetWidth || 260;
      const bh = bar.offsetHeight || 44;
      const nodeH = p.h * this.view.scale;
      // 水平：居中于节点，但不出画布左右边界
      const left = Math.max(4, Math.min(rect.width - bw - 4, cx - bw / 2));
      // 垂直：优先放节点上方；上方放不下则落到节点下方
      let top = topY - bh - 8;
      if (top < 4) top = topY + nodeH + 8;
      bar.style.left = left + "px";
      bar.style.top = top + "px";
      bar.hidden = false;
      // Round5：关联绘制模式按钮高亮
      const linkBtn = bar.querySelector('[data-a="link"]');
      if (linkBtn) linkBtn.classList.toggle("on", !!this._linkFrom);
      this._updateNavCrumb && this._updateNavCrumb();
    }
    // Round5：进入/退出关联线绘制模式
    beginLinkMode(fromId) {
      if (!fromId || this.findNode(fromId)?._isRoot) {
        toast("请先选中非根节点再画关联", "info");
        return;
      }
      if (this._linkFrom === fromId) {
        this.cancelLinkMode();
        return;
      }
      this._linkFrom = fromId;
      this._updateFloatBar && this._updateFloatBar();
      toast("🔗 再点另一个节点建立关联（Esc 取消）", "info", 2800);
      haptic(12);
    }
    cancelLinkMode() {
      if (!this._linkFrom) return;
      this._linkFrom = null;
      this._updateFloatBar && this._updateFloatBar();
      toast("已取消关联绘制", "info");
    }
    completeLinkTo(toId) {
      const fromId = this._linkFrom;
      if (!fromId || !toId || fromId === toId) {
        this.cancelLinkMode();
        return false;
      }
      const from = this.findNode(fromId);
      const to = this.findNode(toId);
      if (!from || !to || from._isRoot) {
        this.cancelLinkMode();
        toast("无法建立关联", "warn");
        return false;
      }
      this.pushHistory();
      const m = from.meta || (from.meta = {});
      if (m.link === toId) {
        delete m.link;
        this._linkFrom = null;
        this.render();
        toast("已清除关联", "info");
        return true;
      }
      m.link = toId;
      this._linkFrom = null;
      this.selectedId = fromId;
      this.render();
      this._showNodePanel && this._showNodePanel(fromId);
      toast("🔗 已关联 → " + trunc(to.text || "节点", 16), "success");
      haptic(18);
      return true;
    }
    // Round2：节点路径面包屑（根 › … › 当前），点击可跳父级
    _updateNavCrumb() {
      if (!this.els || !this.els.canvas) return;
      let crumb = this.els.canvas.querySelector(".mm-nav-crumb");
      if (!crumb) {
        crumb = document.createElement("div");
        crumb.className = "mm-nav-crumb";
        this.els.canvas.appendChild(crumb);
        crumb.addEventListener("click", (e) => {
          const b = e.target.closest("[data-mm-nav]");
          if (!b) return;
          const id = b.getAttribute("data-mm-nav");
          if (!id) return;
          this.selectedId = id;
          this._showNodePanel && this._showNodePanel(id);
          this.render();
          this.centerOn(id);
          haptic(12);
        });
      }
      const id = this.selectedId;
      if (!id || !this.root) { crumb.hidden = true; return; }
      const path = [];
      let cur = this.findNode(id);
      const guard = new Set();
      while (cur && !guard.has(cur.id)) {
        guard.add(cur.id);
        path.unshift(cur);
        if (cur._isRoot) break;
        cur = this.findParent(cur.id);
      }
      if (!path.length) { crumb.hidden = true; return; }
      crumb.hidden = false;
      crumb.innerHTML = path.map((n, i) => {
        const label = trunc(n._isRoot ? ("根：" + (n.text || "导图")) : (n.text || "节点"), 14);
        return '<button type="button" class="mm-nav-seg' + (i === path.length - 1 ? " cur" : "") + '" data-mm-nav="' + n.id + '">' + escapeHtml(label) + "</button>";
      }).join('<span class="mm-nav-sep">›</span>');
    }
    _applyView() {
      const { x, y, scale } = this.view;
      this.els.g.setAttribute("transform", `translate(${x},${y}) scale(${scale})`);
      if (this.els.zoomLabel) this.els.zoomLabel.textContent = Math.round(scale * 100) + "%";
    }
    _edgePath(px, py, cx, cy) {
      const dir = this.layout === "lr" ? 1 : 0;
      if (dir) return `M ${px} ${py} C ${px + 34} ${py}, ${cx - 34} ${cy}, ${cx} ${cy}`;
      return `M ${px} ${py} C ${px} ${py + 26}, ${cx} ${cy - 26}, ${cx} ${cy}`;
    }
    _renderEdges(n, anim, dep) {
      const pos = this._nodePos;
      const p = pos.get(n.id);
      if (!p) return;
      if (n.collapsed) return; // 折叠：不渲染子级
      n.children.forEach((c) => {
        const cp = pos.get(c.id);
        if (!cp) return;
        const path = document.createElementNS("http://www.w3.org/2000/svg", "path");
        const dir = this.layout === "lr" ? 1 : 0;
        let sx = p.x + p.w, sy = p.y + p.h / 2;
        let tx = cp.x, ty = cp.y + cp.h / 2;
        if (this.layout === "radial") {
          // 放射状：父中心 → 子中心直线（轻微曲率）
          sx = p.x + p.w / 2; sy = p.y + p.h / 2;
          tx = cp.x + cp.w / 2; ty = cp.y + cp.h / 2;
          path.setAttribute("d", `M ${sx} ${sy} L ${tx} ${ty}`);
        } else {
          path.setAttribute("d", dir
            ? `M ${sx} ${sy} C ${sx + 34} ${sy}, ${tx - 34} ${ty}, ${tx} ${ty}`
            : `M ${sx} ${sy} C ${sx} ${sy + 26}, ${tx} ${ty - 26}, ${tx} ${ty}`);
        }
        path.setAttribute("fill", "none");
        const isSide = c.type === "side";
        const isChild = c.type === "child";
        path.setAttribute("stroke", isSide ? "#ffa94d" : (isChild ? "#4dc3ff" : "rgba(124,92,255,0.55)"));
        path.setAttribute("stroke-width", isSide ? 1.6 : (isChild ? 1.4 : 2));
        if (isSide || isChild) path.setAttribute("stroke-dasharray", "5 4");
        path.setAttribute("opacity", "0.7");
        // 入场动画：连线按层级递进绘制（主线实线用描边生长，虚线用淡入以免破坏虚线样式）
        if (anim) {
          const d0 = ((dep || 0) * 80 + 60);
          path.style.setProperty("--mm-delay", d0 + "ms");
          if (!isSide && !isChild) {
            let len = 260;
            try { len = path.getTotalLength() || 260; } catch (e) { len = 260; }
            path.style.setProperty("--mm-len", String(Math.max(80, Math.min(len, 900))));
            path.classList.add("mm-edge-draw");
          } else {
            path.classList.add("mm-edge-in");
          }
        }
        this.els.g.appendChild(path);
        // 端点圆点（父端小圆，视觉锚点）
        const dot = document.createElementNS("http://www.w3.org/2000/svg", "circle");
        dot.setAttribute("cx", sx); dot.setAttribute("cy", sy);
        dot.setAttribute("r", isSide ? 2.5 : (isChild ? 2 : 3));
        dot.setAttribute("fill", isSide ? "#ffa94d" : (isChild ? "#4dc3ff" : "#7c5cff"));
        dot.setAttribute("opacity", "0.85");
        this.els.g.appendChild(dot);
        this._renderEdges(c, anim, (dep || 0) + 1);
      });
    }
    _nodeColors(n) {
      if (n.meta && n.meta.color) return { fill: n.meta.color, text: "#fff" };
      if (n._isRoot) return { fill: "#7c5cff", text: "#fff", stroke: "#a58fff" };
      if (n.meta && n.meta.target_dim) {
        const dc = String(n.meta.target_dim).split(".")[0];
        const d = KNOWLEDGE_DIMENSIONS.find((x) => x.code === dc);
        // 柔和填充 + 同色描边 + 混亮文字（降低认知负荷）
        if (d) return { fill: this._soft(d.color, .22), text: this._dimText(d.color), stroke: d.color, dim: d };
      }
      if (n.type === "side") return { fill: "rgba(255,169,77,.28)", text: "#ffd9a8", stroke: "#c98a4b" };
      if (n.type === "child") return { fill: "rgba(77,195,255,.20)", text: "#b5e3fa", stroke: "#4a9bc4" };
      return { fill: "rgba(124,92,255,0.14)", stroke: "rgba(124,92,255,0.7)", text: "#c9bfff" };
    }
    // hex → 指定透明度的 rgba（柔和填充用）
    _soft(hex, a) {
      const m = /^#?([0-9a-f]{6})$/i.exec(hex || "");
      if (!m) return hex;
      const v = m[1];
      return "rgba(" + parseInt(v.slice(0, 2), 16) + "," + parseInt(v.slice(2, 4), 16) + "," + parseInt(v.slice(4, 6), 16) + "," + a + ")";
    }
    // hex → 混白 72% 的亮色（浅底上的可读文字）
    _dimText(hex) {
      const m = /^#?([0-9a-f]{6})$/i.exec(hex || "");
      if (!m) return "#fff";
      const v = m[1];
      const mix = (c) => Math.round(c + (255 - c) * 0.72);
      return "rgb(" + mix(parseInt(v.slice(0, 2), 16)) + "," + mix(parseInt(v.slice(2, 4), 16)) + "," + mix(parseInt(v.slice(4, 6), 16)) + ")";
    }
    _renderNode(n, depth, anim) {
      const pos = this._nodePos.get(n.id);
      if (!pos) return;
      const g = this.els.g;
      const isSel = this.selectedId === n.id;
      const col = this._nodeColors(n);
      const lines = Math.max(1, Math.ceil(this._textWidth(n.text) / 210));
      const txtLines = [];
      // 节点图标（emoji）前缀
      const nodeIcon = (n.meta && n.meta.icon && !n._isRoot) ? n.meta.icon + " " : "";
      const t = nodeIcon + String(n.text || "");
      for (let i = 0; i < lines; i++) txtLines.push(t.slice(i * 15, (i + 1) * 15));
      const group = document.createElementNS("http://www.w3.org/2000/svg", "g");
      group.setAttribute("transform", `translate(${pos.x},${pos.y})`);
      group.setAttribute("data-node", n.id);
      // v94 task 标识：节点文本已安排到今日时间格子 → 青绿描边 + ↩ 角标（点击直达格子）
      const isTaskNode = !n._isRoot && this._taskTextSet && this._taskTextSet.has((n.text || "").trim());
      group.setAttribute("class", "mm-node" + (isSel ? " mm-node-sel" : "") + (n._isRoot ? " mm-node-root" : "") + (isTaskNode ? " mm-node-task" : "") + (depth ? " mm-depth-" + Math.min(depth, 4) : ""));
      // 入场动画：节点按层级由内向外依次「上板」（用 CSS 独立 scale 属性，避免覆盖 translate 定位）
      if (anim) {
        group.classList.add("mm-node-in");
        group.style.setProperty("--mm-delay", ((depth || 0) * 70 + 30) + "ms");
        // Round2：上板抛光——轻微上浮 + 淡入
        group.style.setProperty("--mm-rise", Math.min(18, 6 + (depth || 0) * 3) + "px");
      }
      // 底（发光）
      if (isSel) {
        const glow = document.createElementNS("http://www.w3.org/2000/svg", "rect");
        glow.setAttribute("x", -5); glow.setAttribute("y", -5);
        glow.setAttribute("width", pos.w + 10); glow.setAttribute("height", pos.h + 10);
        glow.setAttribute("rx", 14); glow.setAttribute("fill", "none");
        glow.setAttribute("stroke", col.stroke || col.fill); glow.setAttribute("stroke-width", 3);
        glow.setAttribute("opacity", "0.55");
        group.appendChild(glow);
      }
      // 主体
      const rect = document.createElementNS("http://www.w3.org/2000/svg", "rect");
      rect.setAttribute("width", pos.w); rect.setAttribute("height", pos.h);
      rect.setAttribute("rx", n._isRoot ? 14 : 11);
      if (n._isRoot) {
        rect.setAttribute("fill", "url(#mmRootGrad)");
        rect.setAttribute("stroke", "#b8a6ff");
        rect.setAttribute("stroke-width", 2);
        rect.setAttribute("stroke-opacity", 0.9);
      } else {
        rect.setAttribute("fill", col.fill);
        const done = n.meta && n.meta.done;
        if (done) {
          rect.setAttribute("stroke", "#4ade80");
          rect.setAttribute("stroke-width", 1.6);
          rect.setAttribute("stroke-opacity", 0.9);
        } else if (isTaskNode) {
          // v94 task 节点：青绿描边（与完成绿区分）——一眼看出"已安排到时间格子"
          rect.setAttribute("stroke", "#2dd4bf");
          rect.setAttribute("stroke-width", isSel ? 2 : 1.6);
          rect.setAttribute("stroke-opacity", isSel ? 1 : 0.95);
        } else {
          if (col.stroke) rect.setAttribute("stroke", col.stroke);
          rect.setAttribute("stroke-width", isSel ? 2 : 1);
          rect.setAttribute("stroke-opacity", isSel ? 1 : 0.6);
        }
      }
      group.appendChild(rect);
      // Round2：根节点「根」徽章 + 非根层级小标（强化层级可读）
      if (n._isRoot) {
        const rb = document.createElementNS("http://www.w3.org/2000/svg", "text");
        rb.setAttribute("x", 10); rb.setAttribute("y", 14);
        rb.setAttribute("fill", "rgba(255,255,255,.85)");
        rb.setAttribute("font-size", "9");
        rb.setAttribute("font-weight", "800");
        rb.setAttribute("style", "pointer-events:none");
        rb.textContent = "根 · ROOT";
        group.appendChild(rb);
      } else if (depth > 0) {
        const db = document.createElementNS("http://www.w3.org/2000/svg", "text");
        db.setAttribute("x", pos.w - 6); db.setAttribute("y", 11);
        db.setAttribute("text-anchor", "end");
        db.setAttribute("fill", "rgba(200,200,230,.55)");
        db.setAttribute("font-size", "8");
        db.setAttribute("font-weight", "700");
        db.setAttribute("style", "pointer-events:none");
        db.textContent = "L" + depth;
        group.appendChild(db);
      }
      // 风险左边条
      const risk = n.meta && n.meta.risk;
      if (risk === "high" || risk === "med") {
        const bar = document.createElementNS("http://www.w3.org/2000/svg", "rect");
        bar.setAttribute("x", 0); bar.setAttribute("y", 6);
        bar.setAttribute("width", 4); bar.setAttribute("height", pos.h - 12);
        bar.setAttribute("rx", 2);
        bar.setAttribute("fill", risk === "high" ? "#ff5470" : "#ffb020");
        group.appendChild(bar);
      }
      // 优先级顶条（🔴高 / 🔶中，红黄横条）
      const prio = n.meta && n.meta.priority;
      if (prio === 1 || prio === 2) {
        const pb = document.createElementNS("http://www.w3.org/2000/svg", "rect");
        pb.setAttribute("x", 4); pb.setAttribute("y", 0);
        pb.setAttribute("width", Math.min(pos.w - 8, 26)); pb.setAttribute("height", 3);
        pb.setAttribute("rx", 1.5);
        pb.setAttribute("fill", prio === 1 ? "#ff5470" : "#ffb020");
        group.appendChild(pb);
      }
      // 文本（可多行）
      const text = document.createElementNS("http://www.w3.org/2000/svg", "text");
      text.setAttribute("x", 14); text.setAttribute("y", 24);
      text.setAttribute("fill", col.text);
      text.setAttribute("font-size", "14");
      text.setAttribute("font-weight", n._isRoot ? 700 : 500);
      text.setAttribute("style", "pointer-events:none");
      const maxChars = 15;
      const chunks = [];
      for (let i = 0; i < t.length; i += maxChars) chunks.push(t.slice(i, i + maxChars));
      chunks.slice(0, 3).forEach((ln, li) => {
        const tspan = document.createElementNS("http://www.w3.org/2000/svg", "tspan");
        tspan.setAttribute("x", 14);
        tspan.setAttribute("dy", li === 0 ? 0 : 18);
        tspan.textContent = ln;
        text.appendChild(tspan);
      });
      if (chunks.length > 3) {
        const more = document.createElementNS("http://www.w3.org/2000/svg", "tspan");
        more.setAttribute("x", 14); more.setAttribute("dy", 18);
        more.textContent = "…";
        text.appendChild(more);
      }
      group.appendChild(text);
      // 徽标行（↩格子 / ⏱ / ✓ / ✅完成 / 📝备注 / dim）
      let badges = [];
      if (isTaskNode) badges.push("↩格");
      if (n.meta && n.meta.est_min) badges.push(`⏱${n.meta.est_min}`);
      if (n.meta && n.meta.done) badges.push("✅");
      else if (n.meta && n.meta.verify) badges.push("✓");
      if (n.meta && n.meta.note) badges.push("📝");
      if (n.meta && n.meta.link) badges.push("🔗");
      if (n.meta && n.meta.article_text) badges.push("📄");
      if (n.meta && n.meta.insight) badges.push("💡");
      if (n.meta && n.meta.target_dim) {
        const dc = String(n.meta.target_dim).split(".")[0];
        badges.push(dc);
      }
      if (badges.length) {
        const bt = document.createElementNS("http://www.w3.org/2000/svg", "text");
        bt.setAttribute("x", 14);
        bt.setAttribute("y", pos.h - 9);
        bt.setAttribute("fill", col.text);
        bt.setAttribute("font-size", "10");
        bt.setAttribute("opacity", "0.85");
        bt.setAttribute("style", "pointer-events:none");
        bt.textContent = badges.join(" · ");
        group.appendChild(bt);
      }
      // v94 task 节点右上角 ↩ 角标：点击直达时间格子（直截了当，无需先选中再找跳转按钮）
      if (isTaskNode) {
        const jg = document.createElementNS("http://www.w3.org/2000/svg", "g");
        jg.setAttribute("data-mm-jump", n.id);
        jg.setAttribute("class", "mm-task-badge");
        const jt = document.createElementNS("http://www.w3.org/2000/svg", "title");
        jt.textContent = "↩ 回到时间格子（此节点已安排为今日任务）";
        jg.appendChild(jt);
        const jc = document.createElementNS("http://www.w3.org/2000/svg", "circle");
        jc.setAttribute("cx", pos.w - 16); jc.setAttribute("cy", 14); jc.setAttribute("r", 10);
        jc.setAttribute("fill", "#2dd4bf");
        jg.appendChild(jc);
        const js = document.createElementNS("http://www.w3.org/2000/svg", "text");
        js.setAttribute("x", pos.w - 16); js.setAttribute("y", 18.5);
        js.setAttribute("text-anchor", "middle");
        js.setAttribute("font-size", "11");
        js.setAttribute("font-weight", "700");
        js.setAttribute("fill", "#082b26");
        js.textContent = "↩";
        jg.appendChild(js);
        group.appendChild(jg);
      }
      // 折叠按钮（有子节点且未折叠时显示 +N；统一放右下角，右上角留给 task ↩ 角标）
      if (n.children.length && !n._isRoot) {
        const fold = document.createElementNS("http://www.w3.org/2000/svg", "g");
        fold.setAttribute("data-fold", n.id);
        fold.setAttribute("class", "mm-fold");
        const c = document.createElementNS("http://www.w3.org/2000/svg", "circle");
        c.setAttribute("cx", pos.w - 12); c.setAttribute("cy", pos.h - 12);
        c.setAttribute("r", 9);
        c.setAttribute("fill", "rgba(255,255,255,0.9)");
        fold.appendChild(c);
        const f = document.createElementNS("http://www.w3.org/2000/svg", "text");
        f.setAttribute("x", pos.w - 12); f.setAttribute("y", pos.h - 8);
        f.setAttribute("text-anchor", "middle");
        f.setAttribute("font-size", "10");
        f.setAttribute("font-weight", 700);
        f.setAttribute("fill", "#222");
        f.textContent = n.collapsed ? `+${n.children.length}` : "−";
        fold.appendChild(f);
        group.appendChild(fold);
      }
      // 根节点省略折叠
      this.els.g.appendChild(group);
      // 递归渲染子节点
      if (!n.collapsed) n.children.forEach((c) => this._renderNode(c, depth + 1, anim));
    }
    // 跨分支关联线：节点 meta.link → 目标节点之间画橙色虚线（表达依赖/关联）
    _renderLinks(root) {
      if (!this.els.g || !this._nodePos) return;
      root = root || this.root;
      const NS = "http://www.w3.org/2000/svg";
      const drawn = new Set();
      const walk = (n) => {
        if (n.meta && n.meta.link) {
          const t = this.findNode(n.meta.link);
          const p = this._nodePos.get(n.id);
          const tp = t && this._nodePos.get(t.id);
          if (p && tp) {
            const key = [n.id, t.id].sort().join("→");
            if (!drawn.has(key)) {
              drawn.add(key);
              const x1 = p.x + p.w, y1 = p.y + p.h / 2;
              const x2 = tp.x, y2 = tp.y + tp.h / 2;
              const dx = Math.max(40, (x2 - x1) * 0.5);
              const path = document.createElementNS(NS, "path");
              path.setAttribute("d", `M ${x1} ${y1} C ${x1 + dx} ${y1}, ${x2 - dx} ${y2}, ${x2} ${y2}`);
              path.setAttribute("fill", "none");
              path.setAttribute("stroke", "#ffa94d");
              path.setAttribute("stroke-width", 1.6);
              path.setAttribute("stroke-dasharray", "5 4");
              path.setAttribute("opacity", "0.9");
              path.setAttribute("pointer-events", "stroke");
              path.setAttribute("stroke-width", 8);
              path.setAttribute("stroke-opacity", "0"); // 透明加粗命中区
              path.style.cursor = "pointer";
              path.dataset.linkFrom = n.id;
              path.dataset.linkTo = t.id;
              // 点击关联线 → 删除该关联（可视化闭环）
              path.addEventListener("click", (e) => {
                e.stopPropagation();
                const f = this.findNode(path.dataset.linkFrom);
                if (f && f.meta) {
                  if (confirm(`删除「${trunc(f.text, 16)}」与「${trunc(t.text, 16)}」的关联？`)) {
                    delete f.meta.link;
                    this.pushHistory();
                    this.render();
                    toast("已删除关联", "info");
                  }
                }
              });
              this.els.g.appendChild(path);
              // 可见细虚线（覆盖在命中区上）
              const vis = document.createElementNS(NS, "path");
              vis.setAttribute("d", path.getAttribute("d"));
              vis.setAttribute("fill", "none");
              vis.setAttribute("stroke", "#ffa94d");
              vis.setAttribute("stroke-width", 1.6);
              vis.setAttribute("stroke-dasharray", "5 4");
              vis.setAttribute("opacity", "0.75");
              vis.setAttribute("pointer-events", "none");
              this.els.g.appendChild(vis);
              // 目标端小圆点
              const dot = document.createElementNS(NS, "circle");
              dot.setAttribute("cx", x2); dot.setAttribute("cy", y2); dot.setAttribute("r", 3.5);
              dot.setAttribute("fill", "#ffa94d"); dot.setAttribute("opacity", "0.9");
              dot.setAttribute("pointer-events", "none");
              this.els.g.appendChild(dot);
            }
          }
        }
        n.children.forEach(walk);
      };
      walk(root);
    }
    _renderStats(root) {
      if (!this.els.stats) return;
      root = root || this.root;
      const total = this._countNodes(root);
      const mains = (root && root.children) || [];
      const sides = [];
      const kids = [];
      const walk = (n) => { n.children.forEach((c) => { if (c.type === "side") sides.push(c); else if (c.type === "child") kids.push(c); walk(c); }); };
      walk(root);
      const totalMin = this._sumMin(root);
      const dimSet = new Set();
      const walkDim = (n) => { if (n.meta && n.meta.target_dim) dimSet.add(String(n.meta.target_dim).split(".")[0]); n.children.forEach(walkDim); };
      walkDim(root);
      const focusTag = this.focusId ? `<span style="color:#ffd93d;">🎯 聚焦</span>` : "";
      let doneCnt = 0;
      const walkDone = (n) => { if (n.meta && n.meta.done) doneCnt++; n.children.forEach(walkDone); };
      walkDone(root);
      const doneTag = doneCnt ? `<span style="color:#4ade80;">✅ ${doneCnt}</span>` : "";
      const dots = KNOWLEDGE_DIMENSIONS.map((d) =>
        `<span class="mm-dimdot" style="background:${d.color};opacity:${dimSet.has(d.code) ? 1 : 0.22};" title="${d.name} ${d.code}${dimSet.has(d.code) ? " ✓" : " 未覆盖"}"></span>`).join("");
      this.els.stats.innerHTML = `${focusTag}${doneTag}<span>${total} 节点</span><span>主线 ${mains.length}</span><span>支线 ${sides.length}</span><span>子步 ${kids.length}</span><span>总时长 ${totalMin || "—"}min</span><span class="mm-stats-dims" title="7 维覆盖">${dots} ${dimSet.size}/${KNOWLEDGE_DIMENSIONS.length}</span>`;
    }
    _renderLegend() {
      if (!this.els.legend) return;
      const dimDots = KNOWLEDGE_DIMENSIONS.map((d) => `<span class="mm-leg-item"><span class="mm-leg-dot" style="background:${d.color}"></span>${d.code}</span>`).join("");
      this.els.legend.innerHTML = `<span class="mm-leg-title">图例</span>${dimDots}<span class="mm-leg-item"><span class="mm-leg-dot" style="background:rgba(124,92,255,0.5);border:1px solid #7c5cff;"></span>主线</span><span class="mm-leg-item"><span class="mm-leg-dot" style="background:#ffa94d"></span>支线</span><span class="mm-leg-item"><span class="mm-leg-dot" style="background:#4dc3ff"></span>子步</span><span class="mm-leg-item" title="青绿描边 + ↩ 角标 = 该节点已安排到今日时间格子，点 ↩ 直达"><span class="mm-leg-dot" style="background:rgba(45,212,191,.25);border:1.5px solid #2dd4bf;"></span>↩ 已上格子</span>`;
    }
    _countNodes(n) { return 1 + n.children.reduce((s, c) => s + this._countNodes(c), 0); }
    _sumMin(n) { return (n.meta && n.meta.est_min) || 0 + n.children.reduce((s, c) => s + this._sumMin(c), 0); }

    // ---------- 视图：缩放 / 平移 / 适应 ----------
    zoom(factor, cx, cy) {
      const old = this.view.scale;
      const ns = Math.min(2.5, Math.max(0.2, old * factor));
      const k = ns / old;
      // 以画布中心为锚点
      const rect = this.els.canvas.getBoundingClientRect();
      const mx = cx != null ? cx - rect.left : rect.width / 2;
      const my = cy != null ? cy - rect.top : rect.height / 2;
      this.view.x = mx - (mx - this.view.x) * k;
      this.view.y = my - (my - this.view.y) * k;
      this.view.scale = ns;
      this._applyView();
    }
    fit() {
      if (!this._bbox) return;
      const rect = this.els.canvas.getBoundingClientRect();
      if (!rect.width) return;
      const pad = 40;
      const bw = (this._bbox.maxX - this._bbox.minX) + pad * 2;
      const bh = (this._bbox.maxY - this._bbox.minY) + pad * 2;
      const scale = Math.min(1.2, Math.max(0.2, Math.min(rect.width / bw, rect.height / bh)));
      this.view.scale = scale;
      this.view.x = pad - this._bbox.minX * scale + (rect.width - (this._bbox.maxX - this._bbox.minX) * scale) / 2;
      this.view.y = pad - this._bbox.minY * scale + (rect.height - (this._bbox.maxY - this._bbox.minY) * scale) / 2;
      this._applyView();
    }
    centerOn(id) {
      const p = this._nodePos && this._nodePos.get(id);
      if (!p) return;
      const rect = this.els.canvas.getBoundingClientRect();
      if (!rect.width) return;
      // Round1：节点跳转居中更稳——预留浮动操作条高度，避免选中后被顶出可视区
      const reserveTop = 56;
      this.view.x = rect.width / 2 - (p.x + p.w / 2) * this.view.scale;
      this.view.y = (rect.height + reserveTop) / 2 - (p.y + p.h / 2) * this.view.scale;
      this._applyView();
      this._focusedNode = id;
      this._updateFloatBar && this._updateFloatBar();
      setTimeout(() => { this._focusedNode = null; this.render(); }, 1200);
    }
    svgPointToView(e) {
      const rect = this.els.canvas.getBoundingClientRect();
      return { x: e.clientX - rect.left, y: e.clientY - rect.top };
    }

    // ---------- 历史（撤销/重做） ----------
    pushHistory() {
      const snap = JSON.stringify({ root: this.root, sel: this.selectedId });
      if (this.histIdx >= 0 && this.history[this.histIdx] === snap) return;
      this.history = this.history.slice(0, this.histIdx + 1);
      this.history.push(snap);
      if (this.history.length > 50) this.history.shift();
      this.histIdx = this.history.length - 1;
    }
    undo() {
      if (this.histIdx <= 0) { toast("没有可撤销的操作", "info"); return; }
      this.histIdx--;
      const s = JSON.parse(this.history[this.histIdx]);
      this.root = s.root; this.selectedId = s.sel;
      this.render();
    }
    redo() {
      if (this.histIdx >= this.history.length - 1) { toast("没有可重做的操作", "info"); return; }
      this.histIdx++;
      const s = JSON.parse(this.history[this.histIdx]);
      this.root = s.root; this.selectedId = s.sel;
      this.render();
    }

    // ---------- 查找 ----------
    findNode(id, n) {
      n = n || this.root;
      if (n.id === id) return n;
      for (const c of n.children) { const r = this.findNode(id, c); if (r) return r; }
      return null;
    }
    // 按文本匹配节点（用于格子任务 ↔ 导图节点互跳）
    findNodeByText(text, n) {
      n = n || this.root;
      if (!n) return null;
      if ((n.text || "").trim() === String(text || "").trim()) return n;
      for (const c of n.children) { const r = this.findNodeByText(text, c); if (r) return r; }
      return null;
    }
    // 收集除指定节点外的所有节点（用于「关联到」下拉）
    _allNodesExcept(id) {
      const out = [];
      const walk = (n) => { if (n.id !== id) out.push(n); n.children.forEach(walk); };
      walk(this.root);
      return out;
    }
    findParent(id, n, parent) {
      n = n || this.root;
      if (n.id === id) return parent;
      for (const c of n.children) { const r = this.findParent(id, c, n); if (r) return r; }
      return null;
    }
    walk(n, fn) { fn(n); n.children.forEach((c) => this.walk(c, fn)); }

    // ---------- 编辑操作 ----------
    select(id) {
      this.selectedId = id;
      this.render();
      this._showNodePanel(id);
    }
    _showNodePanel(id) {
      const panel = this.els.nodePanel;
      const n = this.findNode(id);
      if (!n || n._isRoot) { panel.hidden = true; panel.innerHTML = ""; return; }
      const m = n.meta || (n.meta = {});
      const dimOpts = ['<option value="">（无维度）</option>'].concat(
        KNOWLEDGE_DIMENSIONS.map((d) =>
          `<optgroup label="${d.name} ${d.code}">` +
          d.subs.map((s) => `<option value="${d.code}.${s.key}" ${m.target_dim === `${d.code}.${s.key}` ? "selected" : ""}>${d.code}·${s.name}</option>`).join("") +
          `</optgroup>`).join(""));
      panel.innerHTML = `
        <div class="mm-panel-head"><span>✏️ 节点详情</span><button type="button" class="icon-btn mm-panel-close">✕</button></div>
        <div class="mm-panel-body">
          <label>文本<textarea class="mm-pf-text" rows="2">${escapeHtml(n.text)}</textarea></label>
          <label class="mm-pf-done-label" style="flex-direction:row;align-items:center;gap:8px;cursor:pointer;">
            <input type="checkbox" class="mm-pf-done" ${m.done ? "checked" : ""} /> 已完成（✅ 绿框标记）
          </label>
          <div class="mm-pf-grid">
            <label>时长(分)<input type="number" class="mm-pf-min" value="${m.est_min || ""}" min="0" /></label>
            <label>风险<select class="mm-pf-risk"><option value="">无</option><option value="low" ${m.risk === "low" ? "selected" : ""}>低</option><option value="med" ${m.risk === "med" ? "selected" : ""}>中</option><option value="high" ${m.risk === "high" ? "selected" : ""}>高</option></select></label>
            <label>优先级<select class="mm-pf-prio"><option value="">无</option><option value="1" ${m.priority === 1 ? "selected" : ""}>🔴 高</option><option value="2" ${m.priority === 2 ? "selected" : ""}>🔶 中</option></select></label>
            <label>维度<select class="mm-pf-dim">${dimOpts}</select></label>
            <label>颜色<input type="color" class="mm-pf-color" value="${m.color || "#7c5cff"}" /><button type="button" class="tool-btn mm-pf-clr">清除</button></label>
          </div>
          <label>自检标准<textarea class="mm-pf-verify" rows="1" placeholder="完成标准…">${escapeHtml(m.verify || "")}</textarea></label>
          <label>为什么必要<textarea class="mm-pf-why" rows="1" placeholder="为什么…">${escapeHtml(m.why || "")}</textarea></label>
          <label>关联到（虚线连接，表达依赖/关联）
            <select class="mm-pf-link">
              <option value="">（无关联）</option>
              ${this._allNodesExcept(id).map((x) => `<option value="${x.id}" ${m.link === x.id ? "selected" : ""}>${escapeHtml(trunc(x.text, 18))}</option>`).join("")}
            </select>
          </label>
          <label>图标（节点前缀 emoji）
            <div class="mm-pf-icons">
              <button type="button" data-i="" class="${!m.icon ? "on" : ""}" title="无图标">无</button>
              ${["📌","⭐","🔥","✅","💡","🎯","📚","💪","🧠","🕐","💰","❤️"].map((e) => `<button type="button" data-i="${e}" class="${m.icon === e ? "on" : ""}" title="用 ${e} 作节点图标">${e}</button>`).join("")}
            </div>
          </label>
          <label>备注<textarea class="mm-pf-note" rows="2" placeholder="补充说明、检查要点…（节点显示 📝 标记）">${escapeHtml(m.note || "")}</textarea></label>
          <label>📄 文章链接（可选，AI 可据此拆解多节点）
            <div class="mm-pf-url-row">
              <input type="url" class="mm-pf-url" placeholder="https://…" value="${escapeHtml(m.article_url || "")}" />
              <button type="button" class="tool-btn mm-pf-fetch" title="抓取链接正文">🌐 抓取</button>
            </div>
          </label>
          <div class="mm-pf-art">
            ${m.article_text ? `<span class="mm-pf-art-info">📖 已抓取 ${m.article_text.length} 字</span>` : `<span class="mm-pf-art-info">未关联文章</span>`}
            <div class="mm-pf-art-btns">
              ${m.article_text ? `<button type="button" class="tool-btn mm-pf-view">查看原文</button>` : ""}
              <button type="button" class="tool-btn mm-pf-chat">💬 AI 对话</button>
              <button type="button" class="tool-btn mm-pf-ai">🧠 AI 拆解</button>
            </div>
          </div>
          ${m.insight ? `<div class="mm-pf-insight">💡 见解精要：${escapeHtml(m.insight)}</div>` : ""}
        </div>`;
      panel.hidden = false;
      const commit = (fn) => { this.pushHistory(); fn(); this.render(); this._showNodePanel(id); };
      const onCommit = (ev) => commit(() => {
        if (ev.target.classList.contains("mm-pf-text")) n.text = ev.target.value;
        if (ev.target.classList.contains("mm-pf-min")) { m.est_min = parseInt(ev.target.value, 10) || null; }
        if (ev.target.classList.contains("mm-pf-risk")) m.risk = ev.target.value || "";
        if (ev.target.classList.contains("mm-pf-dim")) m.target_dim = ev.target.value || "";
        if (ev.target.classList.contains("mm-pf-verify")) m.verify = ev.target.value;
        if (ev.target.classList.contains("mm-pf-why")) m.why = ev.target.value;
        if (ev.target.classList.contains("mm-pf-color")) m.color = ev.target.value || "";
        if (ev.target.classList.contains("mm-pf-note")) m.note = ev.target.value;
        if (ev.target.classList.contains("mm-pf-url")) m.article_url = ev.target.value.trim() || "";
        if (ev.target.classList.contains("mm-pf-done")) m.done = !!ev.target.checked;
        if (ev.target.classList.contains("mm-pf-prio")) { if (ev.target.value) m.priority = parseInt(ev.target.value, 10); else delete m.priority; }
        if (ev.target.classList.contains("mm-pf-link")) { if (ev.target.value) m.link = ev.target.value; else delete m.link; }
      });
      panel.querySelectorAll("textarea, select, input[type=number], input[type=color], input[type=url]").forEach((inp) => {
        inp.addEventListener("change", onCommit);
        if (inp.tagName === "TEXTAREA") inp.addEventListener("blur", onCommit);
      });
      // 📄 文章链接抓取 / 查看原文 / AI 拆解 / AI 对话
      const fetchBtn = panel.querySelector(".mm-pf-fetch");
      if (fetchBtn) fetchBtn.addEventListener("click", () => this.fetchNodeArticle(id));
      const viewBtn = panel.querySelector(".mm-pf-view");
      if (viewBtn) viewBtn.addEventListener("click", () => this.viewNodeArticle(id));
      const chatBtn = panel.querySelector(".mm-pf-chat");
      if (chatBtn) chatBtn.addEventListener("click", () => this.openNodeChat(id));
      const aiBtn = panel.querySelector(".mm-pf-ai");
      if (aiBtn) aiBtn.addEventListener("click", () => this.aiDecompose(id));
      // 完成状态 checkbox：change 即提交
      const doneCb = panel.querySelector(".mm-pf-done");
      if (doneCb) doneCb.addEventListener("change", onCommit);
      // 图标选择：点击即切换
      panel.querySelectorAll(".mm-pf-icons button").forEach((b) => {
        b.addEventListener("click", () => commit(() => {
          const v = b.dataset.i || "";
          if (v) m.icon = v; else delete m.icon;
          panel.querySelectorAll(".mm-pf-icons button").forEach((x) => x.classList.toggle("on", x === b));
        }));
      });
      const clr = panel.querySelector(".mm-pf-clr");
      if (clr) clr.addEventListener("click", () => commit(() => { delete m.color; }));
      const closeBtn = panel.querySelector(".mm-panel-close");
      if (closeBtn) closeBtn.addEventListener("click", () => { panel.hidden = true; });
      // 🎨 降干扰：面板 6 秒无操作淡出（半透明仍可点）；面板内交互即重置
      clearTimeout(this._panelIdle);
      panel.classList.remove("idle-fade");
      const armIdle = () => {
        clearTimeout(this._panelIdle);
        panel.classList.remove("idle-fade");
        this._panelIdle = setTimeout(() => {
          const ae = document.activeElement;
          const editing = ae && panel.contains(ae) && ["TEXTAREA", "INPUT", "SELECT"].includes(ae.tagName);
          if (!editing) panel.classList.add("idle-fade"); // 正在编辑则不淡出
        }, 6000);
      };
      armIdle();
      panel.onpointerdown = armIdle;
      panel.onwheel = armIdle;
    }
    // 📄 抓取节点关联文章链接（多源降级，失败提示手动粘贴）
    async fetchNodeArticle(id) {
      const n = this.findNode(id);
      if (!n) return;
      const m = n.meta || (n.meta = {});
      const url = (m.article_url || "").trim();
      if (!url) { toast("请先在上方填写文章链接", "info"); return; }
      toast("🌐 抓取文章中…", "info");
      const text = await this._grabArticle(url);
      if (!text) { toast("抓取失败（跨域限制）· 可手动粘贴正文", "error"); return; }
      m.article_text = text;
      delete m.insight; // 原文变了，旧精要作废
      this.render();
      this._showNodePanel(id);
      toast("✓ 已抓取 " + text.length + " 字 · 可点「AI 拆解」", "success");
    }
    async _grabArticle(url) {
      const sources = [
        (u) => "https://r.jina.ai/" + u,
        (u) => "https://api.allorigins.win/raw?url=" + encodeURIComponent(u),
      ];
      for (const mk of sources) {
        try {
          const res = await fetch(mk(url), { method: "GET" });
          if (!res.ok) continue;
          const txt = await res.text();
          if (txt && txt.length > 60) return txt.slice(0, 60000);
        } catch (e) { /* 换下一个源 */ }
      }
      return null;
    }
    // 📖 查看节点关联文章原文（只读弹窗）
    viewNodeArticle(id) {
      const n = this.findNode(id);
      if (!n) return;
      const text = n.meta && n.meta.article_text;
      if (!text) { toast("尚未抓取文章", "info"); return; }
      let dlg = document.getElementById("mmArticleViewDlg");
      if (!dlg) {
        dlg = document.createElement("dialog");
        dlg.id = "mmArticleViewDlg";
        dlg.className = "mm-article-view-dlg";
        dlg.innerHTML = '<div class="mav-head"><span>📖 文章原文</span><button type="button" class="icon-btn mav-close">✕</button></div>'
          + '<div class="mav-body"></div>';
        document.body.appendChild(dlg);
        dlg.querySelector(".mav-close").addEventListener("click", () => dlg.close());
      }
      dlg.querySelector(".mav-body").textContent = text;
      dlg.showModal();
    }
    // 🧠 AI 综合拆解：task 文本 + 关联文章 + 现有子节点 → 多节点 + 见解精要（省 token）
    async aiDecompose(id) {
      const n = this.findNode(id);
      if (!n) return;
      const m = n.meta || (n.meta = {});
      const taskText = (n.text || "").trim();
      const articleText = (m.article_text || "").trim();
      const noApi = !state.settings.apiUrl || !state.settings.apiKey;
      // 无 API 但有文章 → 0 token 本地复现文章结构
      if (noApi && articleText) { this._localDecompose(id, articleText); return; }
      if (noApi) { toast("未配置 AI API（设置 → AI 配置），可先关联文章走本地复现", "warn"); return; }
      toast("🧠 AI 拆解中…", "info");
      const existing = (n.children || []).map((c) => c.text).filter(Boolean).join("；");
      const artBrief = articleText ? this._briefArticle(articleText) : "";
      const systemPrompt = "你是任务拆解助手。把任务拆成 3-8 个可执行子步骤，并给一句见解精要。只输出 JSON 对象，格式：{\"insight\":\"一句话精要\",\"children\":[{\"text\":\"子步骤\",\"why\":\"为何这一步\"}]}，不要输出任何 JSON 之外的内容。";
      const userPrompt = `任务：${taskText}\n现有子节点：${existing || "无"}\n${artBrief ? "关联文章（已截断，供参考）：\n" + artBrief : "（无关联文章，仅按任务本身拆解）"}`;
      try {
        const raw = await callHatchLLM(systemPrompt, userPrompt);
        const data = extractJSON(raw);
        if (!data || !Array.isArray(data.children) || !data.children.length) { toast("AI 未返回有效拆解，请重试", "warn"); return; }
        this.pushHistory();
        let added = 0;
        data.children.forEach((c) => {
          const text = (c && c.text || "").trim().slice(0, 60);
          if (!text || (n.children || []).some((x) => x.text === text)) return;
          const child = this.newNode(text, { source: "ai", why: (c.why || "").slice(0, 80) });
          child.type = "child";
          n.children.push(child);
          added++;
        });
        if (data.insight) m.insight = String(data.insight).slice(0, 120);
        if (!added) { toast("AI 拆解结果与现有节点重复", "info"); return; }
        this.render();
        this._showNodePanel(id);
        toast("🧠 已拆解 " + added + " 个节点" + (data.insight ? " · 见解精要已生成" : ""), "success");
        haptic(20);
      } catch (e) {
        toast("AI 拆解失败：" + (e.message || "未知错误"), "error");
      }
    }
    // 0 token 本地复现文章结构到当前节点下
    _localDecompose(id, articleText) {
      const n = this.findNode(id);
      if (!n) return;
      const root = this.parseArticleToTree(articleText);
      if (!root || !(root.children || []).length) { toast("文章未解析出有效结构", "warn"); return; }
      this.pushHistory();
      n.children.push(...root.children);
      // 见解精要：取文章标题 + 首个主要小节标题，清洗 Markdown 标记
      const cleanLine = (s) => String(s || "").replace(/^#{1,6}\s+/, "").replace(/^[-*+]\s+/, "").replace(/^\d+[.)]\s+/, "").replace(/\*\*|__|`/g, "").trim();
      const lines = String(articleText || "").split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
      const title = cleanLine(lines[0]) || "";
      const sub = lines.slice(1).map(cleanLine).find((l) => l && l.length > 2) || "";
      n.meta.insight = (title + (sub ? " · " + sub : "")).slice(0, 120);
      this.render();
      this._showNodePanel(id);
      toast("📄 已本地复现文章结构（0 token）· " + root.children.length + " 个节点", "success");
      haptic(20);
    }
    // 省 token：截断文章并压缩空行
    _briefArticle(text) {
      const clean = String(text || "").replace(/\r/g, "").replace(/\n{3,}/g, "\n\n").trim();
      return clean.slice(0, 2500);
    }
    // 💬 打开节点 AI 对话（围绕当前节点多轮问答）
    openNodeChat(id) {
      const n = this.findNode(id);
      if (!n) return;
      this._chatNodeId = id;
      const m = n.meta || (n.meta = {});
      if (!m.chat) m.chat = [];
      let dlg = document.getElementById("mmNodeChatDlg");
      if (!dlg) {
        dlg = document.createElement("dialog");
        dlg.id = "mmNodeChatDlg";
        dlg.className = "mm-node-chat-dlg";
        dlg.innerHTML =
          '<div class="mnc-head"><span class="mnc-title">💬 AI 对话</span><button type="button" class="icon-btn mnc-close">✕</button></div>'
          + '<div class="mnc-log" id="mncLog"></div>'
          + '<div class="mnc-chips" id="mncChips">'
          +   '<button type="button" data-q="拆解成 3-5 个可执行子步骤">拆解子步骤</button>'
          +   '<button type="button" data-q="补充执行细节">补充细节</button>'
          +   '<button type="button" data-q="指出可能踩的坑">指出风险</button>'
          +   '<button type="button" data-q="给出完成验收标准">完成标准</button>'
          +   '<button type="button" data-a="incubate" class="mnc-incubate" title="把最近一条 AI 回复解析为子节点上板">🥚 孵化上板</button>'
          + '</div>'
          + '<div class="mnc-input-row">'
          +   '<input type="text" id="mncInput" class="mnc-input" placeholder="问这个节点…" />'
          +   '<button type="button" id="mncSend" class="primary-btn">发送</button>'
          + '</div>';
        document.body.appendChild(dlg);
        dlg.querySelector(".mnc-close").addEventListener("click", () => dlg.close());
        dlg.querySelector("#mncSend").addEventListener("click", () => this.sendNodeChat());
        dlg.querySelector("#mncInput").addEventListener("keydown", (e) => { if (e.key === "Enter") this.sendNodeChat(); });
        dlg.querySelectorAll("#mncChips button").forEach((b) => {
          b.addEventListener("click", () => {
            if (b.dataset.a === "incubate") { this.incubateChatOntoMap(); return; }
            const inp = dlg.querySelector("#mncInput");
            if (inp) inp.value = b.dataset.q || "";
            this.sendNodeChat();
          });
        });
      }
      dlg.querySelector(".mnc-title").textContent = "💬 AI 对话 · " + String(n.text || "").slice(0, 12);
      this._renderNodeChatLog();
      dlg.showModal();
      setTimeout(() => { const i = dlg.querySelector("#mncInput"); if (i) i.focus(); }, 60);
    }
    _renderNodeChatLog() {
      const dlg = document.getElementById("mmNodeChatDlg");
      if (!dlg) return;
      const log = dlg.querySelector("#mncLog");
      const n = this.findNode(this._chatNodeId);
      const chat = (n && n.meta && n.meta.chat) || [];
      if (!log) return;
      if (!chat.length) {
        log.innerHTML = '<div class="mnc-empty">围绕这个节点提问，AI 会结合任务内容、子节点和关联文章回答。</div>';
        return;
      }
      log.innerHTML = chat.map((msg) => {
        const cls = msg.role === "user" ? "user" : "bot";
        return '<div class="mnc-msg ' + cls + '"><div class="mnc-bubble">' + mdLite(escapeHtml(msg.content || "")) + '</div></div>';
      }).join("");
      log.scrollTop = log.scrollHeight;
    }
    async sendNodeChat() {
      const dlg = document.getElementById("mmNodeChatDlg");
      if (!dlg) return;
      const input = dlg.querySelector("#mncInput");
      const send = dlg.querySelector("#mncSend");
      const text = (input.value || "").trim();
      if (!text) return;
      const n = this.findNode(this._chatNodeId);
      if (!n) return;
      const m = n.meta || (n.meta = {});
      const chat = m.chat || (m.chat = []);
      const noApi = !state.settings.apiUrl || !state.settings.apiKey;
      if (noApi) { toast("未配置 AI API（设置 → AI 配置）", "warn"); return; }
      chat.push({ role: "user", content: text });
      input.value = "";
      if (send) { send.disabled = true; send.textContent = "…"; }
      this._renderNodeChatLog();
      const log = dlg.querySelector("#mncLog");
      const botDiv = document.createElement("div");
      botDiv.className = "mnc-msg bot";
      botDiv.innerHTML = '<div class="mnc-bubble">⏳ AI 思考中…</div>';
      log.appendChild(botDiv);
      log.scrollTop = log.scrollHeight;
      const botEl = botDiv.querySelector(".mnc-bubble");
      // 省 token：上下文只带节点+子节点+文章摘要+最近 8 条历史
      const childrenTxt = (n.children || []).map((c) => c.text).filter(Boolean).join("；");
      const article = m.article_text ? this._briefArticle(m.article_text).slice(0, 1500) : "";
      const history = chat.slice(-8).map((x) => (x.role === "user" ? "用户：" : "助手：") + x.content).join("\n");
      const systemPrompt = "你是思维导图节点助手，围绕用户当前聚焦的任务节点回答问题或给建议。回答简洁、可执行、用中文。用户要求拆解时输出子步骤列表；要求细节/风险/标准时用要点回答。";
      const userPrompt = `当前节点：${n.text}\n现有子节点：${childrenTxt || "无"}\n${article ? "关联文章（摘要）：\n" + article : ""}\n\n${history ? "对话历史：\n" + history + "\n\n" : ""}用户最新输入：${text}`;
      try {
        const raw = await callHatchLLM(systemPrompt, userPrompt, undefined, (full) => {
          if (this._chatRAF) return;
          this._chatRAF = requestAnimationFrame(() => {
            this._chatRAF = 0;
            if (botEl) botEl.innerHTML = mdLite(escapeHtml(full));
            if (log) log.scrollTop = log.scrollHeight;
            // Round5：流式中识别可上板结构 → 高亮孵化按钮
            this._pendingIncubateText = full;
            this._nudgeStreamIncubate(full, dlg);
          });
        });
        if (botEl) botEl.innerHTML = mdLite(escapeHtml(raw || "（无回复）"));
        // 避免流式中途上板已写入时再重复一条（末条为 raw 前缀则更新）
        const lastMsg = chat.length ? chat[chat.length - 1] : null;
        const finalTxt = raw || "";
        if (lastMsg && lastMsg.role === "assistant" && (lastMsg.content === finalTxt || finalTxt.indexOf(lastMsg.content) === 0)) {
          lastMsg.content = finalTxt;
        } else {
          chat.push({ role: "assistant", content: finalTxt });
        }
        this._pendingIncubateText = finalTxt;
        this._nudgeStreamIncubate(finalTxt, dlg);
      } catch (err) {
        const aborted = err && (err.name === "AbortError" || /abort/i.test(err.message || ""));
        const msg = aborted ? "⚠ 请求超时，请重试" : "⚠ " + (err.message || "请求失败");
        if (botEl) botEl.textContent = msg;
        if (!input.value.trim()) input.value = text;
      } finally {
        if (send) { send.disabled = false; send.textContent = "发送"; }
      }
    }
    // Round5：流式回复出现结构列表时点亮「可上板」提示
    _nudgeStreamIncubate(text, dlg) {
      dlg = dlg || document.getElementById("mmNodeChatDlg");
      if (!dlg) return;
      const chip = dlg.querySelector(".mnc-incubate");
      if (!chip) return;
      const items = this.parseIncubateItems(text);
      const ready = items.length >= 2;
      chip.classList.toggle("ready", ready);
      if (ready) {
        chip.textContent = "🥚 可上板 · " + items.length;
        chip.title = "检测到 " + items.length + " 条可上板步骤，点击孵化";
      } else {
        chip.textContent = "🥚 孵化上板";
        chip.title = "把最近一条 AI 回复解析为子节点上板";
      }
      let banner = dlg.querySelector(".mnc-stream-board");
      if (ready) {
        if (!banner) {
          banner = document.createElement("button");
          banner.type = "button";
          banner.className = "mnc-stream-board";
          banner.addEventListener("click", () => this.incubateChatOntoMap());
          const chips = dlg.querySelector("#mncChips");
          if (chips) chips.parentNode.insertBefore(banner, chips);
          else dlg.appendChild(banner);
        }
        banner.hidden = false;
        banner.textContent = "📋 检测到 " + items.length + " 步结构 · 点此上板";
      } else if (banner) {
        banner.hidden = true;
      }
    }
    // Round3/4：把节点 AI 对话最近助手回复解析为子节点并上板（优先 JSON）
    parseIncubateItems(raw) {
      const text = String(raw || "");
      const items = [];
      const push = (t, kids) => {
        t = String(t || "").replace(/\*\*|__/g, "").trim();
        if (!t || t.length < 2 || t.length > 80) return;
        if (/^(注意|总结|综上|参考|建议|以下|如上|好的|可以)/.test(t)) return;
        if (items.some((x) => x.text === t)) return;
        items.push({ text: t, children: kids || [] });
      };
      // 1) fenced JSON / bare JSON
      let jsonStr = null;
      const fence = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
      if (fence) jsonStr = fence[1].trim();
      else {
        const bare = text.match(/(\[[\s\S]*\]|\{[\s\S]*\})/);
        if (bare) jsonStr = bare[1].trim();
      }
      if (jsonStr) {
        try {
          const data = JSON.parse(jsonStr);
          const arr = Array.isArray(data) ? data
            : (data.children || data.steps || data.items || data.nodes || []);
          if (Array.isArray(arr) && arr.length) {
            arr.forEach((it) => {
              if (typeof it === "string") push(it);
              else if (it && typeof it === "object") {
                const kids = [];
                (it.children || it.steps || []).forEach((c) => {
                  const ct = typeof c === "string" ? c : (c.text || c.title || c.name || "");
                  if (ct) kids.push(String(ct).trim());
                });
                push(it.text || it.title || it.name || it.label || "", kids.filter(Boolean).slice(0, 4));
              }
            });
          }
        } catch (e) { /* fall through */ }
      }
      // 2) line heuristic
      if (!items.length) {
        text.split(/\r?\n/).map((l) => l.trim()).filter(Boolean).forEach((l) => {
          let t = l
            .replace(/^#{1,6}\s+/, "")
            .replace(/^[-*+•]\s+/, "")
            .replace(/^\d+[.)、]\s*/, "")
            .replace(/^\(?\d+\)?[.)、]\s*/, "")
            .replace(/\*\*|__/g, "")
            .trim();
          push(t);
        });
      }
      return items.slice(0, 10);
    }
    incubateChatOntoMap() {
      const n = this.findNode(this._chatNodeId);
      if (!n) { toast("未选中节点", "info"); return; }
      const m = n.meta || (n.meta = {});
      const chat = m.chat || (m.chat = []);
      let last = this._pendingIncubateText || null;
      if (!last) {
        for (let i = chat.length - 1; i >= 0; i--) {
          if (chat[i].role === "assistant" && chat[i].content) { last = chat[i].content; break; }
        }
      }
      if (!last) { toast("先和 AI 对话（如点「拆解子步骤」），再点孵化上板", "info"); return; }
      // 流式中途点上板：确保回复已写入 chat
      if (this._pendingIncubateText && !chat.some((msg) => msg.role === "assistant" && msg.content === this._pendingIncubateText)) {
        chat.push({ role: "assistant", content: this._pendingIncubateText });
      }
      const items = this.parseIncubateItems(last);
      if (!items.length) { toast("未能从回复中解析出可上板的步骤", "warn"); return; }
      // Round4：≥3 条时预览确认，避免误上板
      if (items.length >= 3) {
        const preview = items.map((it, i) => (i + 1) + ". " + it.text + (it.children && it.children.length ? "（+" + it.children.length + "）" : "")).join("\n");
        if (!confirm("将上板 " + items.length + " 项到「" + trunc(n.text || "节点", 16) + "」：\n\n" + preview + "\n\n确认？")) return;
      }
      this.pushHistory();
      if (n.collapsed) n.collapsed = false;
      let added = 0;
      items.forEach((it) => {
        if ((n.children || []).some((c) => c.text === it.text)) return;
        const child = this.newNode(it.text, { source: "chat-incubate" });
        child.type = (n._isRoot || n.type === "main") ? "side" : "child";
        (it.children || []).forEach((ct) => {
          const gc = this.newNode(ct, { source: "chat-incubate" });
          gc.type = "child";
          child.children.push(gc);
        });
        n.children.push(child);
        added++;
      });
      if (!added) { toast("解析结果与现有子节点重复", "info"); return; }
      this.save();
      this.render();
      this.centerOn(n.id);
      this._showNodePanel(n.id);
      haptic(20);
      toast("🥚 已孵化上板 " + added + " 个节点", "success");
      const dlg = document.getElementById("mmNodeChatDlg");
      if (dlg && dlg.open) dlg.close();
    }
    // Round4：按布局方向导航（lr/tb/radial）
    navigateRelative(dir) {
      const id = this.selectedId;
      if (!id) return;
      const n = this.findNode(id);
      if (!n) return;
      const parent = this.findParent(id);
      const layout = this.layout || "lr";
      const go = (nid) => {
        if (!nid) return;
        this.selectedId = nid;
        this._showNodePanel(nid);
        this.render();
        this.centerOn(nid);
        haptic(10);
      };
      // tb：上下深入/返回，左右兄弟；lr/radial：左右深入/返回，上下兄弟
      const deepAxis = (layout === "tb")
        ? { parent: "up", child: "down", prev: "left", next: "right" }
        : { parent: "left", child: "right", prev: "up", next: "down" };
      if (dir === deepAxis.parent) {
        if (parent) go(parent.id);
        return;
      }
      if (dir === deepAxis.child) {
        if (n.collapsed && n.children && n.children.length) {
          n.collapsed = false;
          this.pushHistory();
        }
        if (n.children && n.children.length) go(n.children[0].id);
        return;
      }
      if (!parent) return;
      const idx = parent.children.findIndex((c) => c.id === id);
      if (dir === deepAxis.prev && idx > 0) go(parent.children[idx - 1].id);
      if (dir === deepAxis.next && idx < parent.children.length - 1) go(parent.children[idx + 1].id);
    }
    toggleFold(id) {
      const n = this.findNode(id || this.selectedId);
      if (!n || n._isRoot) { toast("根节点请用手风琴折叠各主线", "info"); return; }
      if (!(n.children || []).length) { toast("无子节点可折叠", "info"); return; }
      this.pushHistory();
      n.collapsed = !n.collapsed;
      this.render();
      this.centerOn(n.id);
      toast(n.collapsed ? "已折叠本支" : "已展开本支", "info", 1400);
    }
    // Round4：手风琴——折叠同级其他分支，只展开当前
    accordionSiblings(id) {
      const n = this.findNode(id || this.selectedId);
      if (!n) return;
      const parent = this.findParent(n.id) || (n._isRoot ? n : null);
      const host = n._isRoot ? n : parent;
      if (!host || !(host.children || []).length) return;
      this.pushHistory();
      const keepId = n._isRoot ? null : n.id;
      host.children.forEach((c) => {
        if (!(c.children || []).length) return;
        c.collapsed = keepId ? (c.id !== keepId) : false;
      });
      if (!n._isRoot && (n.children || []).length) n.collapsed = false;
      this.render();
      this.centerOn(n.id);
      toast("▤ 手风琴：已折叠同级其他分支", "success", 1800);
    }
    editNode(id) {
      const n = this.findNode(id);
      if (!n) return;
      this.selectedId = id;
      const fe = this.els.floatEdit;
      const input = this.els.floatInput;
      input.value = n.text;
      const p = this._nodePos && this._nodePos.get(id);
      const rect = this.els.canvas.getBoundingClientRect();
      const sx = p.x * this.view.scale + this.view.x;
      const sy = p.y * this.view.scale + this.view.y;
      fe.style.left = Math.max(4, Math.min(rect.width - 260, sx - 6)) + "px";
      fe.style.top = Math.max(4, sy - 50) + "px";
      fe.hidden = false;
      input.focus();
      input.select();
      fe.dataset.editing = id;
      this._finishEdit = (save) => {
        fe.hidden = true;
        const cur = fe.dataset.editing;
        delete fe.dataset.editing;
        if (save && cur) {
          const node = this.findNode(cur);
          if (node) {
            const v = input.value.trim();
            if (v && v !== node.text) { this.pushHistory(); node.text = v; this.render(); this._showNodePanel(cur); }
          }
        }
      };
    }
    addChild(id) {
      const n = this.findNode(id);
      if (!n) return;
      const child = this.newNode("新节点", {});
      child.type = (n._isRoot || n.type === "main") ? "side" : "child";
      if (n.collapsed) n.collapsed = false;
      n.children.push(child);
      this.pushHistory();
      this.selectedId = child.id;
      this.render();
      this.editNode(child.id);
    }
    deleteNode(id) {
      const n = this.findNode(id);
      if (!n || n._isRoot) { toast("根节点不能删除", "info"); return; }
      const parent = this.findParent(id);
      if (!parent) return;
      const idx = parent.children.findIndex((c) => c.id === id);
      if (idx >= 0) {
        this.pushHistory();
        parent.children.splice(idx, 1);
        if (this.selectedId === id) this.selectedId = parent.id;
        this.render();
        toast("已删除节点（可 Ctrl+Z 撤销）", "info");
      }
    }
    moveNode(id, dir) {
      const parent = this.findParent(id);
      if (!parent) return;
      const idx = parent.children.findIndex((c) => c.id === id);
      const to = idx + dir;
      if (to < 0 || to >= parent.children.length) { toast("已在边界", "info"); return; }
      this.pushHistory();
      const [n] = parent.children.splice(idx, 1);
      parent.children.splice(to, 0, n);
      this.render();
    }
    promote(id) {
      // 提升：上移为父节点的兄弟（插到父节点之后）
      const n = this.findNode(id);
      if (!n || n._isRoot) return;
      const parent = this.findParent(id);
      const grand = this.findParent(parent && parent.id);
      if (!parent || !grand || parent._isRoot) { toast("已在最外层", "info"); return; }
      this.pushHistory();
      const idx = parent.children.findIndex((c) => c.id === id);
      const [node] = parent.children.splice(idx, 1);
      node.type = parent.type === "side" ? "main" : "side";
      const pidx = grand.children.findIndex((c) => c.id === parent.id);
      grand.children.splice(pidx + 1, 0, node);
      this.render();
    }
    demote(id) {
      // 降级：成为前一个兄弟的子节点
      const parent = this.findParent(id);
      if (!parent) return;
      const idx = parent.children.findIndex((c) => c.id === id);
      if (idx <= 0) { toast("没有可挂靠的前一个兄弟", "info"); return; }
      const prev = parent.children[idx - 1];
      const n = parent.children[idx];
      this.pushHistory();
      parent.children.splice(idx, 1);
      n.type = "child";
      prev.children.push(n);
      this.render();
    }
    reparent(id, newParentId) {
      if (id === newParentId) return;
      const n = this.findNode(id);
      const np = this.findNode(newParentId);
      if (!n || !np) return;
      if (n._isRoot) { toast("根节点不能移动", "info"); return; }
      if (np._isRoot && np.children.length >= 24) { toast("根下主线过多（最多 24）", "info"); return; }
      // 防止挂到自己子孙
      let anc = np, guard = 0;
      while (anc && guard++ < 100) { if (anc.id === id) { toast("不能挂到自己的子孙节点", "info"); return; } anc = this.findParent(anc.id); }
      const parent = this.findParent(id);
      if (!parent) return;
      if (parent.id === np.id) { toast("已在该节点下", "info"); return; }
      this.pushHistory();
      const idx = parent.children.findIndex((c) => c.id === id);
      const [node] = parent.children.splice(idx, 1);
      if (node.meta) { node.meta.dx = 0; node.meta.dy = 0; } // v94：改隶属时清手动偏移，融入新布局
      // Round3：挂到根 → 主线；挂到主线 → 支线；其余 → 子步（层级语义清晰）
      if (np._isRoot) node.type = "main";
      else if (np.type === "main" || np._isRoot) node.type = "side";
      else node.type = "child";
      np.children.push(node);
      if (np.collapsed) np.collapsed = false;
      this.selectedId = node.id;
      this.render();
      this.centerOn(node.id);
      toast("已改挂到「" + trunc(np.text || "节点", 12) + "」", "success");
    }

    // ---------- 拖拽视觉（桌面 + 触屏共用）----------
    _beginDragVisual(id, x, y) {
      const nodeEl = this.els.g.querySelector(`[data-node="${id}"]`);
      if (nodeEl) nodeEl.classList.add("mm-drag-source"); // 源节点虚影
      this._dragId = id;
      this._dragTarget = null;
      const n = this.findNode(id);
      this._dragGhost = document.createElement("div");
      this._dragGhost.className = "mm-drag-ghost";
      this._dragGhost.innerHTML = `<span class="sticky-pin">🧠</span>${escapeHtml((n && n.text || "").slice(0, 24))}`;
      document.body.appendChild(this._dragGhost);
      this._dragGhost.style.left = x + "px";
      this._dragGhost.style.top = y + "px";
      this._dragGhost.style.display = "block";
    }
    _moveDragVisual(x, y) {
      if (this._dragGhost) {
        this._dragGhost.style.left = x + "px";
        this._dragGhost.style.top = y + "px";
      }
      const target = document.elementFromPoint(x, y);
      const tNode = target && target.closest ? target.closest("[data-node]") : null;
      const tId = tNode ? tNode.getAttribute("data-node") : null;
      if (tId !== this._dragTarget) {
        this.els.g.querySelectorAll(".mm-drop-hint").forEach((h) => h.remove());
        this._dragTarget = tId;
        if (tId && tId !== this._dragId) {
          const tp = this._nodePos.get(tId);
          if (tp) {
            const hint = document.createElementNS("http://www.w3.org/2000/svg", "rect");
            hint.setAttribute("class", "mm-drop-hint");
            hint.setAttribute("x", tp.x - 3); hint.setAttribute("y", tp.y - 3);
            hint.setAttribute("width", tp.w + 6); hint.setAttribute("height", tp.h + 6);
            hint.setAttribute("rx", 13);
            hint.setAttribute("fill", "none"); hint.setAttribute("stroke", "#ffd93d");
            hint.setAttribute("stroke-width", 2.5);
            hint.setAttribute("stroke-dasharray", "6 4");
            this.els.g.appendChild(hint);
          }
        }
      }
    }
    _endDragVisual(x, y) {
      this.els.g.querySelectorAll(".mm-drop-hint").forEach((h) => h.remove());
      this.els.g.querySelectorAll(".mm-drag-source").forEach((el2) => el2.classList.remove("mm-drag-source"));
      if (this._dragGhost) { this._dragGhost.remove(); this._dragGhost = null; }
      const did = this._dragId;
      const target = (x != null && y != null) ? document.elementFromPoint(x, y) : null;
      const tNode = target && target.closest ? target.closest("[data-node]") : null;
      const tId = tNode ? tNode.getAttribute("data-node") : null;
      this._dragId = null;
      this._dragTarget = null;
      // 拖到节点上 → 改隶属（清手动偏移，融入新位置）
      if (did && tId && tId !== did) {
        const n = this.findNode(did);
        if (n && n.meta) { n.meta.dx = 0; n.meta.dy = 0; }
        this.reparent(did, tId);
        return;
      }
      // v94 自由摆放：拖到空白处松手 → 节点落在指针处（相对自动布局记偏移，连线自动跟随）
      if (did && x != null && y != null && !tId) {
        const n = this.findNode(did);
        const p = this._nodePos.get(did);
        if (n && p) {
          const rect = this.els.canvas.getBoundingClientRect();
          const cx = (x - rect.left - this.view.x) / this.view.scale; // 屏幕 → 画布逻辑坐标
          const cy = (y - rect.top - this.view.y) / this.view.scale;
          const curDx = (n.meta && n.meta.dx) || 0, curDy = (n.meta && n.meta.dy) || 0;
          const ndx = curDx + (cx - p.x), ndy = curDy + (cy - p.y);
          if (Math.abs(ndx - curDx) > 2 || Math.abs(ndy - curDy) > 2) {
            n.meta = n.meta || {};
            // Round3：自由摆放吸附 10px 网格，减少抖动错位
            n.meta.dx = Math.round(ndx / 10) * 10;
            n.meta.dy = Math.round(ndy / 10) * 10;
            this.pushHistory();
            this.save();
            this.render();
            this.centerOn(did);
            haptic(12);
            toast("📍 已摆放（吸附网格）· 拖到节点=改隶属 · ⟳=恢复自动布局", "info", 2400);
          }
        }
      }
    }

    // ---------- 搜索 ----------
    search(q) {
      const res = this.els.searchRes;
      if (!q) { res.hidden = true; res.innerHTML = ""; this._searchList = []; this.render(); return; }
      const hits = [];
      this.walk(this.root, (n) => {
        if (!n._isRoot && (n.text || "").toLowerCase().includes(q.toLowerCase())) hits.push(n);
      });
      this._searchList = hits;
      if (!hits.length) {
        res.innerHTML = `<div class="mm-sr-empty">无匹配节点</div>`;
      } else {
        res.innerHTML = hits.slice(0, 12).map((n, i) =>
          `<div class="mm-sr-item" data-id="${n.id}">${i + 1}. ${escapeHtml(trunc(n.text, 40))}</div>`).join("")
          + (hits.length > 12 ? `<div class="mm-sr-more">…共 ${hits.length} 个匹配</div>` : "");
      }
      res.hidden = false;
      // 高亮
      this._highlightIds = new Set(hits.map((h) => h.id));
      this.render();
    }

    // ---------- 大纲 ----------
    renderOutline() {
      const out = this.els.outline;
      if (!this.outlineOpen) { out.hidden = true; return; }
      const lines = [];
      const walk = (n, depth) => {
        const prefix = "　".repeat(Math.max(0, depth - 1)) + (depth === 0 ? "🧠 " : (n.type === "side" ? "└ " : (n.type === "child" ? "· " : "• ")));
        const min = n.meta && n.meta.est_min ? `（${n.meta.est_min}min）` : "";
        lines.push(`<div class="mm-ol-item" data-id="${n.id}" style="padding-left:${depth * 16}px;">${prefix}${escapeHtml(n.text)}${min}</div>`);
        n.children.forEach((c) => walk(c, depth + 1));
      };
      walk(this.root, 0);
      out.innerHTML = lines.join("");
      out.hidden = false;
      out.querySelectorAll(".mm-ol-item").forEach((it) => {
        it.addEventListener("click", () => {
          this.selectedId = it.dataset.id;
          this.centerOn(it.dataset.id);
          this.render();
        });
        // 双击大纲项 → 直接编辑该节点文本
        it.addEventListener("dblclick", () => this.editNode(it.dataset.id));
      });
    }

    // ---------- 导出 ----------
    exportPng() {
      if (!this.root) { toast("没有可导出的内容", "info"); return; }
      try {
        const clone = this.els.svg.cloneNode(true);
        clone.setAttribute("xmlns", "http://www.w3.org/2000/svg");
        clone.setAttribute("xmlns:xlink", "http://www.w3.org/1999/xlink");
        const b = this._bbox;
        const pad = 30;
        const W = Math.round(b.maxX - b.minX) + pad * 2;
        const H = Math.round(b.maxY - b.minY) + pad * 2;
        clone.setAttribute("width", W);
        clone.setAttribute("height", H);
        clone.setAttribute("viewBox", `${b.minX - pad} ${b.minY - pad} ${W} ${H}`);
        // 清掉交互浮层
        clone.querySelectorAll("[data-node]").forEach((g) => {
          g.classList && g.classList.remove("mm-node-sel");
        });
        const xml = new XMLSerializer().serializeToString(clone);
        const svgUrl = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(xml);
        const img = new Image();
        img.onload = () => {
          const scale = 2;
          const canvas = document.createElement("canvas");
          canvas.width = W * scale; canvas.height = H * scale;
          const ctx = canvas.getContext("2d");
          ctx.fillStyle = "#14141f";
          ctx.fillRect(0, 0, canvas.width, canvas.height);
          ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
          canvas.toBlob((blob) => {
            if (!blob) { toast("PNG 导出失败", "error"); return; }
            const a = document.createElement("a");
            a.href = URL.createObjectURL(blob);
            const d = new Date(); const p = (n) => String(n).padStart(2, "0");
            a.download = `孵化思维导图_${d.getFullYear()}${p(d.getMonth() + 1)}${p(d.getDate())}_${p(d.getHours())}${p(d.getMinutes())}.png`;
            document.body.appendChild(a); a.click(); document.body.removeChild(a);
            setTimeout(() => URL.revokeObjectURL(a.href), 5000);
            toast("已导出思维导图 PNG（2x 高清）", "success");
          }, "image/png");
        };
        img.onerror = () => toast("PNG 导出失败（SVG 序列化异常）", "error");
        img.src = svgUrl;
      } catch (e) {
        toast("PNG 导出失败：" + (e.message || e), "error");
      }
    }
    exportText() {
      if (!this.root) return;
      const lines = [];
      const walk = (n, depth) => {
        const min = n.meta && n.meta.est_min ? `（${n.meta.est_min}min）` : "";
        const dim = n.meta && n.meta.target_dim ? ` [${n.meta.target_dim}]` : "";
        const risk = n.meta && n.meta.risk === "high" ? " ⚠高" : (n.meta && n.meta.risk === "med" ? " ⚠中" : "");
        lines.push("  ".repeat(depth) + (depth === 0 ? "🧠 " : "- ") + n.text + min + dim + risk);
        n.children.forEach((c) => walk(c, depth + 1));
      };
      walk(this.root, 0);
      const totalMin = this._sumMin(this.root);
      const text = lines.join("\n") + `\n\n共 ${this._countNodes(this.root)} 节点 · 预估 ${totalMin || 0} 分钟`;
      copyText(text);
      toast("已复制文本大纲", "success");
    }
    exportMermaid() {
      if (!this.root) return;
      const esc = (s) => String(s || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/[\[\](){}|#]/g, " ").replace(/"/g, "＂").replace(/\n/g, " ").slice(0, 60);
      const lines = ["flowchart TD"];
      const ids = new Map();
      let seq = 0;
      const walk = (n, parentId) => {
        const id = "N" + seq++;
        ids.set(n.id, id);
        const cls = n._isRoot ? "" : (n.type === "side" ? ":::side" : (n.type === "child" ? ":::child" : ":::main"));
        lines.push(`${id}["${esc(n.text)}${n.meta && n.meta.est_min ? ` (${n.meta.est_min}min)` : ""}"]${cls}`);
        if (parentId) lines.push(`${parentId} --> ${id}`);
        n.children.forEach((c) => walk(c, id));
      };
      walk(this.root, null);
      lines.push("classDef main fill:#241f4a,stroke:#7c5cff,color:#c9bfff;");
      lines.push("classDef side fill:#3a2a12,stroke:#ffa94d,color:#ffd9a8;");
      lines.push("classDef child fill:#102a3a,stroke:#4dc3ff,color:#b8e8ff;");
      copyText(lines.join("\n"));
      toast("已复制 Mermaid 语法", "success");
    }
    exportMarkdown() {
      if (!this.root) return;
      const lines = [];
      const walk = (n, depth) => {
        const indent = "  ".repeat(depth);
        const icon = n.meta && n.meta.icon && !n._isRoot ? n.meta.icon + " " : "";
        const min = n.meta && n.meta.est_min ? `（${n.meta.est_min}min）` : "";
        const dim = n.meta && n.meta.target_dim ? ` \`${n.meta.target_dim}\`` : "";
        const risk = n.meta && n.meta.risk === "high" ? " ⚠高" : (n.meta && n.meta.risk === "med" ? " ⚠中" : "");
        const note = n.meta && n.meta.note ? ` — ${n.meta.note}` : "";
        lines.push(`${indent}${depth === 0 ? "# " : "- "}${icon}${n.text}${min}${dim}${risk}${note}`);
        n.children.forEach((c) => walk(c, depth + 1));
      };
      walk(this.root, 0);
      const totalMin = this._sumMin(this.root);
      lines.push(`\n> 共 ${this._countNodes(this.root)} 节点 · 预估 ${totalMin || 0} 分钟`);
      copyText(lines.join("\n"));
      toast("已复制 Markdown 大纲（含图标/时长/维度/备注）", "success");
    }
    // 导出为独立 HTML 文件（浏览器直接打开即可查看导图，可分享）
    exportHtml() {
      if (!this.root) return;
      const data = JSON.stringify({ root: this.root, taskText: this.root.text || "思维导图", exportedAt: new Date().toISOString() });
      const html = `<!DOCTYPE html><html lang="zh"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(this.root.text || "思维导图")}</title><style>
body{font-family:system-ui,sans-serif;background:#0f0f1e;color:#e8e8f0;margin:0;padding:20px}h1{font-size:20px;margin:0 0 16px}.node{position:absolute;background:#1e1e38;border:1px solid #7c5cff;border-radius:10px;padding:8px 12px;font-size:13px;white-space:nowrap}.node.root{background:linear-gradient(135deg,#7c5cff,#5b8cff);font-weight:700;color:#fff}.node .meta{font-size:10px;color:#9a9ab8;margin-top:3px}svg{position:absolute;top:0;left:0;z-index:-1}
</style></head><body><h1>${escapeHtml(this.root.text || "思维导图")}</h1><div id="w" style="position:relative"></div><script>
const DATA=${data};const root=DATA.root;const w=document.getElementById('w');const svgNS='http://www.w3.org/2000/svg';const svg=document.createElementNS(svgNS,'svg');w.appendChild(svg);const pos=new Map();let slot=0;function calc(n,d){if(!n.children.length||n.collapsed){n._s=slot++}else{n.children.forEach(c=>calc(c,d+1));n._s=(n.children[0]._s+n.children[n.children.length-1]._s)/2}}calc(root,0);function place(n,d){const x=d*250,y=n._s*60;pos.set(n.id,{x,y,w:200,h:44});n.children.forEach(c=>place(c,d+1))}place(root,0);let maxW=0,maxH=0;pos.forEach(p=>{maxW=Math.max(maxW,p.x+p.w);maxH=Math.max(maxH,p.y+p.h)});svg.setAttribute('width',maxW+20);svg.setAttribute('height',maxH+20);function walk(n){const p=pos.get(n.id);n.children.forEach(c=>{const cp=pos.get(c.id);const ln=document.createElementNS(svgNS,'path');ln.setAttribute('d','M '+(p.x+p.w)+' '+(p.y+p.h/2)+' C '+(p.x+40)+' '+(p.y+p.h/2)+', '+(cp.x-40)+' '+(cp.y+cp.h/2)+', '+cp.x+' '+(cp.y+cp.h/2));ln.setAttribute('stroke','rgba(124,92,255,.5)');ln.setAttribute('stroke-width','2');ln.setAttribute('fill','none');svg.appendChild(ln);walk(c)});const d=document.createElement('div');d.className='node'+(n._isRoot?' root':'');d.style.left=p.x+'px';d.style.top=p.y+'px';d.style.width=p.w+'px';d.style.minHeight=p.h+'px';d.innerHTML=n.text+(n.meta&&n.meta.est_min?'<div class="meta">⏱'+n.meta.est_min+'min'+(n.meta.done?' · ✅':'' )+'</div>':'');w.appendChild(d)}walk(root);
</script></body></html>`;
      const blob = new Blob([html], { type: "text/html;charset=utf-8" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `${(this.root.text || "mindmap").replace(/[\\/:*?"<>|]/g, "")}.html`;
      a.click();
      setTimeout(() => URL.revokeObjectURL(url), 2000);
      toast("已导出交互式 HTML（浏览器打开即可查看/分享）", "success");
    }

    // ---------- 保存 / 应用 ----------
    save() {
      if (!this.root) return;
      const list = load(MINDMAP_KEY, []);
      const taskText = (this.els.title ? this.els.title.textContent : "") || this.root.text || "未命名导图";
      let rec = null;
      // upsert：从已保存库打开的导图按 id 更新；否则新建（避免同一张导图反复保存产生重复条目）
      if (this._openedFrom && this._openedFrom.mode === "saved" && this._openedFrom.id) {
        rec = list.find((r) => r.id === this._openedFrom.id) || null;
        if (rec) {
          // 存档旧版本（保留最近 10 版，可回退）
          if (!rec.history) rec.history = [];
          rec.history.push({ savedAt: rec.updatedAt || Date.now(), root: rec.root, layout: rec.layout });
          if (rec.history.length > 10) rec.history.shift();
          rec.taskText = taskText;
          rec.layout = this.layout;
          rec.root = this.root;
          rec.updatedAt = Date.now();
        }
      }
      if (!rec) {
        rec = {
          id: "mm_" + Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
          taskText,
          createdAt: Date.now(),
          updatedAt: Date.now(),
          layout: this.layout,
          root: this.root,
        };
        list.push(rec);
        this._openedFrom = { mode: "saved", id: rec.id };
      }
      while (list.length > 100) list.shift();
      try { save(MINDMAP_KEY, list); } catch (e) { console.warn("思维导图保存失败", e); }
      // 同步到当前孵化历史条目（随记录回看）
      try {
        if (hatchState.taskHash) {
          const hist = loadHatchHistory();
          const hit = hist.find((h) => h.task_hash === hatchState.taskHash);
          if (hit) {
            hit.mindmap = { root: this.root, layout: this.layout, savedAt: Date.now() };
            saveHatchHistory(hist);
          }
        }
      } catch (e) {}
      toast("💾 思维导图已保存（导图库可随时打开编辑）", "success");
    }
    // 📚 导图库：多导图管理（打开/新建/重命名/删除/导出）
    openLibrary() {
      this.renderLibrary();
      if (this.els.library) this.els.library.hidden = false;
      if (this.els.outline) this.els.outline.hidden = true;
      if (this.els.nodePanel) this.els.nodePanel.hidden = true;
    }
    closeLibrary() { if (this.els.library) this.els.library.hidden = true; }
    renderLibrary() {
      if (!this.els.library) return;
      const list = load(MINDMAP_KEY, []);
      const fmt = (ts) => { const t = new Date(ts); return `${t.getMonth() + 1}月${t.getDate()}日 ${String(t.getHours()).padStart(2, "0")}:${String(t.getMinutes()).padStart(2, "0")}`; };
      const items = list.length
        ? list.map((r) => {
            const cnt = r.root ? this._countNodes(r.root) : 0;
            return `<div class="mm-lib-item" data-id="${r.id}">
              <div class="mm-lib-main"><div class="mm-lib-title">${escapeHtml(r.taskText || "未命名导图")}</div>
              <div class="mm-lib-meta">${cnt} 节点 · 更新于 ${fmt(r.updatedAt || r.createdAt)}</div></div>
              <div class="mm-lib-actions">
                <button data-a="open" title="打开编辑">打开</button>
                <button data-a="hist" title="历史版本（回退）">历史</button>
                <button data-a="rename" title="重命名">改名</button>
                <button data-a="export" title="导出为 JSON 文件">导出</button>
                <button data-a="del" title="删除（不可恢复）">删</button>
              </div>
            </div>`;
          }).join("")
        : `<div class="mm-lib-empty">暂无导图 · 点下方「＋ 新建」创建一张空白导图</div>`;
      this.els.library.innerHTML = `<div class="mm-lib-head"><span>📚 导图库（${list.length}）</span><button id="mmLibTpl" class="mm-tb">📄 模板</button><button id="mmLibNew" class="mm-tb">＋ 新建空白</button><button id="mmLibClose" class="icon-btn">✕</button></div>
        <div class="mm-lib-list">${items}</div>`;
      const lib = this.els.library;
      lib.querySelector("#mmLibClose").addEventListener("click", () => this.closeLibrary());
      lib.querySelector("#mmLibNew").addEventListener("click", () => { this.closeLibrary(); this.openBlank(); });
      lib.querySelector("#mmLibTpl").addEventListener("click", () => this.showTemplates());
      lib.querySelectorAll(".mm-lib-item").forEach((el) => {
        const id = el.dataset.id;
        el.querySelector('[data-a="open"]').addEventListener("click", () => {
          const rec = list.find((r) => r.id === id);
          this.closeLibrary();
          if (rec) this.openSavedMindmap(rec);
        });
        el.querySelector('[data-a="rename"]').addEventListener("click", () => {
          const rec = list.find((r) => r.id === id);
          if (!rec) return;
          const name = prompt("导图名称：", rec.taskText || "");
          if (name && name.trim()) { rec.taskText = name.trim(); save(MINDMAP_KEY, list); this.renderLibrary(); }
        });
        el.querySelector('[data-a="hist"]').addEventListener("click", () => {
          const rec = list.find((r) => r.id === id);
          if (rec) this.showHistory(rec);
        });
        el.querySelector('[data-a="export"]').addEventListener("click", () => {
          const rec = list.find((r) => r.id === id);
          if (rec) { downloadBackupFile(rec, `mindmap-${rec.taskText || id}.json`); toast("导图已导出为文件", "success"); }
        });
        el.querySelector('[data-a="del"]').addEventListener("click", () => {
          const rec = list.find((r) => r.id === id);
          if (!rec) return;
          if (confirm(`删除导图「${rec.taskText || "未命名"}」？此操作不可恢复。`)) {
            const i = list.indexOf(rec);
            list.splice(i, 1);
            save(MINDMAP_KEY, list);
            this.renderLibrary();
            toast("已删除", "info");
          }
        });
      });
    }
    // 📄 模板选择（在导图库浮层内渲染）
    showTemplates() {
      if (!this.els.library) return;
      const tpls = [
        { id: "goal", icon: "🎯", name: "目标拆解", desc: "目标 → 子目标 → 行动 → 验收 → 复盘" },
        { id: "study", icon: "📚", name: "学习计划", desc: "目标 → 资料 → 路径 → 打卡 → 复习 → 输出" },
        { id: "project", icon: "🚀", name: "项目规划", desc: "需求 → 设计 → 拆分 → 执行 → 里程碑" },
      ];
      this.els.library.innerHTML = `<div class="mm-lib-head"><span>📄 选择模板</span><button id="mmLibBack" class="mm-tb">← 返回</button><button id="mmLibClose2" class="icon-btn">✕</button></div>
        <div class="mm-lib-list">
          ${tpls.map((t) => `<div class="mm-lib-item mm-tpl-item" data-tpl="${t.id}">
            <div class="mm-tpl-icon">${t.icon}</div>
            <div class="mm-lib-main"><div class="mm-lib-title">${t.name}</div><div class="mm-lib-meta">${t.desc}</div></div>
            <button class="mm-tb" data-a="use">套用</button>
          </div>`).join("")}
        </div>`;
      const lib = this.els.library;
      lib.querySelector("#mmLibClose2").addEventListener("click", () => this.closeLibrary());
      lib.querySelector("#mmLibBack").addEventListener("click", () => this.renderLibrary());
      lib.querySelectorAll(".mm-tpl-item").forEach((el) => {
        el.addEventListener("click", (e) => {
          if (e.target.closest('[data-a="use"]')) {
            this.closeLibrary();
            this.applyTemplate(el.dataset.tpl);
          }
        });
      });
    }
    // 🕰 版本历史：浏览/回退到某次保存的旧版本
    showHistory(rec) {
      if (!this.els.library) return;
      const hist = (rec.history || []).slice().reverse();
      const fmt = (ts) => { const t = new Date(ts); return `${t.getMonth() + 1}月${t.getDate()}日 ${String(t.getHours()).padStart(2, "0")}:${String(t.getMinutes()).padStart(2, "0")}`; };
      const items = hist.length
        ? hist.map((h, i) => {
            const cnt = h.root ? this._countNodes(h.root) : 0;
            const ver = hist.length - i;
            return `<div class="mm-lib-item" data-ver="${i}">
              <div class="mm-lib-main"><div class="mm-lib-title">版本 ${ver}</div>
              <div class="mm-lib-meta">${cnt} 节点 · ${fmt(h.savedAt)}</div></div>
              <div class="mm-lib-actions"><button data-a="restore">恢复此版本</button></div>
            </div>`;
          }).join("")
        : `<div class="mm-lib-empty">暂无历史版本 · 每次「💾 保存」都会留档上一版（最多 10 版）</div>`;
      this.els.library.innerHTML = `<div class="mm-lib-head"><span>🕰 版本历史：${escapeHtml(rec.taskText || "未命名")}</span><button id="mmLibBack" class="mm-tb">← 返回</button><button id="mmLibClose2" class="icon-btn">✕</button></div>
        <div class="mm-lib-list">${items}</div>`;
      const lib = this.els.library;
      lib.querySelector("#mmLibClose2").addEventListener("click", () => this.closeLibrary());
      lib.querySelector("#mmLibBack").addEventListener("click", () => this.renderLibrary());
      lib.querySelectorAll(".mm-lib-item").forEach((el) => {
        const vi = parseInt(el.dataset.ver, 10);
        el.querySelector('[data-a="restore"]').addEventListener("click", () => {
          const h = hist[vi];
          if (!h || !h.root) return;
          if (!confirm(`恢复到版本 ${hist.length - vi}（${fmt(h.savedAt)}）？当前内容会先留档。`)) return;
          // 当前版本留档
          if (!rec.history) rec.history = [];
          rec.history.push({ savedAt: Date.now(), root: rec.root, layout: rec.layout });
          rec.root = h.root;
          rec.layout = h.layout || "lr";
          rec.updatedAt = Date.now();
          const list = load(MINDMAP_KEY, []);
          const target = list.find((r) => r.id === rec.id);
          if (target) { target.root = rec.root; target.layout = rec.layout; target.updatedAt = rec.updatedAt; target.history = rec.history; }
          save(MINDMAP_KEY, list);
          this.closeLibrary();
          this.openSavedMindmap(rec);
          toast(`已恢复到版本 ${hist.length - vi}`, "success");
        });
      });
    }
    // 📥 转任务：把导图节点转为收集箱任务（附建议 tag + 维度 tag）
    exportToInbox() {
      const steps = this.treeToSteps();
      if (!steps.length) { toast("导图里还没有可转的节点（先保存或添加主线步骤）", "info"); return; }
      const tag = suggestTag(this.root.text || "");
      const existing = new Set(inboxItems.map((i) => (i.text || "").trim()));
      let added = 0;
      steps.forEach((s) => {
        const t = (s.text || "").trim();
        if (!t || existing.has(t)) return;
        existing.add(t);
        inboxItems.push(migrateInboxItem({
          id: "inb_" + Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
          text: t,
          tags: [tag, s.target_dim].filter(Boolean),
          priority: 0, mainline: null, sideline: null, parentId: null,
          due: null, estimate: s.est_min ? String(s.est_min) : null, note: s.why || "",
          done: false, createdAt: Date.now(), links: [], kind: "mindmap",
        }));
        added++;
      });
      if (added) { saveInbox(); renderInboxList(); renderInboxStats(); toast(`📥 已将 ${added} 个节点转入收集箱（tag：${tag || "无"}）`, "success"); }
      else toast("没有新节点可转（可能已存在）", "info");
    }

    // ========== 🔗 导入文章 / 链接 → 自动复现为可编辑导图 ==========
    importArticle() {
      const self = this;
      let dlg = document.getElementById("mmImportDlg");
      if (!dlg) {
        dlg = document.createElement("dialog");
        dlg.id = "mmImportDlg";
        dlg.className = "mm-import-dlg";
        dlg.innerHTML =
          '<div class="mmi-head">🔗 导入文章 → 思维导图</div>'
          + '<div class="mmi-tip">粘贴正文（支持 Markdown 标题 / 列表），或输入链接自动抓取后一键成图</div>'
          + '<div class="mmi-url-row">'
          + '<input type="url" id="mmiUrl" class="mmi-url" placeholder="https://…（可选）" />'
          + '<button type="button" class="tool-btn" id="mmiFetch">🌐 抓取</button>'
          + "</div>"
          + '<div class="mmi-fetch-hint" id="mmiFetchHint">抓取受跨域限制，失败时直接粘贴正文即可</div>'
          + '<textarea id="mmiText" class="mmi-text" rows="10" placeholder="在此粘贴文章正文…&#10;&#10;支持结构：&#10;# 一级标题&#10;## 二级标题&#10;- 列表项&#10;或纯文本分段（每段一个节点）"></textarea>'
          + '<div class="mmi-actions">'
          + '<button type="button" class="tool-btn" id="mmiCancel">取消</button>'
          + '<button type="button" class="tool-btn mmi-ok" id="mmiOk">🧠 生成导图</button>'
          + "</div>";
        document.body.appendChild(dlg);
        dlg.querySelector("#mmiCancel").addEventListener("click", () => dlg.close());
        dlg.querySelector("#mmiFetch").addEventListener("click", () => self.fetchArticleUrl(dlg));
        dlg.querySelector("#mmiOk").addEventListener("click", () => {
          const txt = (dlg.querySelector("#mmiText").value || "").trim();
          if (!txt) { toast("请先粘贴正文，或抓取链接", "info"); return; }
          const root = self.parseArticleToTree(txt);
          if (!root) { toast("未能解析出有效内容", "error"); return; }
          self.root = root;
          self.layout = "lr";
          self._openedFrom = { mode: "article" };
          self._animateIn = true; // 生成即播放上板动效
          try {
            if (typeof hatchState !== "undefined") {
              hatchState.taskText = root.text || "导入文章";
              hatchState.taskHash = hashTaskText(root.text || "导入文章");
              hatchState.result = { steps: [], est_total_min: null };
            }
          } catch (e) { /* 上下文不可用则跳过 */ }
          dlg.close();
          self._open();
          toast("🧠 文章已复现为思维导图 · 可继续编辑保存", "success");
          haptic(20);
        });
      }
      dlg.querySelector("#mmiUrl").value = "";
      dlg.querySelector("#mmiText").value = "";
      const hint = dlg.querySelector("#mmiFetchHint");
      if (hint) hint.textContent = "抓取受跨域限制，失败时直接粘贴正文即可";
      dlg.showModal();
    }
    // 🌐 抓取链接正文（多源降级；失败提示手动粘贴）
    async fetchArticleUrl(dlg) {
      const url = (dlg.querySelector("#mmiUrl").value || "").trim();
      if (!url) { toast("请先输入链接", "info"); return; }
      const hint = dlg.querySelector("#mmiFetchHint");
      const ta = dlg.querySelector("#mmiText");
      const sources = [
        (u) => "https://r.jina.ai/" + u,
        (u) => "https://api.allorigins.win/raw?url=" + encodeURIComponent(u),
      ];
      if (hint) hint.textContent = "抓取中…";
      for (const mk of sources) {
        try {
          const res = await fetch(mk(url), { method: "GET" });
          if (!res.ok) continue;
          const txt = await res.text();
          if (txt && txt.length > 60) {
            ta.value = txt.slice(0, 60000);
            if (hint) hint.textContent = "✓ 已抓取 " + txt.length + " 字符 · 点「生成导图」";
            toast("🌐 抓取成功", "success");
            return;
          }
        } catch (e) { /* 换下一个源 */ }
      }
      if (hint) hint.textContent = "✗ 抓取失败（跨域限制）· 请手动复制正文粘贴到下方";
      toast("抓取失败，请手动粘贴正文", "error");
    }
    // 📄 文章文本 → 导图树（Markdown 标题按级数分层 / 列表项为子步 / 纯文本分段）
    parseArticleToTree(text) {
      const lines = String(text || "").split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
      if (!lines.length) return null;
      const clean = (s) => String(s || "").replace(/^#{1,6}\s+/, "").replace(/^[-*+]\s+/, "").replace(/^\d+[.)]\s+/, "").replace(/\*\*|__|`/g, "").trim();
      const rootText = clean(lines[0]).slice(0, 60) || "导入文章";
      const root = this.newNode(rootText, { source: "article" });
      root._isRoot = true;
      root.type = "main";
      const stack = [{ depth: 0, node: root }];
      let nodes = 0;
      for (let i = 1; i < lines.length && nodes < 220; i++) {
        const raw = lines[i];
        if (/^---+$|^===+$|^\|.*\|$/.test(raw)) continue; // 分隔线/表格跳过
        const hm = raw.match(/^(#{1,6})\s+(.*)$/);
        if (hm) {
          const level = hm[1].length;
          const n = this.newNode(clean(hm[2]).slice(0, 60), { source: "article" });
          n.type = "main";
          while (stack.length > 1 && stack[stack.length - 1].depth >= level) stack.pop();
          stack[stack.length - 1].node.children.push(n);
          stack.push({ depth: level, node: n });
          nodes++;
          continue;
        }
        const lm = raw.match(/^([-*+]|\d+[.)])\s+(.*)$/);
        if (lm) {
          const n = this.newNode(clean(lm[2]).slice(0, 60), { source: "article" });
          n.type = "child";
          stack[stack.length - 1].node.children.push(n);
          nodes++;
          continue;
        }
        if (raw.length > 1 && raw.length < 240) {
          const n = this.newNode(clean(raw).slice(0, 60), { source: "article" });
          n.type = "main";
          stack[stack.length - 1].node.children.push(n);
          nodes++;
        }
      }
      return root;
    }

    // 🔗 跳转：导图节点 → 今日时间格子（按文本匹配）或待办收集箱
    jumpToTask(nodeId) {
      const n = this.findNode(nodeId);
      if (!n) return;
      const text = (n.text || "").trim();
      let found = null;
      outer:
      for (let p = 0; p < PERIOD_COUNT; p++) {
        for (let c = 0; c < CELLS_PER_PERIOD; c++) {
          const arr = getCellTasks(p, c);
          if (arr.some((t) => (t.text || "").trim() === text)) { found = { p, c }; break outer; }
        }
      }
      this.close();
      if (found) {
        jumpToCell(found.p, found.c);
        toast("🔗 已定位到 " + (PERIOD_NAMES[found.p] || ("第" + (found.p + 1) + "辰")) + " 第" + (found.c + 1) + "格", "success");
      } else {
        const ib = document.getElementById("realmFabInbox");
        if (ib) ib.click();
        toast("🔗 该节点未安排到格子 · 已打开待办", "info");
      }
    }

    applyToList() {
      if (!this.root) return;
      const steps = this.treeToSteps();
      if (!steps.length) { toast("导图里还没有主线步骤", "info"); return; }
      const cur = hatchState.result || {};
      const merged = Object.assign({}, cur, {
        steps,
        est_total_min: this._sumMin(this.root) || cur.est_total_min,
      });
      merged.mode = merged.mode || hatchState.mode;
      merged.scene = merged.scene || hatchState.scene;
      renderHatchResult(merged, { keepChat: true, fromMindmap: true });
      toast("✓ 导图已同步到步骤列表", "success");
    }

    // ---------- 打开 / 关闭 ----------
    openFromResult() {
      if (!hatchState.result) { toast("请先完成一次孵化", "info"); return; }
      const rec = hatchState.result;
      const saved = this._findSavedMindmap(hatchState.taskHash);
      if (saved && saved.root) {
        this.root = saved.root;
        this.layout = saved.layout || "lr";
      } else {
        this.root = this.stepsToTree(rec);
        this.layout = "lr";
      }
      this._openedFrom = { mode: "result", hash: hatchState.taskHash };
      this._open();
    }
    openFromHistory(rec) {
      const saved = rec && rec.mindmap;
      if (saved && saved.root) {
        this.root = saved.root;
        this.layout = saved.layout || "lr";
      } else {
        this.root = this.stepsToTree(rec);
        this.layout = "lr";
      }
      this._openedFrom = { mode: "history", hash: rec && rec.task_hash };
      if (hatchState.taskHash !== (rec && rec.task_hash)) {
        // 历史打开时同步 state 以便保存/应用回写正确条目
        hatchState.taskHash = (rec && rec.task_hash) || hatchState.taskHash;
        hatchState.taskText = (rec && rec.task_text) || hatchState.taskText;
        hatchState.result = rec && { steps: rec.steps, est_total_min: rec.est_total_min, mode: rec.last_mode, scene: rec.last_scene };
        hatchState.mode = rec && rec.last_mode;
        hatchState.scene = rec && rec.last_scene;
      }
      this._open();
    }
    // 独立入口：打开独立导图库中保存的某张导图
    openSavedMindmap(rec) {
      if (!rec || !rec.root) { this.openBlank(); return; }
      this.root = rec.root;
      this.layout = rec.layout || "lr";
      this._openedFrom = { mode: "saved", id: rec.id };
      if (rec.taskText) {
        hatchState.taskText = rec.taskText;
        hatchState.taskHash = hashTaskText(rec.taskText);
        hatchState.result = { steps: this.treeToSteps(rec.root), est_total_min: rec.estTotalMin || null };
      }
      this._open();
    }
    // 空白新建：独立思维导图（根节点可编辑）
    openBlank() {
      const root = this.newNode("新思维导图", {});
      root._isRoot = true;
      this.root = root;
      this.layout = "lr";
      this._openedFrom = { mode: "blank" };
      hatchState.taskText = "新思维导图";
      hatchState.taskHash = hashTaskText("新思维导图");
      hatchState.result = { steps: [], est_total_min: null };
      this._open();
    }
    // 📄 导图模板：预设结构骨架，一键套用
    applyTemplate(name) {
      const templates = {
        goal: { root: "🎯 目标拆解", children: ["明确最终目标", "拆分子目标", "制定行动计划", "设定验收标准", "执行与复盘"] },
        study: { root: "📚 学习计划", children: ["明确学习目标", "收集学习资料", "制定学习路径", "每日学习打卡", "定期复习巩固", "实践输出检验"] },
        project: { root: "🚀 项目规划", children: ["需求分析", "方案设计", "任务拆分", "执行推进", "里程碑复盘"] },
      };
      const t = templates[name];
      if (!t) return;
      const root = this.newNode(t.root, {});
      root._isRoot = true;
      t.children.forEach((c) => {
        const n = this.newNode(c, { est_min: 30 });
        n.type = "main";
        root.children.push(n);
      });
      this.root = root;
      this.layout = "lr";
      this._openedFrom = { mode: "blank" };
      hatchState.taskText = t.root;
      hatchState.taskHash = hashTaskText(t.root);
      hatchState.result = { steps: [], est_total_min: null };
      this._open();
      toast(`已套用「${t.root}」模板（${t.children.length} 条主线，双击编辑细节）`, "success");
    }
    _findSavedMindmap(taskHash) {
      try {
        const hist = loadHatchHistory();
        const hit = hist.find((h) => h.task_hash === taskHash);
        if (hit && hit.mindmap && hit.mindmap.root) return hit.mindmap;
        const list = load(MINDMAP_KEY, []);
        return list.filter((r) => r.taskText && hashTaskText(r.taskText) === taskHash).pop() || null;
      } catch (e) { return null; }
    }
    _open() {
      this._animateIn = true; // 打开导图时播放一次「节点上板」动画
      this.seq = 0;
      this._resyncSeq(); // 与已存在节点（历史/导入/自动上板）对齐序号，避免新建节点 id 撞号
      this.history = [];
      this.histIdx = -1;
      this.selectedId = null;
      this.focusId = null;
      this.outlineOpen = false;
      this.view = { x: 0, y: 0, scale: 1 };
      if (this.els.library) this.els.library.hidden = true;
      if (this.els.title) this.els.title.textContent = this.root.text || "孵化思维导图";
      if (this.els.sub) this.els.sub.textContent = this.root._isRoot ? `根：${this.root.text} · 双击节点编辑，拖拽节点到另一节点改隶属` : "双击节点编辑 · 拖拽节点到另一节点改隶属";
      // 空态引导：无主线步骤时提示如何起步
      const empty = !this.root || !this.root.children || !this.root.children.length;
      const isTouch = window.matchMedia && window.matchMedia("(hover: none)").matches;
      if (this.els.hint) {
        this.els.hint.textContent = empty
          ? "💡 双击根节点添加第一条主线步骤 · 选中节点后按 Tab 添加子节点 · 按 ? 查看快捷键"
          : (isTouch
            ? "👆 单指拖动平移 · 双指捏合缩放 · 长拖节点改隶属 · 快速点两下编辑"
            : "🖱 滚轮缩放 · 拖动空白平移 · 点击选中节点 · 双击编辑文本 · 按 ? 查看快捷键");
        this.els.hint.style.background = empty ? "rgba(124,92,255,.16)" : "rgba(15,15,30,.7)";
      }
      // 快捷键帮助面板（懒创建一次）
      let sc = this.els.canvas.querySelector(".mm-shortcuts");
      if (!sc) {
        sc = document.createElement("div");
        sc.className = "mm-shortcuts";
        sc.innerHTML = `<div class="mm-sc-head"><span>⌨ 快捷键</span><button type="button" class="mm-sc-close">✕</button></div>
          <div class="mm-sc-grid">
            <div><b>Tab</b><span>添加子节点</span></div>
            <div><b>Enter</b><span>编辑选中节点</span></div>
            <div><b>Delete</b><span>删除节点（可撤销）</span></div>
            <div><b>↑ ↓ ← →</b><span>方向感知导航（随布局）</span></div>
            <div><b>Alt+↑↓</b><span>同级排序（根下主线）</span></div>
            <div><b>Alt+←/→</b><span>进入关联线绘制</span></div>
            <div><b>C</b><span>折叠/展开本支</span></div>
            <div><b>Shift+C</b><span>手风琴折叠同级</span></div>
            <div><b>Shift+F</b><span>聚焦当前分支</span></div>
            <div><b>F</b><span>聚焦搜索</span></div>
            <div><b>+ / −</b><span>缩放画布</span></div>
            <div><b>0</b><span>适应画布</span></div>
            <div><b>Ctrl+Z / Y</b><span>撤销 / 重做</span></div>
            <div><b>双击节点</b><span>编辑文本</span></div>
            <div><b>拖拽节点</b><span>改隶属 / 空白自由摆放</span></div>
            <div><b>?</b><span>显示/隐藏本面板</span></div>
          </div>`;
        this.els.canvas.appendChild(sc);
        sc.querySelector(".mm-sc-close").addEventListener("click", () => { sc.hidden = true; });
      }
      sc.hidden = true;
      if (this.els.search) { this.els.search.value = ""; }
      if (this.els.nodePanel) { this.els.nodePanel.hidden = true; }
      if (this.els.floatBar) { this.els.floatBar.hidden = true; }
      if (this.els.floatEdit) { this.els.floatEdit.hidden = true; }
      if (this.els.outline) { this.els.outline.hidden = true; }
      if (this.els.searchRes) { this.els.searchRes.hidden = true; }
      if (this.els.undo) this.els.undo.disabled = true;
      if (this.els.redo) this.els.redo.disabled = true;
      this.pushHistory(); // 初始快照
      this.render();
      this.els.dialog.showModal();
      setTimeout(() => this.fit(), 30);
    }
    close() {
      if (this.els.dialog.open) this.els.dialog.close();
    }

    // ---------- 事件绑定 ----------
    _bind() {
      const els = this.els;
      const self = this;
      // 工具栏
      els.undo.addEventListener("click", () => this.undo());
      els.redo.addEventListener("click", () => this.redo());
      els.layout.addEventListener("click", () => {
        // 三态循环：左右 → 上下 → 放射
        this.layout = this.layout === "lr" ? "tb" : (this.layout === "tb" ? "radial" : "lr");
        els.layout.textContent = this.layout === "lr" ? "⇄ 布局" : (this.layout === "tb" ? "⇅ 布局" : "☀ 放射");
        this.render();
        setTimeout(() => this.fit(), 30);
      });
      els.outlineToggle.addEventListener("click", () => {
        this.outlineOpen = !this.outlineOpen;
        this.renderOutline();
      });
      els.zoomIn.addEventListener("click", () => this.zoom(1.25));
      els.zoomOut.addEventListener("click", () => this.zoom(0.8));
      els.fit.addEventListener("click", () => this.fit());
      // v94 ⟳ 恢复自动布局：清除全部手动摆放偏移（拖到空白处自由摆放的节点回归算法位）
      const resetLayoutBtn = document.getElementById("mmResetLayout");
      if (resetLayoutBtn) resetLayoutBtn.addEventListener("click", () => {
        let cleared = 0;
        const walk = (n) => {
          if (!n) return;
          if (n.meta && (n.meta.dx || n.meta.dy)) { n.meta.dx = 0; n.meta.dy = 0; cleared++; }
          (n.children || []).forEach(walk);
        };
        if (this.root) walk(this.root);
        if (!cleared) { toast("没有手动摆放的节点", "info"); return; }
        this.pushHistory();
        this.save();
        this.render();
        setTimeout(() => this.fit(), 30);
        haptic(18);
        toast("⟳ 已恢复自动布局（" + cleared + " 个节点归位）", "success");
      });
      els.exportPng.addEventListener("click", () => this.exportPng());
      els.exportText.addEventListener("click", () => this.exportText());
      els.exportMmd.addEventListener("click", () => this.exportMermaid());
      els.exportMd.addEventListener("click", () => this.exportMarkdown());
      if (els.exportHtml) els.exportHtml.addEventListener("click", () => this.exportHtml());
      els.apply.addEventListener("click", () => this.applyToList());
      els.save.addEventListener("click", () => this.save());
      if (els.libraryBtn) els.libraryBtn.addEventListener("click", () => this.openLibrary());
      if (els.exportInbox) els.exportInbox.addEventListener("click", () => this.exportToInbox());
      if (els.importArticle) els.importArticle.addEventListener("click", () => this.importArticle());
      els.close.addEventListener("click", () => this.close());
      // 搜索
      els.search.addEventListener("input", () => this.search(els.search.value.trim()));
      els.searchRes.addEventListener("click", (e) => {
        const it = e.target.closest(".mm-sr-item");
        if (it) { this.selectedId = it.dataset.id; this.centerOn(it.dataset.id); this.render(); }
      });
      // 画布：缩放
      els.canvas.addEventListener("wheel", (e) => {
        e.preventDefault();
        const rect = els.canvas.getBoundingClientRect();
        this.zoom(e.deltaY < 0 ? 1.12 : 0.89, e.clientX, e.clientY);
      }, { passive: false });
      // 画布：平移 / 拖拽（桌面）
      els.svg.addEventListener("mousedown", (e) => {
        // v94 task ↩ 角标：点击直达时间格子
        const jumpEl = e.target.closest ? e.target.closest("[data-mm-jump]") : null;
        if (jumpEl) { this.jumpToTask(jumpEl.getAttribute("data-mm-jump")); return; }
        const nodeEl = e.target.closest ? e.target.closest("[data-node]") : null;
        if (nodeEl) {
          const id = nodeEl.getAttribute("data-node");
          if (e.button === 0) {
            if (this._linkFrom) {
              this.completeLinkTo(id);
              return;
            }
            this.selectedId = id;
            this._showNodePanel(id);
            this.render();
            this._dragging = { id, moved: false, startX: e.clientX, startY: e.clientY };
          }
          return;
        }
        const foldEl = e.target.closest ? e.target.closest("[data-fold]") : null;
        if (foldEl) {
          const id = foldEl.getAttribute("data-fold");
          const n = this.findNode(id);
          if (n) { n.collapsed = !n.collapsed; this.pushHistory(); this.render(); }
          return;
        }
        // 空白：开始平移
        this._panning = { startX: e.clientX, startY: e.clientY, ox: this.view.x, oy: this.view.y };
        e.preventDefault();
      });
      window.addEventListener("mousemove", (e) => {
        if (this._panning) {
          this.view.x = this._panning.ox + (e.clientX - this._panning.startX);
          this.view.y = this._panning.oy + (e.clientY - this._panning.startY);
          this._applyView();
        }
        if (this._dragging) {
          const d = this._dragging;
          if (!d.moved && Math.abs(e.clientX - d.startX) + Math.abs(e.clientY - d.startY) > 5) {
            d.moved = true;
            this._beginDragVisual(d.id, e.clientX, e.clientY);
          }
          if (d.moved) this._moveDragVisual(e.clientX, e.clientY);
        }
      });
      window.addEventListener("mouseup", (e) => {
        if (this._dragging) {
          const d = this._dragging;
          this._dragging = null;
          if (d.moved) this._endDragVisual(e.clientX, e.clientY);
          else this._endDragVisual();
        }
        this._panning = null;
      });
      // 双击编辑（桌面）
      els.svg.addEventListener("dblclick", (e) => {
        const nodeEl = e.target.closest ? e.target.closest("[data-node]") : null;
        if (nodeEl) this.editNode(nodeEl.getAttribute("data-node"));
      });
      // ================= 触屏支持（安卓手机）=================
      // 单指：空白=平移 / 节点=拖拽改隶属（>8px 判定）/ 未拖动=选中+双触编辑
      // 双指：pinch 缩放（以两指中心为锚）
      let tp = null;
      this._lastTap = null;
      const TAP_MS = 400, DRAG_PX = 8;
      els.canvas.addEventListener("touchstart", (e) => {
        if (!els.dialog || !els.dialog.open) return;
        const touches = e.touches;
        if (touches.length === 1) {
          const t = touches[0];
          const hit = document.elementFromPoint(t.clientX, t.clientY);
          // v94 task ↩ 角标：触屏点击直达时间格子
          const jumpEl = hit && hit.closest ? hit.closest("[data-mm-jump]") : null;
          if (jumpEl) { this.jumpToTask(jumpEl.getAttribute("data-mm-jump")); return; }
          // 折叠按钮
          const foldEl = hit && hit.closest ? hit.closest("[data-fold]") : null;
          if (foldEl) {
            const id = foldEl.getAttribute("data-fold");
            const n = this.findNode(id);
            if (n) { n.collapsed = !n.collapsed; this.pushHistory(); this.render(); }
            return;
          }
          const nodeEl = hit && hit.closest ? hit.closest("[data-node]") : null;
          if (nodeEl) {
            const id = nodeEl.getAttribute("data-node");
            tp = { mode: "node", id, x: t.clientX, y: t.clientY, moved: false };
            this.selectedId = id;
            this.render();
          } else {
            tp = { mode: "pan", x: t.clientX, y: t.clientY, ox: this.view.x, oy: this.view.y };
          }
        } else if (touches.length === 2) {
          const dx = touches[0].clientX - touches[1].clientX, dy = touches[0].clientY - touches[1].clientY;
          tp = { mode: "pinch", d0: Math.max(1, Math.hypot(dx, dy)), s0: this.view.scale, mx: (touches[0].clientX + touches[1].clientX) / 2, my: (touches[0].clientY + touches[1].clientY) / 2, ox: this.view.x, oy: this.view.y };
        }
      }, { passive: true });
      els.canvas.addEventListener("touchmove", (e) => {
        if (!tp) return;
        e.preventDefault();
        const touches = e.touches;
        if (tp.mode === "pinch" && touches.length >= 2) {
          const dx = touches[0].clientX - touches[1].clientX, dy = touches[0].clientY - touches[1].clientY;
          const d = Math.max(1, Math.hypot(dx, dy));
          const rect = els.canvas.getBoundingClientRect();
          const cx = (touches[0].clientX + touches[1].clientX) / 2 - rect.left;
          const cy = (touches[0].clientY + touches[1].clientY) / 2 - rect.top;
          const ns = Math.min(2.5, Math.max(0.2, tp.s0 * (d / tp.d0)));
          const k = ns / tp.s0;
          this.view.x = cx - (cx - tp.ox) * k;
          this.view.y = cy - (cy - tp.oy) * k;
          this.view.scale = ns;
          this._applyView();
        } else if (tp.mode === "pan" && touches.length === 1) {
          const t = touches[0];
          this.view.x = tp.ox + (t.clientX - tp.x);
          this.view.y = tp.oy + (t.clientY - tp.y);
          this._applyView();
        } else if (tp.mode === "node" && touches.length === 1) {
          const t = touches[0];
          if (!tp.moved && Math.abs(t.clientX - tp.x) + Math.abs(t.clientY - tp.y) > DRAG_PX) {
            tp.moved = true;
            this._beginDragVisual(tp.id, t.clientX, t.clientY);
            haptic(15);
          }
          if (tp.moved) this._moveDragVisual(t.clientX, t.clientY);
        }
      }, { passive: false });
      const endTouch = (e) => {
        if (!tp) return;
        const t = e.changedTouches && e.changedTouches[0];
        if (tp.mode === "node") {
          if (tp.moved && t) {
            this._endDragVisual(t.clientX, t.clientY);
            haptic(20);
          } else {
            // Round5：关联绘制模式下点第二个节点即连线
            if (this._linkFrom) {
              this.completeLinkTo(tp.id);
              tp = null;
              return;
            }
            // 未拖动：单击选中 + 双触（500ms 内两次点同一节点）编辑
            const now = Date.now();
            if (this._lastTap && this._lastTap.id === tp.id && now - this._lastTap.t < TAP_MS) {
              this.editNode(tp.id);
              this._lastTap = null;
            } else {
              this._lastTap = { id: tp.id, t: now };
              this._showNodePanel(tp.id);
            }
          }
        }
        tp = null;
      };
      els.canvas.addEventListener("touchend", endTouch, { passive: true });
      els.canvas.addEventListener("touchcancel", endTouch, { passive: true });
      // 触屏拖动 ghost 期间禁止页面滚动
      els.canvas.style.touchAction = "none";
      // 浮层编辑
      els.floatInput.addEventListener("keydown", (e) => {
        e.stopPropagation();
        if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); this._finishEdit && this._finishEdit(true); }
        else if (e.key === "Escape") { e.preventDefault(); this._finishEdit && this._finishEdit(false); }
      });
      els.floatOk.addEventListener("click", () => this._finishEdit && this._finishEdit(true));
      // 浮动操作条（选中节点后出现）：增删改移，触屏/桌面通用；事件隔离画布手势
      // Round1：pointerdown 只 stopPropagation，禁止 preventDefault——否则会吞掉后续 click，按钮点不动
      if (els.floatBar) {
        const stopBubble = (e) => { e.stopPropagation(); };
        els.floatBar.addEventListener("pointerdown", stopBubble);
        els.floatBar.addEventListener("touchstart", stopBubble, { passive: true });
        els.floatBar.addEventListener("click", (e) => {
          e.stopPropagation();
          const btn = e.target.closest("[data-a]");
          if (!btn || !this.selectedId) return;
          const a = btn.dataset.a;
          if (a === "child") this.addChild(this.selectedId);
          else if (a === "edit") this.editNode(this.selectedId);
          else if (a === "fold") this.toggleFold(this.selectedId);
          else if (a === "accordion") this.accordionSiblings(this.selectedId);
          else if (a === "up") this.moveNode(this.selectedId, -1);
          else if (a === "down") this.moveNode(this.selectedId, 1);
          else if (a === "promote") this.promote(this.selectedId);
          else if (a === "focus") this.focusNode(this.selectedId);
          else if (a === "link") this.beginLinkMode(this.selectedId);
          else if (a === "jump") this.jumpToTask(this.selectedId);
          else if (a === "del") this.deleteNode(this.selectedId);
        });
      }
      // 快捷键（dialog 打开时）
      document.addEventListener("keydown", this._keyHandler = (e) => {
        if (!els.dialog || !els.dialog.open) return;
        const editing = !els.floatEdit.hidden;
        const tag = (e.target && e.target.tagName) || "";
        const inField = tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT";
        if (e.key === "Escape") {
          if (editing) { e.stopPropagation(); this._finishEdit && this._finishEdit(false); }
          else if (this._linkFrom) {
            e.preventDefault(); e.stopPropagation();
            this.cancelLinkMode();
          }
          else if (this.focusId) {
            // 聚焦态：Esc 先退出聚焦返回全景
            e.preventDefault(); e.stopPropagation();
            this.clearFocus();
          }
          else if (this.selectedId) {
            // 先取消选中（Esc 第二下才关闭对话框）
            e.preventDefault(); e.stopPropagation();
            this.selectedId = null;
            if (this.els.nodePanel) this.els.nodePanel.hidden = true;
            if (this.els.floatBar) this.els.floatBar.hidden = true;
            this.render();
          }
          return;
        }
        if (inField) return;
        const k = e.key;
        // 快捷键帮助面板（无需选中节点）
        if (k === "?" || k === "/") {
          e.preventDefault();
          const sc = this.els.canvas.querySelector(".mm-shortcuts");
          if (sc) sc.hidden = !sc.hidden;
          return;
        }
        // Shift+F 聚焦；C 折叠；Shift+C 手风琴
        if (e.shiftKey && k.toLowerCase() === "f" && this.selectedId) { e.preventDefault(); this.focusNode(this.selectedId); return; }
        if (e.shiftKey && k.toLowerCase() === "c" && this.selectedId) { e.preventDefault(); this.accordionSiblings(this.selectedId); return; }
        if (!e.shiftKey && k.toLowerCase() === "c" && this.selectedId && !inField) { e.preventDefault(); this.toggleFold(this.selectedId); return; }
        if ((e.ctrlKey || e.metaKey) && k.toLowerCase() === "z") { e.preventDefault(); e.shiftKey ? this.redo() : this.undo(); return; }
        if ((e.ctrlKey || e.metaKey) && k.toLowerCase() === "y") { e.preventDefault(); this.redo(); return; }
        if (!this.selectedId) return;
        // Round5：Alt+↑↓ 同级排序（根下主线顺序）
        if (e.altKey && (k === "ArrowUp" || k === "ArrowDown")) {
          e.preventDefault();
          this.moveNode(this.selectedId, k === "ArrowUp" ? -1 : 1);
          return;
        }
        if (e.altKey && (k === "ArrowLeft" || k === "ArrowRight")) {
          e.preventDefault();
          this.beginLinkMode(this.selectedId);
          return;
        }
        if (k === "Tab") { e.preventDefault(); this.addChild(this.selectedId); }
        else if (k === "Enter") { e.preventDefault(); this.editNode(this.selectedId); }
        else if (k === "Delete" || k === "Backspace") { e.preventDefault(); this.deleteNode(this.selectedId); }
        else if (k === "ArrowUp") { e.preventDefault(); this.navigateRelative("up"); }
        else if (k === "ArrowDown") { e.preventDefault(); this.navigateRelative("down"); }
        else if (k === "ArrowLeft") { e.preventDefault(); this.navigateRelative("left"); }
        else if (k === "ArrowRight") { e.preventDefault(); this.navigateRelative("right"); }
        else if (k === "+" || k === "=") { this.zoom(1.25); }
        else if (k === "-" || k === "_") { this.zoom(0.8); }
        else if (k === "0") { this.fit(); }
        else if (k === "f" || k === "F") { e.preventDefault(); els.search.focus(); }
      });
      // dialog 关闭事件：清浮层
      els.dialog.addEventListener("close", () => {
        this._linkFrom = null;
        if (this.els.floatEdit) this.els.floatEdit.hidden = true;
        if (this.els.nodePanel) this.els.nodePanel.hidden = true;
        if (this.els.floatBar) this.els.floatBar.hidden = true;
      });
    }
  }

  // 打开思维导图（从孵化结果）
  function openMindmapFromResult() {
    if (!hatchState.result) { toast("请先完成一次孵化", "info"); return; }
    if (!mmEditor) mmEditor = new MindMapEditor();
    mmEditor.openFromResult();
  }
  // ============================================================
  // 🤖 自动上板：AI 对话拆解 / 孵化结果 → 思维导图（无需手动点按钮）
  // 同一来源始终更新同一张导图（按目标文本哈希定 id），不重复堆积。
  // 节点 id 独立生成，不复用 mmEditor.seq，避免与已打开导图冲突。
  // ============================================================
  let _autoSeq = Date.now() % 1000000;
  function autoNode(text, meta, type) {
    return { id: "au" + (++_autoSeq), text: String(text || ""), meta: meta || {}, type: type || "main", collapsed: false, children: [] };
  }
  // 拆解上下文 → 导图记录（存库）
  function syncMindmapFromBreakdown(ctx) {
    if (!ctx || !Array.isArray(ctx.nodes) || !ctx.nodes.length) return null;
    try {
      const root = autoNode(ctx.goal || "项目拆解", { source: "ai-breakdown" }, "main");
      root._isRoot = true;
      ctx.nodes.forEach((m, i) => {
        const n = autoNode(m.title || m.name || ("模块 " + (i + 1)), { status: m.status || "pending" }, "main");
        (m.children || []).forEach((c) => {
          const cn = autoNode(c.title || c.name || "", { status: c.status || "pending" }, "child");
          n.children.push(cn);
        });
        root.children.push(n);
      });
      const mmId = ctx._mmId || ("aibk-" + hashTaskText(ctx.goal || "项目拆解"));
      const rec = { id: mmId, taskText: ctx.goal || "项目拆解", root, layout: "lr", updatedAt: Date.now(), source: "ai-breakdown" };
      const saved = load(MINDMAP_KEY, []);
      const idx = saved.findIndex((x) => x.id === mmId);
      if (idx >= 0) saved[idx] = rec; else saved.push(rec);
      save(MINDMAP_KEY, saved.slice(-100));
      ctx._mmId = mmId;
      return rec;
    } catch (e) { console.warn("[自动上板] 拆解同步失败", e); return null; }
  }
  // 孵化结果 → 导图记录（存库）
  function syncMindmapFromHatch() {
    if (!hatchState.result || !hatchState.result.steps || !hatchState.result.steps.length) return null;
    try {
      if (!mmEditor) mmEditor = new MindMapEditor();
      const root = mmEditor.stepsToTree({ steps: hatchState.result.steps, est_total_min: hatchState.result.est_total_min, taskText: hatchState.taskText });
      if (!root || !root.children || !root.children.length) return null;
      root._isRoot = true;
      const mmId = "aibt-" + (hatchState.taskHash || hashTaskText(hatchState.taskText || "孵化任务"));
      const rec = { id: mmId, taskText: hatchState.taskText || "孵化任务", root, layout: "lr", updatedAt: Date.now(), source: "hatch" };
      const saved = load(MINDMAP_KEY, []);
      const idx = saved.findIndex((x) => x.id === mmId);
      if (idx >= 0) saved[idx] = rec; else saved.push(rec);
      save(MINDMAP_KEY, saved.slice(-100));
      return rec;
    } catch (e) { console.warn("[自动上板] 孵化同步失败", e); return null; }
  }
  // 打开思维导图（从历史记录）
  function openMindmapFromHistory(rec) {
    if (!rec) return;
    if (!mmEditor) mmEditor = new MindMapEditor();
    mmEditor.openFromHistory(rec);
  }

  // 独立入口：打开思维导图编辑器（最近导图 → 最近孵化历史 → 空白新建）
  function openMindmapStandalone() {
    if (!mmEditor) mmEditor = new MindMapEditor();
    // 1) 独立导图库最近一张
    const saved = load(MINDMAP_KEY, []);
    if (saved.length) {
      const last = saved[saved.length - 1];
      mmEditor.openSavedMindmap(last);
      toast(`已打开最近导图「${trunc(last.taskText || "未命名", 24)}」（共 ${saved.length} 张，可在编辑器内切换）`, "info");
      return;
    }
    // 2) 最近一条孵化历史（含步骤）
    const hist = loadHatchHistory();
    if (hist.length) {
      mmEditor.openFromHistory(hist[hist.length - 1]);
      toast("已从最近孵化记录生成思维导图（可编辑后保存）", "info");
      return;
    }
    // 3) 空白新建
    mmEditor.openBlank();
    toast("已新建空白思维导图 · 双击根节点命名，选中后 Tab 添加节点", "info");
  }

  // ============================================================
  // 🔗 关系图谱（Obsidian 风格）：全局任务/节点关系网络
  // ============================================================
  const graphState = { nodes: [], edges: [], drag: null };

  // 收集全局节点：收集箱任务 + 孵化历史 + 导图
  function collectGraphNodes() {
    const nodes = [];
    const seen = new Set();
    const push = (n) => { if (n && n.label && !seen.has(n.id)) { seen.add(n.id); nodes.push(n); } };
    // 收集箱任务
    inboxItems.forEach((it) => {
      const label = (it.text || "").replace(/\s*#\w+(→\d+)?#\s*$/, "").trim();
      push({ id: "inb_" + (it.id || Math.random().toString(36).slice(2)), label, type: "inbox", tags: it.tags || [], done: it.done, ref: it });
    });
    // 孵化历史
    (loadHatchHistory() || []).forEach((h) => {
      push({ id: "hatch_" + (h.task_hash || Math.random().toString(36).slice(2)), label: h.task_text, type: "hatch", tags: [h.tag].filter(Boolean), ref: h });
    });
    // 导图（任务级）
    (load(MINDMAP_KEY, []) || []).forEach((m) => {
      push({ id: "mm_" + (m.id || Math.random().toString(36).slice(2)), label: m.taskText || m.root.text, type: "mindmap", tags: [], ref: m, mmRoot: m.root });
    });
    return nodes;
  }

  // 建边：相同 tag / 文本相似 / 导图关联线
  function buildGraphEdges(nodes) {
    const edges = [];
    const seen = new Set();
    const add = (a, b, type) => {
      if (!a || !b || a === b) return;
      const key = [a, b].sort().join("|");
      if (seen.has(key)) return;
      seen.add(key);
      edges.push({ a, b, type });
    };
    // 相同 tag
    const byTag = new Map();
    nodes.forEach((n) => (n.tags || []).forEach((t) => { if (t) { if (!byTag.has(t)) byTag.set(t, []); byTag.get(t).push(n.id); } }));
    byTag.forEach((list) => { for (let i = 0; i < list.length; i++) for (let j = i + 1; j < list.length; j++) add(list[i], list[j], "tag"); });
    // 文本相似（中文 2-gram + 英文词 token 重叠）
    const grams = (s) => { const t = String(s || "").toLowerCase(); const g = new Set(); for (let i = 0; i < t.length - 1; i++) g.add(t.slice(i, i + 2)); return g; };
    for (let i = 0; i < nodes.length; i++) {
      const gi = grams(nodes[i].label);
      for (let j = i + 1; j < nodes.length; j++) {
        const gj = grams(nodes[j].label);
        let inter = 0; gi.forEach((x) => { if (gj.has(x)) inter++; });
        const denom = Math.min(gi.size, gj.size) || 1;
        if (inter / denom > 0.35) add(nodes[i].id, nodes[j].id, "similar");
      }
    }
    // 导图内 meta.link 关联（节点级 → 任务级连线）
    nodes.forEach((n) => {
      if (n.type !== "mindmap" || !n.mmRoot) return;
      const links = new Set();
      const walk = (x) => { if (x.meta && x.meta.link) links.add(x.meta.link); (x.children || []).forEach(walk); };
      walk(n.mmRoot);
      links.forEach((targetId) => {
        // 目标节点在同导图内，映射到任务级连线（同导图内不画，跨导图才画）
        const t = nodes.find((m) => m.id === targetId);
        if (t && t.id !== n.id) add(n.id, t.id, "link");
      });
    });
    return edges;
  }

  // 打开关系图谱
  function openGraph() {
    const dlg = document.getElementById("graphDialog");
    if (!dlg) return;
    graphState.nodes = collectGraphNodes();
    graphState.edges = buildGraphEdges(graphState.nodes);
    renderGraph();
    dlg.showModal();
  }

  // 环形布局 + 渲染
  function renderGraph() {
    const nodes = graphState.nodes, edges = graphState.edges;
    const svg = document.getElementById("graphSvg");
    const gEdges = document.getElementById("graphEdges");
    const gNodes = document.getElementById("graphNodes");
    const empty = document.getElementById("graphEmpty");
    const legend = document.getElementById("graphLegend");
    if (!svg || !gEdges || !gNodes) return;
    const W = 1000, H = 700, cx = W / 2, cy = H / 2;
    svg.setAttribute("viewBox", `0 0 ${W} ${H}`);
    svg.setAttribute("width", "100%"); svg.setAttribute("height", "100%");
    // 空态
    if (!nodes.length) { empty.hidden = false; gEdges.innerHTML = ""; gNodes.innerHTML = ""; legend.innerHTML = ""; return; }
    empty.hidden = true;
    // 节点环形定位（按类型分组）
    const groups = { inbox: [], hatch: [], mindmap: [] };
    nodes.forEach((n) => { (groups[n.type] || (groups[n.type] = [])).push(n); });
    const ordered = [...groups.inbox, ...groups.hatch, ...groups.mindmap];
    const R = Math.min(W, H) / 2 - 90;
    const colors = { inbox: "#7c5cff", hatch: "#ffa94d", mindmap: "#4dc3ff" };
    graphState.pos = {};
    ordered.forEach((n, i) => {
      const angle = (i / Math.max(1, ordered.length)) * Math.PI * 2 - Math.PI / 2;
      graphState.pos[n.id] = { x: cx + Math.cos(angle) * R, y: cy + Math.sin(angle) * R, color: colors[n.type] || "#999" };
    });
    // 边
    gEdges.innerHTML = edges.map((e) => {
      const pa = graphState.pos[e.a], pb = graphState.pos[e.b];
      if (!pa || !pb) return "";
      const typeColor = { tag: "rgba(124,92,255,.5)", similar: "rgba(160,160,200,.35)", link: "#ffa94d" };
      return `<line x1="${pa.x}" y1="${pa.y}" x2="${pb.x}" y2="${pb.y}" stroke="${typeColor[e.type] || "#999"}" stroke-width="${e.type === "link" ? 2 : 1.2}" stroke-dasharray="${e.type === "link" ? "5 4" : ""}" opacity="0.7" data-a="${e.a}" data-b="${e.b}" data-type="${e.type}" class="graph-edge" />`;
    }).join("");
    // 节点
    gNodes.innerHTML = nodes.map((n) => {
      const p = graphState.pos[n.id];
      const label = trunc(n.label, 12);
      return `<g class="graph-node" data-id="${n.id}" transform="translate(${p.x},${p.y})" cursor="grab">
        <circle r="${n.type === "mindmap" ? 16 : 13}" fill="${p.color}" fill-opacity="0.85" stroke="#fff" stroke-width="1.5" />
        <text y="-20" text-anchor="middle" fill="#e8e8f0" font-size="11">${escapeHtml(label)}</text>
        ${n.done ? '<text y="4" text-anchor="middle" font-size="9" fill="#4ade80">✓</text>' : ""}
      </g>`;
    }).join("");
    // 图例
    legend.innerHTML = `<span class="graph-leg-item"><span class="dot" style="background:#7c5cff"></span>收集箱</span>
      <span class="graph-leg-item"><span class="dot" style="background:#ffa94d"></span>孵化</span>
      <span class="graph-leg-item"><span class="dot" style="background:#4dc3ff"></span>导图</span>
      <span class="graph-leg-item"><span class="line" style="background:rgba(124,92,255,.5)"></span>同标签</span>
      <span class="graph-leg-item"><span class="line dash" style="background:#ffa94d"></span>导图关联</span>`;
    bindGraphInteractions();
  }

  function bindGraphInteractions() {
    const svg = document.getElementById("graphSvg");
    if (!svg || svg.dataset.bound) return;
    svg.dataset.bound = "1";
    // 拖拽节点
    svg.addEventListener("mousedown", (e) => {
      const g = e.target.closest ? e.target.closest(".graph-node") : null;
      if (!g) return;
      const id = g.dataset.id;
      graphState.drag = { id, dx: e.clientX, dy: e.clientY, moved: false };
      e.preventDefault();
    });
    window.addEventListener("mousemove", (e) => {
      if (!graphState.drag) return;
      const d = graphState.drag;
      const p = graphState.pos[d.id];
      if (!p) return;
      // 屏幕坐标 → viewBox 坐标（近似）
      const rect = svg.getBoundingClientRect();
      const scale = 1000 / rect.width;
      p.x += (e.clientX - d.dx) * scale * 2;
      p.y += (e.clientY - d.dy) * scale * 2;
      d.dx = e.clientX; d.dy = e.clientY; d.moved = true;
      renderGraph();
    });
    window.addEventListener("mouseup", () => { graphState.drag = null; });
    // 点击节点跳转 / 点击边删除
    svg.addEventListener("click", (e) => {
      const nodeEl = e.target.closest ? e.target.closest(".graph-node") : null;
      if (nodeEl) {
        const n = graphState.nodes.find((x) => x.id === nodeEl.dataset.id);
        if (!n) return;
        if (n.type === "inbox") { el.inboxDialog && el.inboxDialog.showModal(); renderInboxList(); toast(`已定位收集箱任务「${trunc(n.label, 16)}」`, "info"); }
        else if (n.type === "hatch") { openHatchHistoryDialog && openHatchHistoryDialog(); toast(`已打开孵化历史（${trunc(n.label, 16)}）`, "info"); }
        else if (n.type === "mindmap") { if (!mmEditor) mmEditor = new MindMapEditor(); mmEditor.openSavedMindmap(n.ref); document.getElementById("graphDialog").close(); }
        return;
      }
      const edgeEl = e.target.closest ? e.target.closest(".graph-edge") : null;
      if (edgeEl && edgeEl.dataset.type === "link") {
        if (confirm("删除这条导图关联线？")) {
          const mm = graphState.nodes.find((n) => n.type === "mindmap" && n.mmRoot);
          if (mm && mm.mmRoot) {
            const remove = (x) => { if (x.meta && x.meta.link) { if (x.id === edgeEl.dataset.a || x.id === edgeEl.dataset.b) delete x.meta.link; } (x.children || []).forEach(remove); };
            remove(mm.mmRoot);
            // 保存
            const list = load(MINDMAP_KEY, []);
            const t = list.find((r) => r.id === mm.ref.id);
            if (t) { t.root = mm.mmRoot; save(MINDMAP_KEY, list); }
            openGraph(); // 重渲染
            toast("已删除关联线", "info");
          }
        }
      }
    });
  }

  // AI 规划助手：聚焦到主页 AI 对话区
  function focusAiAssistant() {
    const sec = document.querySelector(".chat-section");
    if (sec) { sec.scrollIntoView({ behavior: "smooth", block: "start" }); }
    if (el.chatInput) setTimeout(() => el.chatInput.focus(), 400);
    toast("🤖 AI 规划助手：描述任务，我会帮你拆解并安排", "info");
  }

  // 剪贴板复制工具（带 toast 反馈）
  function copyText(text) {
    const done = () => toast("已复制到剪贴板", "success");
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(done).catch(() => fallbackCopy(text, done));
    } else fallbackCopy(text, done);
  }
  function fallbackCopy(text, done) {
    try {
      const ta = document.createElement("textarea");
      ta.value = text;
      ta.style.cssText = "position:fixed;opacity:0;";
      document.body.appendChild(ta);
      ta.select();
      document.execCommand("copy");
      document.body.removeChild(ta);
      done && done();
    } catch (e) { toast("复制失败", "error"); }
  }

  el.hatchBtn.addEventListener("click", openHatchDialog);
  if (el.hatchToolBtn) el.hatchToolBtn.addEventListener("click", () => openHatchDialog({}));
  if (el.realmFabHatch) el.realmFabHatch.addEventListener("click", () => openHatchDialog({}));
  // 基本孵化独立入口：一键切到 basic 模式（7 维度×子维度穷尽拆解）
  const startBasicHatch = () => {
    if (hatchState.running) { toast("AI 处理中，稍候…", "info"); return; }
    const text = (el.hatchTaskInput ? el.hatchTaskInput.value : "").trim() || hatchState.taskText || "";
    if (!text) {
      // 无任务：打开弹窗并预设 basic，等用户填任务
      openHatchDialog({});
      if (el.hatchMode) el.hatchMode.value = "basic";
      if (el.hatchTaskInput) el.hatchTaskInput.focus();
      toast("填入任务后点「开始孵化」（已切到基本孵化模式）", "info");
      return;
    }
    if (!el.hatchDialog || !el.hatchDialog.open) openHatchDialog({ text });
    if (el.hatchMode) el.hatchMode.value = "basic";
    startHatchFromForm();
  };
  if (el.realmFabBasic) el.realmFabBasic.addEventListener("click", startBasicHatch);
  if (el.realmFabMindmap) el.realmFabMindmap.addEventListener("click", openMindmapStandalone);
  if (el.realmFabGraph) el.realmFabGraph.addEventListener("click", openGraph);
  if (el.realmFabAI) el.realmFabAI.addEventListener("click", focusAiAssistant);
  const graphClose = document.getElementById("graphClose");
  if (graphClose) graphClose.addEventListener("click", () => document.getElementById("graphDialog") && document.getElementById("graphDialog").close());
  if (el.hatchBasicBtn) el.hatchBasicBtn.addEventListener("click", startBasicHatch);
  if (el.hatchGenBtn) el.hatchGenBtn.addEventListener("click", generateOnboardQuestions);
  if (el.hatchStartBtn) el.hatchStartBtn.addEventListener("click", startHatchFromForm);
  // 重新问询：清空当前问题，回到生成初始态（保留任务描述）
  if (el.hatchRegenBtn) el.hatchRegenBtn.addEventListener("click", () => {
    if (el.hatchOnboardQs) el.hatchOnboardQs.innerHTML = "";
    if (el.hatchOnboardGen) el.hatchOnboardGen.hidden = false;
    if (el.hatchOnboardActions) el.hatchOnboardActions.hidden = false; // 开始孵化保持可用（可跳过问询）
    if (el.hatchRegenBtn) el.hatchRegenBtn.hidden = true; // 问题已清空，隐藏本按钮
    if (el.hatchGenBtn) el.hatchGenBtn.disabled = false;
    if (el.hatchGenTip) el.hatchGenTip.textContent = "填好任务后点此，AI 会针对你的任务提 5-7 个关键问题（含 7 维度子维度）";
    if (el.hatchOnboardTip) el.hatchOnboardTip.textContent = "💡 答得越具体，AI 拆解越精准";
    hatchState.onboardQuestions = [];
    toast("已清空问题，可重新生成或直接开始孵化", "info");
  });
  if (el.hatchTaskInput) el.hatchTaskInput.addEventListener("keydown", (e) => {
    if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); startHatchFromForm(); }
  });
  if (el.hatchOnboardToggle) el.hatchOnboardToggle.addEventListener("click", () => {
    if (el.hatchOnboard) el.hatchOnboard.classList.toggle("collapsed");
  });
  if (el.hatchOnboard) {
    const head = el.hatchOnboard.querySelector(".hatch-onboard-head");
    if (head) head.addEventListener("click", (e) => {
      // 点击头部空白处也能折叠（避开按钮内部交互）
      if (e.target.closest("input,button,select")) return;
      el.hatchOnboard.classList.toggle("collapsed");
    });
  }
  el.closeHatch.addEventListener("click", closeHatchDialog);
  el.hatchCancelBtn.addEventListener("click", closeHatchDialog);
  el.hatchDialog.addEventListener("click", (e) => { if (e.target === el.hatchDialog) closeHatchDialog(); });

  // 流式中取消（仅中止请求，不关闭弹窗）
  if (el.hatchCancelStream) el.hatchCancelStream.addEventListener("click", () => {
    if (hatchState.abortController) {
      try { hatchState.abortController.abort(); } catch (e) {}
    }
  });
  // 复制原始 AI 输出
  if (el.hatchStreamCopy) el.hatchStreamCopy.addEventListener("click", () => {
    const text = el.hatchStreamBody ? el.hatchStreamBody.textContent : "";
    if (!text) return;
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(() => toast("已复制 AI 原始输出", "success"));
    } else {
      const ta = document.createElement("textarea");
      ta.value = text; document.body.appendChild(ta); ta.select();
      try { document.execCommand("copy"); toast("已复制 AI 原始输出", "success"); }
      catch (e) { toast("复制失败，请手动选择", "error"); }
      document.body.removeChild(ta);
    }
  });
  // 错误区：重试 / 降档重试
  const HATCH_MODE_ORDER = ["lite", "medium", "zen", "basic"];
  function rerunHatch(modeOverride) {
    if (!hatchState.taskText) return;
    const scene = el.hatchScene.value === "auto" ? detectHatchScene(hatchState.taskText) : el.hatchScene.value;
    const mode = modeOverride || (el.hatchMode.value === "auto" ? autoHatchMode(hatchState.taskText) : el.hatchMode.value);
    const forceLLM = scene === "drill";
    runHatch(hatchState.taskText + (forceLLM ? "（重试）" : " "), mode, scene, buildHatchContext(), hatchState.longTaskId, forceLLM);
  }
  if (el.hatchRetryBtn) el.hatchRetryBtn.addEventListener("click", () => rerunHatch());
  if (el.hatchDowngradeBtn) el.hatchDowngradeBtn.addEventListener("click", () => {
    const cur = el.hatchMode.value === "auto" ? autoHatchMode(hatchState.taskText) : el.hatchMode.value;
    const idx = HATCH_MODE_ORDER.indexOf(cur);
    const down = idx > 0 ? HATCH_MODE_ORDER[idx - 1] : "lite";
    el.hatchMode.value = down;
    toast(`已降档至 ${down}，重试中…`, "info");
    rerunHatch(down);
  });
  // 失败后一键本地拆解（离线降级，不调用 AI）
  if (el.hatchLocalBtn) el.hatchLocalBtn.addEventListener("click", () => {
    if (!hatchState.taskText) return;
    const scene = el.hatchScene.value === "auto" ? detectHatchScene(hatchState.taskText) : el.hatchScene.value;
    const mode = el.hatchMode.value === "auto" ? autoHatchMode(hatchState.taskText) : el.hatchMode.value;
    const local = localHatchFallback(hatchState.taskText, mode, scene);
    local.mode = mode;
    local.scene = scene;
    local.longTaskId = hatchState.longTaskId || null;
    renderHatchResult(local);
    toast("已用本地启发式拆解（离线模式）", "info");
  });
  // 💾 保存为习惯：把当前孵化结果存为一个可打卡的习惯（四大定律计划自动带入）
  if (el.hatchSaveHabit) el.hatchSaveHabit.addEventListener("click", () => {
    const result = hatchState.result;
    if (!result || !result.steps || !result.steps.length) { toast("没有可保存的步骤", "warn"); return; }
    const isBreak = (result.habitType === "break") || /戒|戒掉|停|杜绝|不再|忍住|改掉/.test(hatchState.taskText || "");
    let base = (hatchState.taskText || "").replace(/^(我要|我想|每天|坚持|养成|培养|戒掉|戒除|改掉|不再|停止|学会|开始)/, "").trim() || "我的习惯";
    // 清理「习惯「xxx」」这类包裹，取内层名称；并去掉尾缀「的习惯/坏习惯」
    const m = base.match(/习惯「(.+?)」|「(.+?)」/);
    if (m) base = (m[1] || m[2]).trim();
    base = base.replace(/的坏习惯$/, "").replace(/的习惯$/, "").trim();
    base = base.slice(0, 30) || "我的习惯";
    const h = addHabit(base, isBreak ? "break" : "build", "每天", "");
    if (!h) return;
    // 四大定律计划：从步骤的 law 字段提取
    const lawPlans = new Map();
    result.steps.forEach((s) => {
      if (s.law && !lawPlans.has(s.law)) lawPlans.set(s.law, s.text);
    });
    h.laws = Array.from(lawPlans.entries()).map(([law, plan]) => ({ law, plan }));
    h.plan = result.steps.map((s) => ({ text: s.text, verify: s.verify || "", law: s.law || "", est_min: s.est_min || 0 }));
    // 进阶设计：从步骤文本提取身份/环境/两分钟线索（尽力而为）
    const all = result.steps.map((s) => s.text).join(" ");
    const idm = all.match(/我是「(.+?)」的人/);
    if (idm) h.identity = `我是${idm[1]}的人`;
    else {
      const idm2 = all.match(/成为(.+?)的人|我想成为(.+?)的人/);
      if (idm2) h.identity = ((idm2[1] || idm2[2]) || "").replace(/^的人[：:]?/, "").trim();
    }
    if (h.identity) h.identity = h.identity.replace(/的习惯的人$/, "的人").slice(0, 40);
    const tmm = all.match(/只(.+?)，先动起来/) || all.match(/两分钟版[：:]\s*([^，。；]{2,20})/) || all.match(/（如：(.+?)[）)]/);
    if (tmm) h.twoMin = (tmm[1] || "").slice(0, 30);
    saveHabits();
    toast(`💾 已保存为习惯「${h.name}」（${isBreak ? "纠正" : "培养"} · ${lawPlans.size}/4 定律计划）`, "success");
    openHabitDetail(h.id);
  });

  el.hatchSelectAll.addEventListener("click", () => {
    if (!hatchState.result) return;
    hatchState.acceptedSet = new Set((hatchState.result.steps || []).map((_, i) => i));
    el.hatchList.querySelectorAll("input[type=checkbox]").forEach((cb) => { cb.checked = true; });
  });
  el.hatchInvert.addEventListener("click", () => {
    if (!hatchState.result) return;
    const newSet = new Set();
    el.hatchList.querySelectorAll("input[type=checkbox]").forEach((cb, i) => {
      cb.checked = !cb.checked;
      if (cb.checked) newSet.add(i);
    });
    hatchState.acceptedSet = newSet;
  });
  el.hatchRegen.addEventListener("click", () => {
    // 重新生成：温度通过加随机后缀变相提升（避免完全相同结果）
    if (!hatchState.taskText) return;
    const mode = el.hatchMode.value === "auto" ? autoHatchMode(hatchState.taskText) : el.hatchMode.value;
    const scene = el.hatchScene.value === "auto" ? detectHatchScene(hatchState.taskText) : el.hatchScene.value;
    // 降档重试逻辑：如果上次失败过，这里不变档；正常重新生成保持同档
    // drill 场景强制走 LLM（绕过模板库），便于个性化
    const forceLLM = scene === "drill";
    runHatch(hatchState.taskText + (forceLLM ? "（个性化）" : " "), mode, scene, buildHatchContext(), hatchState.longTaskId, forceLLM);
  });
  el.hatchApply.addEventListener("click", applyHatchToChecklist);
  if (el.hatchToGrid) el.hatchToGrid.addEventListener("click", applyHatchToGrid);
  if (el.hatchToInbox) el.hatchToInbox.addEventListener("click", applyHatchToInbox);
  if (el.hatchHistoryBtn) el.hatchHistoryBtn.addEventListener("click", () => {
    // 已展开则收起，未展开则展开（toggle）
    if (el.hatchHistoryPanel && !el.hatchHistoryPanel.hidden) closeHatchHistoryDialog();
    else openHatchHistoryDialog();
  });
  if (el.hatchMindmap) el.hatchMindmap.addEventListener("click", openMindmapFromResult);
  if (el.closeHatchHistory) el.closeHatchHistory.addEventListener("click", closeHatchHistoryDialog);
  // 结果页连续对话
  if (el.hatchChatSend) el.hatchChatSend.addEventListener("click", sendHatchFollowup);
  if (el.hatchChatInput) {
    el.hatchChatInput.addEventListener("keydown", (e) => {
      if (e.key === "Enter" && !e.shiftKey) {
        e.preventDefault();
        sendHatchFollowup();
      }
    });
  }
  // 快速调整 chips：点击即填入输入框并发送
  if (el.hatchChatChips) {
    el.hatchChatChips.addEventListener("click", (e) => {
      const chip = e.target.closest(".hatch-chip");
      if (!chip || !chip.dataset.chip) return;
      if (hatchState.running) { toast("AI 处理中，稍候…", "info"); return; }
      if (el.hatchChatInput) el.hatchChatInput.value = chip.dataset.chip;
      sendHatchFollowup();
    });
  }
  if (el.hatchChatCopy) el.hatchChatCopy.addEventListener("click", copyHatchChat);
  if (el.hatchChatClear) el.hatchChatClear.addEventListener("click", clearHatchChat);
  if (el.closeMermaidLightbox) el.closeMermaidLightbox.addEventListener("click", closeMermaidLightbox);
  if (el.mlbDownloadBtn) el.mlbDownloadBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    downloadMermaidPng();
  });
  if (el.mermaidLightbox) el.mermaidLightbox.addEventListener("click", (e) => {
    if (e.target === el.mermaidLightbox) closeMermaidLightbox();
  });
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && el.mermaidLightbox && el.mermaidLightbox.open) closeMermaidLightbox();
  });

  // 模式/场景手动切换后自动重跑
  el.hatchMode.addEventListener("change", () => {
    if (!hatchState.taskText || hatchState.running) return;
    const mode = el.hatchMode.value === "auto" ? autoHatchMode(hatchState.taskText) : el.hatchMode.value;
    const scene = el.hatchScene.value === "auto" ? detectHatchScene(hatchState.taskText) : el.hatchScene.value;
    runHatch(hatchState.taskText, mode, scene, buildHatchContext());
  });
  el.hatchScene.addEventListener("change", () => {
    if (!hatchState.taskText || hatchState.running) return;
    const scene = el.hatchScene.value === "auto" ? detectHatchScene(hatchState.taskText) : el.hatchScene.value;
    if (scene === "drill" && !hatchState.longTaskId) {
      toast("🎯 薄弱补强需从长期任务详情页进入（需读取 7 维度评分）", "info", 4000);
      el.hatchScene.value = "auto";
      return;
    }
    const mode = el.hatchMode.value === "auto" ? autoHatchMode(hatchState.taskText) : el.hatchMode.value;
    runHatch(hatchState.taskText, mode, scene, buildHatchContext(), hatchState.longTaskId);
  });

  // ---------- 子任务清单弹出层 ----------
  let activePopover = null;
  function openChecklistPopover(period, cell, anchorEl) {
    closeChecklistPopover();
    const items = getCellChecklist(period, cell);
    if (!items.length) return;
    const pop = document.createElement("div");
    pop.className = "checklist-popover";
    pop.innerHTML = `<div class="checklist-popover-title">子任务清单</div>`;
    items.forEach((it, idx) => {
      const row = document.createElement("label");
      row.className = "checklist-row" + (it.done ? " done" : "");
      let dimBadge = "";
      if (it.dim) {
        const [dc, sk] = it.dim.split(".");
        const meta = lookupDim(dc, sk);
        if (meta) {
          const goalTxt = it.dimGoal ? `→${it.dimGoal}` : "";
          dimBadge = `<span class="hatch-tag hatch-tag-dim" style="background:${meta.dimColor}22;color:${meta.dimColor};font-size:10px;" title="${meta.dimName}·${meta.subName}：${meta.question}">${it.dim}${goalTxt}</span>`;
        }
      }
      row.innerHTML = `<input type="checkbox" ${it.done ? "checked" : ""}><span>${escapeHtml(it.text)}</span>${dimBadge}`;
      row.querySelector("input").addEventListener("change", () => {
        toggleChecklistItem(period, cell, idx);
        row.classList.toggle("done");
        renderMandala();
        renderOverview();
      });
      pop.appendChild(row);
    });
    const editBtn = document.createElement("button");
    editBtn.className = "checklist-edit-btn";
    editBtn.textContent = "✏ 编辑清单";
    editBtn.addEventListener("click", () => {
      closeChecklistPopover();
      openTaskDialog(period, cell);
    });
    pop.appendChild(editBtn);
    document.body.appendChild(pop);
    // 定位到锚点附近
    if (anchorEl) {
      const r = anchorEl.getBoundingClientRect();
      pop.style.position = "fixed";
      let top = r.bottom + 4;
      let left = r.left;
      // 防止溢出右侧
      const popW = Math.max(160, pop.offsetWidth);
      if (left + popW > window.innerWidth - 8) left = window.innerWidth - popW - 8;
      if (left < 8) left = 8;
      if (top + pop.offsetHeight > window.innerHeight - 8) top = Math.max(8, r.top - pop.offsetHeight - 4);
      pop.style.top = top + "px";
      pop.style.left = left + "px";
    }
    activePopover = pop;
    // 点击外部关闭
    setTimeout(() => {
      document.addEventListener("click", closeChecklistPopoverOnOutside, true);
    }, 0);
  }
  function closeChecklistPopoverOnOutside(e) {
    if (activePopover && !activePopover.contains(e.target) && !e.target.classList.contains("cell-checklist-badge")) {
      closeChecklistPopover();
    }
  }
  function closeChecklistPopover() {
    if (activePopover) { activePopover.remove(); activePopover = null; }
    document.removeEventListener("click", closeChecklistPopoverOnOutside, true);
  }

  // ---------- 时辰导航 ----------
  el.prevPeriod.addEventListener("click", () => {
    state.activePeriod = (state.activePeriod - 1 + PERIOD_COUNT) % PERIOD_COUNT; renderAll();
  });
  el.nextPeriod.addEventListener("click", () => {
    state.activePeriod = (state.activePeriod + 1) % PERIOD_COUNT; renderAll();
  });
  // 记录页时辰导航（与计划页同步）
  if (el.prevPeriodR) el.prevPeriodR.addEventListener("click", () => {
    state.activePeriod = (state.activePeriod - 1 + PERIOD_COUNT) % PERIOD_COUNT; renderAll();
  });
  if (el.nextPeriodR) el.nextPeriodR.addEventListener("click", () => {
    state.activePeriod = (state.activePeriod + 1) % PERIOD_COUNT; renderAll();
  });

  // ---------- 天地人三才切换 ----------
  if (el.realmSwitcher) {
    el.realmSwitcher.dataset.active = "plan";
    el.realmSwitcher.querySelectorAll(".realm-tab").forEach((tab) => {
      tab.addEventListener("click", () => {
        const target = tab.dataset.realm;
        const order = ["plan", "record", "review"];
        const reverse = order.indexOf(target) < order.indexOf(state.realm);
        setRealm(target, reverse);
      });
    });
    // 上下滑切换三才（在切换器条上）
    let sX = 0, sY = 0, sT = 0, tracking = false;
    el.realmSwitcher.addEventListener("touchstart", (e) => {
      if (e.touches.length !== 1) return;
      sX = e.touches[0].clientX; sY = e.touches[0].clientY; sT = Date.now();
      tracking = true;
    }, { passive: true });
    el.realmSwitcher.addEventListener("touchend", (e) => {
      if (!tracking) return;
      tracking = false;
      const dy = e.changedTouches[0].clientY - sY;
      const dx = e.changedTouches[0].clientX - sX;
      const dt = Date.now() - sT;
      if (Math.abs(dy) > 40 && Math.abs(dy) > Math.abs(dx) && dt < 500) {
        const order = ["plan", "record", "review"];
        const idx = order.indexOf(state.realm);
        const next = dy < 0 ? Math.min(idx + 1, 2) : Math.max(idx - 1, 0);
        if (next !== idx) setRealm(order[next], next < idx);
      }
    }, { passive: true });
  }
  // 复盘按钮
  if (el.aiReviewBtn) el.aiReviewBtn.addEventListener("click", generateAiReview);
  if (el.clearReviewBtn) el.clearReviewBtn.addEventListener("click", () => {
    if (!confirm("清空今日复盘内容？")) return;
    clearDayReview(state.currentDate);
    renderReview();
    toast("复盘已清空", "info");
  });
  // 导出复盘
  if (el.exportReviewBtn) el.exportReviewBtn.addEventListener("click", () => {
    const review = getDayReview(state.currentDate);
    const stats = computeReviewStats();
    const date = state.currentDate;
    const dayTasks = state.tasks[date] || {};
    const dayRecords = state.records[date] || {};
    const planLines = [], recordLines = [];
    for (let p = 0; p < PERIOD_COUNT; p++) {
      for (let c = 0; c < CELLS_PER_PERIOD; c++) {
        const key = p + "-" + c;
        const range = getCellRange(p, c);
        const time = `${secondsToHHMM(range.start)}-${secondsToHHMM(range.end)}`;
        const tasks = (dayTasks[key] || []).map((t) => taskText(t));
        const rec = dayRecords[key];
        if (tasks.length) planLines.push(`  [${time}] ${tasks.join("; ")}`);
        if (rec && (rec.actual || rec.spent)) {
          recordLines.push(`  [${time}] 花费:${rec.spent || "-"} 实际:${rec.actual || "-"}${rec.note ? " 备注:" + rec.note : ""}`);
        }
      }
    }
    const md = `# 曼陀罗时辰 · 复盘 ${date}

## 📊 统计
- 计划格数: ${stats.plannedCells}
- 已记录: ${stats.recordedCells}
- 已完成: ${stats.doneCount} (完成率 ${stats.completionRate}%)
- 吻合率: ${stats.matchRate}%
- 总花费时间: ${stats.totalSpentText}

## 📖 计划
${planLines.join("\n") || "  （无）"}

## 📝 记录
${recordLines.join("\n") || "  （无）"}

## 💡 AI 复盘
${review ? (review.summary || "") : "（未生成）"}

${review && review.insights ? "### 洞察\n" + review.insights.map((i) => `- ${i}`).join("\n") : ""}

${review && review.suggestions ? "### 建议\n" + review.suggestions.map((i) => `- ${i}`).join("\n") : ""}

${review && review.highlights ? "### 亮点\n" + review.highlights.map((i) => `- ${i}`).join("\n") : ""}

## ✍️ 我的反思
${review && review.userNotes ? review.userNotes : "（无）"}
`;
    const blob = new Blob([md], { type: "text/markdown;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `mandala-review-${date}.md`;
    a.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    toast("复盘已导出为 Markdown", "success");
  });
  // 记录页工具栏
  if (el.syncPlanBtn) el.syncPlanBtn.addEventListener("click", () => {
    const period = state.activePeriod;
    // 预计算将同步的格子（计划存在 + 无实际记录）
    const pending = [];
    const skippedDone = [];
    const skippedEmpty = [];
    for (let cell = 0; cell < CELLS_PER_PERIOD; cell++) {
      const planTasks = getCellTasks(period, cell);
      const existing = getCellRecord(period, cell);
      if (!planTasks.length) { skippedEmpty.push(cell); continue; }
      if (existing && existing.actual) { skippedDone.push(cell); continue; }
      const range = getCellRange(period, cell);
      pending.push({
        cell,
        time: `${secondsToHHMM(range.start)}-${secondsToHHMM(range.end)}`,
        text: planTasks.map((t) => taskText(t)).join("; "),
      });
    }
    if (!pending.length) {
      toast(skippedDone.length ? "本时辰计划均已记录，无需同步" : "本时辰无计划可同步", "info");
      return;
    }
    // 预览确认弹窗
    const overlay = document.createElement("div");
    overlay.className = "modal-overlay sync-confirm-overlay";
    overlay.style.cssText = "position:fixed;inset:0;background:var(--overlay);z-index:1000;display:flex;align-items:center;justify-content:center;padding:16px;";
    const dialog = document.createElement("div");
    dialog.className = "sync-confirm-dialog";
    dialog.style.cssText = "background:var(--bg-card);border:1px solid var(--border);border-radius:var(--radius);padding:18px;max-width:460px;width:100%;max-height:90vh;overflow:auto;animation:fadeUp 0.25s ease;";
    const listHtml = pending.map((p, i) => `
      <li class="sync-item" style="display:flex;gap:8px;padding:8px 10px;border-radius:6px;background:var(--bg-tertiary);margin-bottom:6px;align-items:flex-start;">
        <span class="sync-idx" style="flex-shrink:0;width:20px;height:20px;border-radius:50%;background:var(--accent);color:#fff;font-size:11px;display:flex;align-items:center;justify-content:center;margin-top:1px;">${i + 1}</span>
        <div style="flex:1;min-width:0;">
          <div style="font-size:11px;color:var(--text-muted);margin-bottom:2px;">⏱ ${p.time}</div>
          <div style="font-size:13px;color:var(--text-primary);word-break:break-word;">${escapeHtml(p.text)}</div>
        </div>
      </li>`).join("");
    const skipInfo = (skippedDone.length || skippedEmpty.length)
      ? `<div style="font-size:11px;color:var(--text-muted);margin-top:10px;padding:8px;background:var(--bg-hover);border-radius:6px;">${
        skippedDone.length ? `✓ 已有记录跳过 ${skippedDone.length} 格` : ""
      }${skippedDone.length && skippedEmpty.length ? " · " : ""}${
        skippedEmpty.length ? `○ 无计划跳过 ${skippedEmpty.length} 格` : ""
      }</div>` : "";
    dialog.innerHTML = `
      <h3 style="font-size:15px;margin-bottom:6px;color:var(--accent-light);">⬇ 同步计划到记录</h3>
      <p style="font-size:12px;color:var(--text-secondary);margin-bottom:12px;">将以下 <b style="color:var(--accent-light);">${pending.length}</b> 格计划任务复制为已完成记录（已记录的格子保持不变）。</p>
      <ul style="list-style:none;padding:0;margin:0;max-height:40vh;overflow:auto;">${listHtml}</ul>
      ${skipInfo}
      <div style="display:flex;gap:8px;justify-content:flex-end;margin-top:14px;">
        <button id="syncCancel" style="padding:8px 14px;border-radius:6px;background:var(--bg-tertiary);color:var(--text-secondary);font-size:12px;">取消</button>
        <button id="syncOk" style="padding:8px 18px;border-radius:6px;background:linear-gradient(135deg,var(--accent),var(--accent-light));color:#fff;font-weight:600;font-size:12px;">✓ 确认同步 ${pending.length} 格</button>
      </div>
    `;
    overlay.appendChild(dialog);
    document.body.appendChild(overlay);
    const close = () => {
      overlay.style.animation = "toastOut 0.2s ease forwards";
      setTimeout(() => overlay.remove(), 200);
    };
    dialog.querySelector("#syncCancel").addEventListener("click", close);
    overlay.addEventListener("click", (e) => { if (e.target === overlay) close(); });
    dialog.querySelector("#syncOk").addEventListener("click", () => {
      let count = 0;
      for (const p of pending) {
        const planTasks = getCellTasks(period, p.cell);
        setCellRecord(period, p.cell, {
          spent: "~" + Math.round(SECONDS_PER_CELL / 60) + "分钟",
          actual: planTasks.map((t) => taskText(t)).join("; "),
          note: ""
        });
        count++;
      }
      renderRecord();
      toast(`已同步 ${count} 格计划到记录`, "success");
      close();
    });
  });
  if (el.clearPeriodRecordBtn) el.clearPeriodRecordBtn.addEventListener("click", () => {
    if (!confirm("清空本时辰所有记录？")) return;
    const period = state.activePeriod;
    if (!state.records[state.currentDate]) return;
    for (let cell = 0; cell < CELLS_PER_PERIOD; cell++) {
      delete state.records[state.currentDate][period + "-" + cell];
    }
    save(RECORD_KEY, state.records);
    renderRecord();
    toast("本时辰记录已清空", "info");
  });
  if (el.clearDayRecordBtn) el.clearDayRecordBtn.addEventListener("click", () => {
    if (!confirm("清空今日所有记录？（不影响计划和复盘）")) return;
    delete state.records[state.currentDate];
    save(RECORD_KEY, state.records);
    renderRecord();
    toast("今日记录已清空", "info");
  });
  if (el.goReviewFromRecord) el.goReviewFromRecord.addEventListener("click", () => {
    setRealm("review");
  });
  // 记录笔记本（弹窗 UI）+ 持续事项（快速记录）
  setupNotebookEvents();
  setupOngoingEvents();
  if (el.goRecordFromPlan) el.goRecordFromPlan.addEventListener("click", () => setRealm("record"));
  if (el.goReviewFromPlan) el.goReviewFromPlan.addEventListener("click", () => setRealm("review"));
  // ❓ 提问解析库（底部快捷条入口 + 弹窗交互 + 解析/渲染）
  initQABank();
  // 底部浮动快捷条（提问/收集箱/孵化）
  if (el.realmFab) {
    // 收集箱入口：点击跳转到收集箱弹窗
    const fabInbox = document.getElementById("realmFabInbox");
    if (fabInbox) fabInbox.addEventListener("click", openInbox);
  }
  // 三才页左右滑动手势切换
  if (el.realmContainer) {
    let sx = 0, sy = 0, st = 0, tracking = false;
    el.realmContainer.addEventListener("touchstart", (e) => {
      if (e.touches.length !== 1) return;
      sx = e.touches[0].clientX; sy = e.touches[0].clientY; st = Date.now();
      tracking = true;
    }, { passive: true });
    el.realmContainer.addEventListener("touchend", (e) => {
      if (!tracking) return;
      tracking = false;
      const dx = e.changedTouches[0].clientX - sx;
      const dy = e.changedTouches[0].clientY - sy;
      const dt = Date.now() - st;
      if (Math.abs(dx) > 60 && Math.abs(dx) > Math.abs(dy) * 1.5 && dt < 500) {
        const order = ["plan", "record", "review"];
        const idx = order.indexOf(state.realm);
        const next = dx < 0 ? Math.min(idx + 1, 2) : Math.max(idx - 1, 0);
        if (next !== idx) setRealm(order[next], next < idx);
      }
    }, { passive: true });
  }

  // ---------- 设置弹窗 ----------
